import React, { useState } from 'react';
import { Product } from '../types';
import { ADMIN_PASSWORD } from '../constants';

interface AdminPanelProps {
  products: Product[];
  onAddProduct: (product: Omit<Product, 'id'>) => void;
  onDeleteProduct: (id: string) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ products, onAddProduct, onDeleteProduct }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [newProduct, setNewProduct] = useState({ name: '', price: '', imageUrl: '' });

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
    } else {
      alert('وشەی نهێنی هەڵەیە');
    }
  };

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProduct.name || !newProduct.price || !newProduct.imageUrl) return;
    onAddProduct({
      name: newProduct.name,
      price: parseInt(newProduct.price),
      imageUrl: newProduct.imageUrl
    });
    setNewProduct({ name: '', price: '', imageUrl: '' });
  };

  if (!isAuthenticated) {
    return (
      <div className="max-w-md mx-auto mt-20 p-6 bg-white rounded-3xl shadow-lg border border-gray-100">
        <h2 className="text-2xl font-bold mb-6 text-center">چوونەژورەوەی بەڕێوەبەر</h2>
        <form onSubmit={handleLogin} className="space-y-4">
          <input 
            type="password" 
            placeholder="وشەی نهێنی (1234)" 
            className="w-full p-4 bg-gray-50 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-500 outline-none transition-all text-center"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <button className="w-full bg-orange-500 text-white py-4 rounded-2xl font-bold text-lg hover:bg-orange-600 transition-colors">
            چوونەژوورەوە
          </button>
        </form>
      </div>
    );
  }

  return (
    <div className="p-4 max-w-4xl mx-auto pb-32">
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 mb-8">
        <h2 className="text-xl font-bold mb-6">زیادکردنی بەرھەم</h2>
        <form onSubmit={handleAdd} className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <input 
              className="p-3 bg-gray-50 rounded-xl border border-gray-200 outline-none"
              placeholder="ناوی بەرھەم" 
              value={newProduct.name}
              onChange={e => setNewProduct({...newProduct, name: e.target.value})}
            />
            <input 
              className="p-3 bg-gray-50 rounded-xl border border-gray-200 outline-none"
              type="number" 
              placeholder="نرخ (د.ع)" 
              value={newProduct.price}
              onChange={e => setNewProduct({...newProduct, price: e.target.value})}
            />
            <input 
              className="p-3 bg-gray-50 rounded-xl border border-gray-200 outline-none"
              placeholder="بەستەری وێنە" 
              value={newProduct.imageUrl}
              onChange={e => setNewProduct({...newProduct, imageUrl: e.target.value})}
            />
          </div>
          <button className="w-full bg-green-600 text-white py-3 rounded-xl font-bold hover:bg-green-700 transition-colors">
            زیادکردنی بەرھەم
          </button>
        </form>
      </div>

      <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6">لیستی بەرھەمەکان</h2>
        <div className="space-y-3">
          {products.map(product => (
            <div key={product.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-2xl border border-gray-100">
              <div className="flex items-center gap-4">
                <img src={product.imageUrl} className="w-12 h-12 rounded-lg object-cover" />
                <div>
                  <h4 className="font-bold">{product.name}</h4>
                  <p className="text-sm text-gray-500">{product.price.toLocaleString()} دینار</p>
                </div>
              </div>
              <button 
                onClick={() => onDeleteProduct(product.id)}
                className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { CartItem } from '../types';

interface BottomNavProps {
  cart: CartItem[];
  onViewCart: () => void;
}

export const BottomNav: React.FC<BottomNavProps> = ({ cart, onViewCart }) => {
  if (cart.length === 0) return null;

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const count = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[92%] sm:max-w-md z-40 bg-gray-900 text-white p-4 rounded-3xl shadow-2xl flex items-center justify-between animate-bounce-subtle">
      <div className="flex items-center gap-3">
        <div className="bg-orange-500 w-10 h-10 rounded-2xl flex items-center justify-center font-bold relative">
          {count}
          <span className="absolute -top-1 -right-1 flex h-3 w-3">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-orange-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-3 w-3 bg-orange-500"></span>
          </span>
        </div>
        <div>
          <p className="text-xs text-gray-400 font-medium">کۆی گشتی</p>
          <p className="font-bold text-lg">{total.toLocaleString()} د.ع</p>
        </div>
      </div>
      <button 
        onClick={onViewCart}
        className="bg-orange-500 px-6 py-3 rounded-2xl font-bold hover:bg-orange-600 transition-colors active:scale-95"
      >
        بینینی سەبەتە
      </button>
      <style>{`
        @keyframes bounce-subtle {
          0%, 100% { transform: translate(-50%, 0); }
          50% { transform: translate(-50%, -4px); }
        }
        .animate-bounce-subtle {
          animation: bounce-subtle 2s infinite ease-in-out;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { Product, CartItem, ViewState } from './types';
import { getStoredProducts, saveProducts } from './services/storage';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  useEffect(() => {
    setProducts(getStoredProducts());
  }, []);

  const handleToggleAdmin = useCallback(() => {
    setView(prev => prev === 'MENU' ? 'ADMIN' : 'MENU');
  }, []);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id 
          ? { ...item, quantity: item.quantity + 1 }
          : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const addProduct = (p: Omit<Product, 'id'>) => {
    const newProducts = [...products, { ...p, id: Date.now().toString() }];
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const deleteProduct = (id: string) => {
    const newProducts = products.filter(p => p.id !== id);
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header currentView={view} onToggleAdmin={handleToggleAdmin} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <div className="max-w-6xl mx-auto px-4 py-6">
            <div className="mb-6">
              <h2 className="text-2xl font-bold text-gray-800">تامی ڕەسەن</h2>
              <p className="text-gray-500">خۆشترین خواردنەکان بە کوالێتی بەرز</p>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
              {products.map(product => (
                <ProductCard 
                  key={product.id} 
                  product={product} 
                  onAddToCart={addToCart} 
                />
              ))}
            </div>

            {products.length === 0 && (
              <div className="text-center py-20 text-gray-400">
                هیچ بەرھەمێک بەردەست نییە
              </div>
            )}
          </div>
        ) : (
          <AdminPanel 
            products={products} 
            onAddProduct={addProduct} 
            onDeleteProduct={deleteProduct} 
          />
        )}
      </main>

      {view === 'MENU' && (
        <BottomNav 
          cart={cart} 
          onViewCart={() => setIsCartOpen(true)} 
        />
      )}

      <CartModal 
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        cart={cart}
        onUpdateQuantity={updateQuantity}
        onRemove={removeFromCart}
      />

      <footer className="bg-white border-t py-8 text-center text-gray-400 text-sm mt-10">
        <p>© 2024 چێشتخانەی خێرا. هەموو مافەکان پارێزراوە.</p>
      </footer>
    </div>
  );
};

export default App;

