import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { CategoryBar } from './components/CategoryBar';
import { Product, CartItem, ViewState, Category, OrderLog } from './types';
import { 
  getStoredProducts, 
  saveProducts, 
  getStoredCategories, 
  saveCategories, 
  getSoundPreference, 
  saveSoundPreference,
  getStoredWhatsApp,
  saveWhatsApp,
  getOrderLogs,
  addOrderLog
} from './services/storage';
import { ADD_TO_CART_SOUND_URL } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [isSoundEnabled, setIsSoundEnabled] = useState(true);
  const [whatsappNumber, setWhatsappNumber] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    setProducts(getStoredProducts());
    setCategories(getStoredCategories());
    setIsSoundEnabled(getSoundPreference());
    setWhatsappNumber(getStoredWhatsApp());
    setOrderLogs(getOrderLogs());

    audioRef.current = new Audio(ADD_TO_CART_SOUND_URL);
    audioRef.current.volume = 0.4;
  }, []);

  const handleToggleAdmin = useCallback(() => {
    setView(prev => prev === 'MENU' ? 'ADMIN' : 'MENU');
  }, []);

  const handleToggleSound = (enabled: boolean) => {
    setIsSoundEnabled(enabled);
    saveSoundPreference(enabled);
  };

  const handleUpdateWhatsApp = (num: string) => {
    setWhatsappNumber(num);
    saveWhatsApp(num);
  };

  const handleLogOrder = (log: OrderLog) => {
    addOrderLog(log);
    setOrderLogs(prev => [log, ...prev].slice(0, 50));
  };

  const filteredProducts = useMemo(() => {
    if (selectedCategory === 'all') return products;
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const playAddSound = () => {
    if (isSoundEnabled && audioRef.current) {
      const sound = audioRef.current.cloneNode() as HTMLAudioElement;
      sound.volume = 0.4;
      sound.play().catch(e => console.debug("Sound playback blocked:", e));
    }
  };

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    playAddSound();
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id && item.selectedSize === size);
      if (existing) {
        return prev.map(item => (item.id === product.id && item.selectedSize === size)
          ? { ...item, quantity: item.quantity + 1 }
          : item
        );
      }
      return [...prev, { ...product, quantity: 1, selectedSize: size }];
    });
  };

  const updateQuantity = (id: string, delta: number, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.filter(item => !(item.id === id && item.selectedSize === size)));
  };

  const addProduct = (p: Omit<Product, 'id'>) => {
    const newProducts = [...products, { ...p, id: Date.now().toString() }];
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const updateProduct = (p: Product) => {
    const newProducts = products.map(prod => prod.id === p.id ? p : prod);
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const deleteProduct = (id: string) => {
    const newProducts = products.filter(p => p.id !== id);
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const addCategory = (c: Omit<Category, 'id'>) => {
    const newCats = [...categories, { ...c, id: Date.now().toString() }];
    setCategories(newCats);
    saveCategories(newCats);
  };

  const deleteCategory = (id: string) => {
    const newCats = categories.filter(c => c.id !== id);
    setCategories(newCats);
    saveCategories(newCats);
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header currentView={view} onToggleAdmin={handleToggleAdmin} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <CategoryBar 
              categories={categories}
              selectedCategoryId={selectedCategory} 
              onSelectCategory={setSelectedCategory} 
            />

            <div className="max-w-6xl mx-auto px-4 py-2">
              <div className="mb-6">
                <h2 className="text-2xl font-bold text-gray-800">تامی ڕەسەن</h2>
                <p className="text-gray-500">خۆشترین خواردنەکان بە کوالێتی بەرز</p>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 animate-in fade-in duration-500 pb-24">
                {filteredProducts.map(product => (
                  <ProductCard 
                    key={product.id} 
                    product={product} 
                    onAddToCart={addToCart} 
                  />
                ))}
              </div>

              {filteredProducts.length === 0 && (
                <div className="text-center py-20 flex flex-col items-center gap-4">
                  <div className="bg-gray-100 p-6 rounded-full">
                    <svg className="w-12 h-12 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.172 9.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                  <p className="text-gray-400 font-medium">لەم بەشەدا هیچ بەرھەمێک نییە</p>
                </div>
              )}
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} 
            categories={categories}
            isSoundEnabled={isSoundEnabled}
            whatsappNumber={whatsappNumber}
            orderLogs={orderLogs}
            onAddProduct={addProduct} 
            onUpdateProduct={updateProduct}
            onDeleteProduct={deleteProduct} 
            onAddCategory={addCategory}
            onDeleteCategory={deleteCategory}
            onToggleSound={handleToggleSound}
            onUpdateWhatsApp={handleUpdateWhatsApp}
          />
        )}
      </main>

      {view === 'MENU' && (
        <BottomNav 
          cart={cart} 
          onViewCart={() => setIsCartOpen(true)} 
        />
      )}

      <CartModal 
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        cart={cart}
        whatsappNumber={whatsappNumber}
        onUpdateQuantity={updateQuantity}
        onRemove={removeFromCart}
        onOrderLogged={handleLogOrder}
      />

      <footer className="bg-white border-t py-8 text-center text-gray-400 text-sm mt-10">
        <p>© 2024 چێشتخانەی خێرا. هەموو مافەکان پارێزراوە.</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { CartItem, OrderLog } from '../types';

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  whatsappNumber: string;
  onUpdateQuantity: (id: string, delta: number, size?: 'S' | 'M' | 'L') => void;
  onRemove: (id: string, size?: 'S' | 'M' | 'L') => void;
  onOrderLogged: (log: OrderLog) => void;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  whatsappNumber,
  onUpdateQuantity, 
  onRemove,
  onOrderLogged
}) => {
  const getItemPrice = (item: CartItem) => {
    if (item.category !== 'pizza' || !item.selectedSize) return item.price;
    if (item.selectedSize === 'M') return item.priceM || (item.price + 2000);
    if (item.selectedSize === 'L') return item.priceL || (item.price + 4000);
    return item.price;
  };

  const total = cart.reduce((acc, item) => acc + (getItemPrice(item) * item.quantity), 0);

  const handleOrder = () => {
    if (cart.length === 0) return;

    const log: OrderLog = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      items: cart.map(i => `${i.quantity}x ${i.name} ${i.selectedSize ? `(${i.selectedSize})` : ''}`),
      total: total
    };
    onOrderLogged(log);

    let message = "سڵاو، دەمەوێت ئەم داواکارییە بکەم:\n\n";
    cart.forEach(item => {
      const sizeLabel = item.selectedSize === 'S' ? 'بچووک' : item.selectedSize === 'M' ? 'ناوەند' : item.selectedSize === 'L' ? 'گەورە' : '';
      const itemTotal = getItemPrice(item) * item.quantity;
      // Updated formatting: "2x Burger - 10,000 IQD" style
      message += `• ${item.quantity}x ${item.name} ${sizeLabel ? `[${sizeLabel}]` : ''} - ${itemTotal.toLocaleString()} IQD\n`;
    });
    message += `\nکۆی گشتی: ${total.toLocaleString()} دینار`;

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/${whatsappNumber}?text=${encodedMessage}`, '_blank');
  };

  if (!isOpen) return null;

  const getSizeName = (size?: string) => {
    if (size === 'S') return 'بچووک';
    if (size === 'M') return 'ناوەند';
    if (size === 'L') return 'گەورە';
    return '';
  };

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/50 transition-opacity duration-300">
      <div 
        className="absolute inset-0" 
        onClick={onClose} 
      />
      <div className="bg-white rounded-t-3xl h-[85vh] w-full flex flex-col relative animate-slide-up shadow-2xl overflow-hidden">
        <div className="p-4 border-b flex justify-between items-center bg-white sticky top-0 z-10">
          <h2 className="text-xl font-bold text-black">داواکارییەکانت</h2>
          <button onClick={onClose} className="p-2 text-gray-400 hover:text-black transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex-grow overflow-y-auto p-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400">
              <svg className="w-16 h-16 mb-4 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
              </svg>
              <p className="font-bold">سەبەتەکەت چۆڵە</p>
            </div>
          ) : (
            <div className="space-y-4">
              {cart.map((item, index) => (
                <div key={`${item.id}-${item.selectedSize || 'none'}-${index}`} className="flex gap-4 items-center bg-gray-50 p-4 rounded-3xl border border-gray-100 shadow-sm transition-all">
                  <img src={item.imageUrl} className="w-20 h-20 rounded-2xl object-cover shadow-sm" />
                  <div className="flex-grow">
                    <h3 className="font-bold text-black text-lg">{item.name}</h3>
                    {item.selectedSize && (
                      <span className="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-md font-bold inline-block mb-1">
                        قیاس: {getSizeName(item.selectedSize)}
                      </span>
                    )}
                    <p className="text-orange-600 font-bold">{(getItemPrice(item) * item.quantity).toLocaleString()} د.ع</p>
                    <div className="flex items-center gap-4 mt-3">
                      <button 
                        onClick={() => {
                          if (item.quantity === 1) {
                            if (window.confirm('ئایا دڵنیایت لە لابردنی ئەم خواردنە؟')) {
                              onRemove(item.id, item.selectedSize);
                            }
                          } else {
                            onUpdateQuantity(item.id, -1, item.selectedSize);
                          }
                        }}
                        className="w-10 h-10 rounded-full border-2 border-gray-200 flex items-center justify-center text-black text-2xl font-bold bg-white hover:bg-gray-100 active:scale-90 transition-all shadow-sm"
                      >-</button>
                      <span className="font-black text-black w-8 text-center text-xl">{item.quantity}</span>
                      <button 
                        onClick={() => onUpdateQuantity(item.id, 1, item.selectedSize)}
                        className="w-10 h-10 rounded-full border-2 border-gray-200 flex items-center justify-center text-black text-2xl font-bold bg-white hover:bg-gray-100 active:scale-90 transition-all shadow-sm"
                      >+</button>
                    </div>
                  </div>
                  <button onClick={() => onRemove(item.id, item.selectedSize)} className="text-red-400 hover:text-red-600 p-2 transition-colors">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="p-6 border-t bg-white sticky bottom-0 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
          <div className="flex justify-between items-center mb-6 px-2">
            <span className="text-gray-500 font-bold text-lg">کۆی گشتی</span>
            <span className="text-3xl font-black text-black">{total.toLocaleString()} د.ع</span>
          </div>
          <button 
            disabled={cart.length === 0}
            onClick={handleOrder}
            className="w-full bg-green-600 hover:bg-green-700 disabled:opacity-50 text-white py-5 rounded-3xl font-bold text-xl flex items-center justify-center gap-3 transition-all active:scale-[0.98] shadow-lg shadow-green-100"
          >
            داواکردن لە واتساپ
            <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24">
              <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.414 0 .018 5.393 0 12.029a11.791 11.791 0 001.591 5.919L0 24l6.117-1.604a11.782 11.782 0 005.925 1.587h.005c6.634 0 12.032-5.391 12.036-12.027a11.795 11.795 0 00-3.497-8.474"/>
            </svg>
          </button>
        </div>
      </div>
      <style>{`
        @keyframes slide-up {
          from { transform: translateY(100%); }
          to { transform: translateY(0); }
        }
        .animate-slide-up {
          animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }
      `}</style>
    </div>
  );
};

export interface Category {
  id: string;
  name: string;
  imageUrl: string;
}

export interface Product {
  id: string;
  name: string;
  price: number; // Base price (Small)
  priceM?: number;
  priceL?: number;
  imageUrl: string;
  category: string;
}

export interface CartItem extends Product {
  quantity: number;
  selectedSize?: 'S' | 'M' | 'L';
  note?: string;
}

export interface OrderLog {
  id: string;
  timestamp: number;
  items: string[];
  total: number;
}

export type ViewState = 'MENU' | 'ADMIN';
export type AdminSubView = 'DASHBOARD' | 'PRODUCTS' | 'CATEGORIES' | 'ORDERS' | 'SETTINGS';

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { CategoryBar } from './components/CategoryBar';
import { Product, CartItem, ViewState, Category, OrderLog } from './types';
import { 
  getStoredProducts, 
  saveProducts, 
  getStoredCategories, 
  saveCategories, 
  getSoundPreference, 
  saveSoundPreference,
  getStoredWhatsApp,
  saveWhatsApp,
  getOrderLogs,
  addOrderLog
} from './services/storage';
import { ADD_TO_CART_SOUND_URL } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [isSoundEnabled, setIsSoundEnabled] = useState(true);
  const [whatsappNumber, setWhatsappNumber] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    setProducts(getStoredProducts());
    setCategories(getStoredCategories());
    setIsSoundEnabled(getSoundPreference());
    setWhatsappNumber(getStoredWhatsApp());
    setOrderLogs(getOrderLogs());

    audioRef.current = new Audio(ADD_TO_CART_SOUND_URL);
    audioRef.current.volume = 0.4;
  }, []);

  const handleToggleAdmin = useCallback(() => {
    setView(prev => prev === 'MENU' ? 'ADMIN' : 'MENU');
  }, []);

  const handleToggleSound = (enabled: boolean) => {
    setIsSoundEnabled(enabled);
    saveSoundPreference(enabled);
  };

  const handleUpdateWhatsApp = (num: string) => {
    setWhatsappNumber(num);
    saveWhatsApp(num);
  };

  const handleLogOrder = (log: OrderLog) => {
    addOrderLog(log);
    setOrderLogs(prev => [log, ...prev].slice(0, 50));
  };

  const filteredProducts = useMemo(() => {
    if (selectedCategory === 'all') return products;
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const playAddSound = () => {
    if (isSoundEnabled && audioRef.current) {
      const sound = audioRef.current.cloneNode() as HTMLAudioElement;
      sound.volume = 0.4;
      sound.play().catch(e => console.debug("Sound playback blocked:", e));
    }
  };

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    playAddSound();
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id && item.selectedSize === size);
      if (existing) {
        return prev.map(item => (item.id === product.id && item.selectedSize === size)
          ? { ...item, quantity: item.quantity + 1 }
          : item
        );
      }
      return [...prev, { ...product, quantity: 1, selectedSize: size, note: '' }];
    });
  };

  const updateQuantity = (id: string, delta: number, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const updateNote = (id: string, note: string, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        return { ...item, note };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.filter(item => !(item.id === id && item.selectedSize === size)));
  };

  const addProduct = (p: Omit<Product, 'id'>) => {
    const newProducts = [...products, { ...p, id: Date.now().toString() }];
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const updateProduct = (p: Product) => {
    const newProducts = products.map(prod => prod.id === p.id ? p : prod);
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const deleteProduct = (id: string) => {
    const newProducts = products.filter(p => p.id !== id);
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const addCategory = (c: Omit<Category, 'id'>) => {
    const newCats = [...categories, { ...c, id: Date.now().toString() }];
    setCategories(newCats);
    saveCategories(newCats);
  };

  const deleteCategory = (id: string) => {
    const newCats = categories.filter(c => c.id !== id);
    setCategories(newCats);
    saveCategories(newCats);
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header currentView={view} onToggleAdmin={handleToggleAdmin} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <CategoryBar 
              categories={categories}
              selectedCategoryId={selectedCategory} 
              onSelectCategory={setSelectedCategory} 
            />

            <div className="max-w-6xl mx-auto px-4 py-2">
              <div className="mb-6">
                <h2 className="text-2xl font-bold text-gray-800">تامی ڕەسەن</h2>
                <p className="text-gray-500">خۆشترین خواردنەکان بە کوالێتی بەرز</p>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 animate-in fade-in duration-500 pb-24">
                {filteredProducts.map(product => (
                  <ProductCard 
                    key={product.id} 
                    product={product} 
                    onAddToCart={addToCart} 
                  />
                ))}
              </div>

              {filteredProducts.length === 0 && (
                <div className="text-center py-20 flex flex-col items-center gap-4">
                  <div className="bg-gray-100 p-6 rounded-full">
                    <svg className="w-12 h-12 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.172 9.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                  <p className="text-gray-400 font-medium">لەم بەشەدا هیچ بەرھەمێک نییە</p>
                </div>
              )}
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} 
            categories={categories}
            isSoundEnabled={isSoundEnabled}
            whatsappNumber={whatsappNumber}
            orderLogs={orderLogs}
            onAddProduct={addProduct} 
            onUpdateProduct={updateProduct}
            onDeleteProduct={deleteProduct} 
            onAddCategory={addCategory}
            onDeleteCategory={deleteCategory}
            onToggleSound={handleToggleSound}
            onUpdateWhatsApp={handleUpdateWhatsApp}
          />
        )}
      </main>

      {view === 'MENU' && (
        <BottomNav 
          cart={cart} 
          onViewCart={() => setIsCartOpen(true)} 
        />
      )}

      <CartModal 
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        cart={cart}
        whatsappNumber={whatsappNumber}
        onUpdateQuantity={updateQuantity}
        onUpdateNote={updateNote}
        onRemove={removeFromCart}
        onOrderLogged={handleLogOrder}
      />

      <footer className="bg-white border-t py-8 text-center text-gray-400 text-sm mt-10">
        <p>© 2024 چێشتخانەی خێرا. هەموو مافەکان پارێزراوە.</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { CartItem, OrderLog } from '../types';

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  whatsappNumber: string;
  onUpdateQuantity: (id: string, delta: number, size?: 'S' | 'M' | 'L') => void;
  onUpdateNote: (id: string, note: string, size?: 'S' | 'M' | 'L') => void;
  onRemove: (id: string, size?: 'S' | 'M' | 'L') => void;
  onOrderLogged: (log: OrderLog) => void;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  whatsappNumber,
  onUpdateQuantity,
  onUpdateNote,
  onRemove,
  onOrderLogged
}) => {
  const getItemPrice = (item: CartItem) => {
    if (item.category !== 'pizza' || !item.selectedSize) return item.price;
    if (item.selectedSize === 'M') return item.priceM || (item.price + 2000);
    if (item.selectedSize === 'L') return item.priceL || (item.price + 4000);
    return item.price;
  };

  const total = cart.reduce((acc, item) => acc + (getItemPrice(item) * item.quantity), 0);

  const handleOrder = () => {
    if (cart.length === 0) return;

    const log: OrderLog = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      items: cart.map(i => `${i.quantity}x ${i.name} ${i.selectedSize ? `(${i.selectedSize})` : ''}`),
      total: total
    };
    onOrderLogged(log);

    let message = "سڵاو، دەمەوێت ئەم داواکارییە بکەم:\n\n";
    cart.forEach(item => {
      const sizeLabel = item.selectedSize === 'S' ? 'بچووک' : item.selectedSize === 'M' ? 'ناوەند' : item.selectedSize === 'L' ? 'گەورە' : '';
      const itemTotal = getItemPrice(item) * item.quantity;
      const noteText = item.note ? ` (Note: ${item.note})` : '';
      message += `• ${item.quantity}x ${item.name} ${sizeLabel ? `[${sizeLabel}]` : ''}${noteText} - ${itemTotal.toLocaleString()} IQD\n`;
    });
    message += `\nکۆی گشتی: ${total.toLocaleString()} دینار`;

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/${whatsappNumber}?text=${encodedMessage}`, '_blank');
  };

  if (!isOpen) return null;

  const getSizeName = (size?: string) => {
    if (size === 'S') return 'بچووک';
    if (size === 'M') return 'ناوەند';
    if (size === 'L') return 'گەورە';
    return '';
  };

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/50 transition-opacity duration-300">
      <div 
        className="absolute inset-0" 
        onClick={onClose} 
      />
      <div className="bg-white rounded-t-3xl h-[85vh] w-full flex flex-col relative animate-slide-up shadow-2xl overflow-hidden">
        <div className="p-4 border-b flex justify-between items-center bg-white sticky top-0 z-10">
          <h2 className="text-xl font-bold text-black">داواکارییەکانت</h2>
          <button onClick={onClose} className="p-2 text-gray-400 hover:text-black transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex-grow overflow-y-auto p-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400">
              <svg className="w-16 h-16 mb-4 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
              </svg>
              <p className="font-bold">سەبەتەکەت چۆڵە</p>
            </div>
          ) : (
            <div className="space-y-4">
              {cart.map((item, index) => (
                <div key={`${item.id}-${item.selectedSize || 'none'}-${index}`} className="flex flex-col gap-2 bg-gray-50 p-4 rounded-3xl border border-gray-100 shadow-sm transition-all">
                  <div className="flex gap-4 items-center">
                    <img src={item.imageUrl} className="w-20 h-20 rounded-2xl object-cover shadow-sm" />
                    <div className="flex-grow">
                      <h3 className="font-bold text-black text-lg">{item.name}</h3>
                      {item.selectedSize && (
                        <span className="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-md font-bold inline-block mb-1">
                          قیاس: {getSizeName(item.selectedSize)}
                        </span>
                      )}
                      <p className="text-orange-600 font-bold">{(getItemPrice(item) * item.quantity).toLocaleString()} د.ع</p>
                      <div className="flex items-center gap-4 mt-3">
                        <button 
                          onClick={() => {
                            if (item.quantity === 1) {
                              if (window.confirm('ئایا دڵنیایت لە لابردنی ئەم خواردنە؟')) {
                                onRemove(item.id, item.selectedSize);
                              }
                            } else {
                              onUpdateQuantity(item.id, -1, item.selectedSize);
                            }
                          }}
                          className="w-10 h-10 rounded-full border-2 border-gray-200 flex items-center justify-center text-black text-2xl font-bold bg-white hover:bg-gray-100 active:scale-90 transition-all shadow-sm"
                        >-</button>
                        <span className="font-black text-black w-8 text-center text-xl">{item.quantity}</span>
                        <button 
                          onClick={() => onUpdateQuantity(item.id, 1, item.selectedSize)}
                          className="w-10 h-10 rounded-full border-2 border-gray-200 flex items-center justify-center text-black text-2xl font-bold bg-white hover:bg-gray-100 active:scale-90 transition-all shadow-sm"
                        >+</button>
                      </div>
                    </div>
                    <button onClick={() => onRemove(item.id, item.selectedSize)} className="text-red-400 hover:text-red-600 p-2 transition-colors self-start">
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                      </svg>
                    </button>
                  </div>

                  {/* Notes Field */}
                  <div className="mt-2">
                    <input 
                      type="text"
                      value={item.note || ''}
                      onChange={(e) => onUpdateNote(item.id, e.target.value, item.selectedSize)}
                      placeholder="زیادکردنی تێبینی..."
                      className="w-full p-3 bg-white border border-gray-200 rounded-xl text-sm text-black font-bold outline-none focus:border-orange-500 transition-all placeholder:text-gray-300 placeholder:font-normal"
                    />
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="p-6 border-t bg-white sticky bottom-0 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
          <div className="flex justify-between items-center mb-6 px-2">
            <span className="text-gray-500 font-bold text-lg">کۆی گشتی</span>
            <span className="text-3xl font-black text-black">{total.toLocaleString()} د.ع</span>
          </div>
          <button 
            disabled={cart.length === 0}
            onClick={handleOrder}
            className="w-full bg-green-600 hover:bg-green-700 disabled:opacity-50 text-white py-5 rounded-3xl font-bold text-xl flex items-center justify-center gap-3 transition-all active:scale-[0.98] shadow-lg shadow-green-100"
          >
            داواکردن لە واتساپ
            <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24">
              <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.414 0 .018 5.393 0 12.029a11.791 11.791 0 001.591 5.919L0 24l6.117-1.604a11.782 11.782 0 005.925 1.587h.005c6.634 0 12.032-5.391 12.036-12.027a11.795 11.795 0 00-3.497-8.474"/>
            </svg>
          </button>
        </div>
      </div>
      <style>{`
        @keyframes slide-up {
          from { transform: translateY(100%); }
          to { transform: translateY(0); }
        }
        .animate-slide-up {
          animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }
      `}</style>
    </div>
  );
