import { Product, Category, OrderLog } from '../types';
import { DEFAULT_PRODUCTS, DEFAULT_CATEGORIES, WHATSAPP_NUMBER } from '../constants';

const PRODUCTS_KEY = 'fastfood_products_v1';
const CATEGORIES_KEY = 'fastfood_categories_v1';
const SOUND_KEY = 'fastfood_sound_enabled_v1';
const WHATSAPP_KEY = 'fastfood_whatsapp_v1';
const ORDERS_KEY = 'fastfood_orders_v1';
const IMGBB_KEY = 'fastfood_imgbb_key_v1';

export const getStoredProducts = (): Product[] => {
  const stored = localStorage.getItem(PRODUCTS_KEY);
  if (!stored) return DEFAULT_PRODUCTS;
  try {
    return JSON.parse(stored);
  } catch (e) {
    return DEFAULT_PRODUCTS;
  }
};

export const saveProducts = (products: Product[]) => {
  localStorage.setItem(PRODUCTS_KEY, JSON.stringify(products));
};

export const getStoredCategories = (): Category[] => {
  const stored = localStorage.getItem(CATEGORIES_KEY);
  if (!stored) return DEFAULT_CATEGORIES;
  try {
    return JSON.parse(stored);
  } catch (e) {
    return DEFAULT_CATEGORIES;
  }
};

export const saveCategories = (categories: Category[]) => {
  localStorage.setItem(CATEGORIES_KEY, JSON.stringify(categories));
};

export const getSoundPreference = (): boolean => {
  const stored = localStorage.getItem(SOUND_KEY);
  return stored === null ? true : stored === 'true';
};

export const saveSoundPreference = (enabled: boolean) => {
  localStorage.setItem(SOUND_KEY, enabled.toString());
};

export const getStoredWhatsApp = (): string => {
  return localStorage.getItem(WHATSAPP_KEY) || WHATSAPP_NUMBER;
};

export const saveWhatsApp = (num: string) => {
  localStorage.setItem(WHATSAPP_KEY, num);
};

export const getOrderLogs = (): OrderLog[] => {
  const stored = localStorage.getItem(ORDERS_KEY);
  return stored ? JSON.parse(stored) : [];
};

export const addOrderLog = (log: OrderLog) => {
  const logs = getOrderLogs();
  const updated = [log, ...logs].slice(0, 50); // Keep last 50
  localStorage.setItem(ORDERS_KEY, JSON.stringify(updated));
};

export const getStoredImgBBKey = (): string => {
  return localStorage.getItem(IMGBB_KEY) || '';
};

export const saveImgBBKey = (key: string) => {
  localStorage.setItem(IMGBB_KEY, key);
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { CategoryBar } from './components/CategoryBar';
import { Product, CartItem, ViewState, Category, OrderLog } from './types';
import { 
  getStoredProducts, 
  saveProducts, 
  getStoredCategories, 
  saveCategories, 
  getSoundPreference, 
  saveSoundPreference,
  getStoredWhatsApp,
  saveWhatsApp,
  getOrderLogs,
  addOrderLog,
  getStoredImgBBKey,
  saveImgBBKey
} from './services/storage';
import { ADD_TO_CART_SOUND_URL } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [isSoundEnabled, setIsSoundEnabled] = useState(true);
  const [whatsappNumber, setWhatsappNumber] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);
  const [imgbbKey, setImgbbKey] = useState('');

  // Location state
  const [autoLocationUrl, setAutoLocationUrl] = useState<string | null>(null);
  const [locationPermissionStatus, setLocationPermissionStatus] = useState<'prompt' | 'granted' | 'denied' | 'unknown'>('unknown');

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    setProducts(getStoredProducts());
    setCategories(getStoredCategories());
    setIsSoundEnabled(getSoundPreference());
    setWhatsappNumber(getStoredWhatsApp());
    setOrderLogs(getOrderLogs());
    setImgbbKey(getStoredImgBBKey());

    audioRef.current = new Audio(ADD_TO_CART_SOUND_URL);
    audioRef.current.volume = 0.4;

    // Automatic Location Request on Page Load
    const requestLocation = () => {
      if (!navigator.geolocation) return;

      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          setAutoLocationUrl(`https://www.google.com/maps?q=${latitude},${longitude}`);
          setLocationPermissionStatus('granted');
        },
        (error) => {
          if (error.code === error.PERMISSION_DENIED) {
            setLocationPermissionStatus('denied');
          }
        },
        { enableHighAccuracy: true, timeout: 10000 }
      );
    };

    // Check session storage to comply with "once per session" logic
    const hasRequestedThisSession = sessionStorage.getItem('location_requested_v1');
    if (!hasRequestedThisSession) {
      requestLocation();
      sessionStorage.setItem('location_requested_v1', 'true');
    }
  }, []);

  const handleToggleAdmin = useCallback(() => {
    setView(prev => prev === 'MENU' ? 'ADMIN' : 'MENU');
  }, []);

  const handleToggleSound = (enabled: boolean) => {
    setIsSoundEnabled(enabled);
    saveSoundPreference(enabled);
  };

  const handleUpdateWhatsApp = (num: string) => {
    setWhatsappNumber(num);
    saveWhatsApp(num);
  };

  const handleUpdateImgBBKey = (key: string) => {
    setImgbbKey(key);
    saveImgBBKey(key);
  };

  const handleLogOrder = (log: OrderLog) => {
    addOrderLog(log);
    setOrderLogs(prev => [log, ...prev].slice(0, 50));
  };

  const filteredProducts = useMemo(() => {
    if (selectedCategory === 'all') return products;
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const playAddSound = () => {
    if (isSoundEnabled && audioRef.current) {
      const sound = audioRef.current.cloneNode() as HTMLAudioElement;
      sound.volume = 0.4;
      sound.play().catch(e => console.debug("Sound playback blocked:", e));
    }
  };

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    playAddSound();
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id && item.selectedSize === size);
      if (existing) {
        return prev.map(item => (item.id === product.id && item.selectedSize === size)
          ? { ...item, quantity: item.quantity + 1 }
          : item
        );
      }
      return [...prev, { ...product, quantity: 1, selectedSize: size, note: '' }];
    });
  };

  const updateQuantity = (id: string, delta: number, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const updateNote = (id: string, note: string, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        return { ...item, note };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.filter(item => !(item.id === id && item.selectedSize === size)));
  };

  const addProduct = (p: Omit<Product, 'id'>) => {
    const newProducts = [...products, { ...p, id: Date.now().toString() }];
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const updateProduct = (p: Product) => {
    const newProducts = products.map(prod => prod.id === p.id ? p : prod);
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const deleteProduct = (id: string) => {
    const newProducts = products.filter(p => p.id !== id);
    setProducts(newProducts);
    saveProducts(newProducts);
  };

  const addCategory = (c: Omit<Category, 'id'>) => {
    const newCats = [...categories, { ...c, id: Date.now().toString() }];
    setCategories(newCats);
    saveCategories(newCats);
  };

  const deleteCategory = (id: string) => {
    const newCats = categories.filter(c => c.id !== id);
    setCategories(newCats);
    saveCategories(newCats);
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      <Header currentView={view} onToggleAdmin={handleToggleAdmin} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <CategoryBar 
              categories={categories}
              selectedCategoryId={selectedCategory} 
              onSelectCategory={setSelectedCategory} 
            />

            <div className="max-w-6xl mx-auto px-4 py-2">
              <div className="mb-6">
                <h2 className="text-2xl font-bold text-gray-800">تامی ڕەسەن</h2>
                <p className="text-gray-500">خۆشترین خواردنەکان بە کوالێتی بەرز</p>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 animate-in fade-in duration-500 pb-24">
                {filteredProducts.map(product => (
                  <ProductCard 
                    key={product.id} 
                    product={product} 
                    onAddToCart={addToCart} 
                  />
                ))}
              </div>

              {filteredProducts.length === 0 && (
                <div className="text-center py-20 flex flex-col items-center gap-4">
                  <div className="bg-gray-100 p-6 rounded-full">
                    <svg className="w-12 h-12 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.172 9.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                  <p className="text-gray-400 font-medium">لەم بەشەدا هیچ بەرھەمێک نییە</p>
                </div>
              )}
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} 
            categories={categories}
            isSoundEnabled={isSoundEnabled}
            whatsappNumber={whatsappNumber}
            imgbbKey={imgbbKey}
            orderLogs={orderLogs}
            onAddProduct={addProduct} 
            onUpdateProduct={updateProduct}
            onDeleteProduct={deleteProduct} 
            onAddCategory={addCategory}
            onDeleteCategory={deleteCategory}
            onToggleSound={handleToggleSound}
            onUpdateWhatsApp={handleUpdateWhatsApp}
            onUpdateImgBBKey={handleUpdateImgBBKey}
          />
        )}
      </main>

      {view === 'MENU' && (
        <BottomNav 
          cart={cart} 
          onViewCart={() => setIsCartOpen(true)} 
        />
      )}

      <CartModal 
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        cart={cart}
        whatsappNumber={whatsappNumber}
        onUpdateQuantity={updateQuantity}
        onUpdateNote={updateNote}
        onRemove={removeFromCart}
        onOrderLogged={handleLogOrder}
        initialLocationUrl={autoLocationUrl}
        locationPermissionStatus={locationPermissionStatus}
      />

      <footer className="bg-white border-t py-8 text-center text-gray-400 text-sm mt-10">
        <p>© 2024 چێشتخانەی خێرا. هەموو مافەکان پارێزراوە.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { ADMIN_PASSWORD } from '../constants';

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  whatsappNumber: string;
  imgbbKey: string;
  orderLogs: OrderLog[];
  onAddProduct: (product: Omit<Product, 'id'>) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddCategory: (category: Omit<Category, 'id'>) => void;
  onDeleteCategory: (id: string) => void;
  onToggleSound: (enabled: boolean) => void;
  onUpdateWhatsApp: (num: string) => void;
  onUpdateImgBBKey: (key: string) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  whatsappNumber,
  imgbbKey,
  orderLogs,
  onAddProduct, 
  onUpdateProduct,
  onDeleteProduct,
  onAddCategory,
  onDeleteCategory,
  onToggleSound,
  onUpdateWhatsApp,
  onUpdateImgBBKey
}) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);

  // Forms state
  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, priceM: string, priceL: string, imageUrl: string, category: string}>({ 
    name: '', price: '', priceM: '', priceL: '', imageUrl: '', category: categories[1]?.id || 'burgers' 
  });
  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [showConfirmDelete, setShowConfirmDelete] = useState<{type: 'P'|'C', id: string} | null>(null);

  const productFileRef = useRef<HTMLInputElement>(null);
  const categoryFileRef = useRef<HTMLInputElement>(null);

  // Analytics
  const stats = useMemo(() => {
    const totalOrders = orderLogs.length;
    const catCount: Record<string, number> = {};
    products.forEach(p => {
      catCount[p.category] = (catCount[p.category] || 0) + 1;
    });
    const popularCatId = Object.entries(catCount).sort((a,b) => b[1] - a[1])[0]?.[0];
    const popularCatName = categories.find(c => c.id === popularCatId)?.name || 'نادیار';

    return { totalProducts: products.length, totalOrders, popularCatName };
  }, [products, categories, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === ADMIN_PASSWORD) setIsAuthenticated(true);
    else alert('وشەی نهێنی هەڵەیە');
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    if (!imgbbKey) {
      alert('تکایە سەرەتا کلیلی ImgBB API لە ڕێکخستنەکان دابنێ.');
      return null;
    }

    setIsUploading(true);
    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${imgbbKey}`, {
        method: 'POST',
        body: formData,
      });
      const data = await response.json();
      if (data.success) {
        return data.data.url;
      } else {
        alert('هەڵەیەک لە بارکردنی وێنەکە ڕوویدا. دڵنیابەرەوە کلیلی API ڕاستە.');
        return null;
      }
    } catch (error) {
      console.error('Upload error:', error);
      alert('کێشەیەک لە پەیوەندی ڕوویدا.');
      return null;
    } finally {
      setIsUploading(false);
    }
  };

