const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [isSoundEnabled, setIsSoundEnabled] = useState(true);
  const [whatsappNumber, setWhatsappNumber] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);
  const [businessLogo, setBusinessLogo] = useState('');
  const [adminUser, setAdminUser] = useState<User | null>(null);

  // Browser Detection State
  const [isInAppBrowser, setIsInAppBrowser] = useState(false);

  // Location state
  const [autoLocationUrl, setAutoLocationUrl] = useState<string | null>(null);
  const [locationPermissionStatus, setLocationPermissionStatus] = useState<'prompt' | 'granted' | 'denied' | 'unknown'>('unknown');

  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    // 1. Browser Detection
    const ua = navigator.userAgent || navigator.vendor || (window as any).opera;
    const isFacebook = ua.indexOf("FBAN") > -1 || ua.indexOf("FBAV") > -1;
    const isMessenger = ua.indexOf("Messenger") > -1;
    if (isFacebook || isMessenger) setIsInAppBrowser(true);

    // 2. Auth State
    const unsubscribeAuth = onAuthStateChanged(auth, (user) => {
      setAdminUser(user);
    });

    // 3. Real-time Products
    const qProducts = query(collection(db, "products"), orderBy("name"));
    const unsubscribeProducts = onSnapshot(qProducts, (snapshot) => {
      const prods: Product[] = [];
      snapshot.forEach((doc) => prods.push({ id: doc.id, ...doc.data() } as Product));
      setProducts(prods);
    });

    // 4. Real-time Categories
    const qCategories = query(collection(db, "categories"), orderBy("name"));
    const unsubscribeCategories = onSnapshot(qCategories, (snapshot) => {
      const cats: Category[] = [{ id: 'all', name: 'هەموو', imageUrl: DEFAULT_CATEGORIES[0].imageUrl }];
      snapshot.forEach((doc) => cats.push({ id: doc.id, ...doc.data() } as Category));
      setCategories(cats);
    });

    // 5. Real-time Settings
    const unsubscribeSettings = onSnapshot(doc(db, "settings", "general"), (doc) => {
      if (doc.exists()) {
        const data = doc.data();
        setWhatsappNumber(data.whatsappNumber || '');
        setBusinessLogo(data.businessLogo || '');
        setIsSoundEnabled(data.isSoundEnabled ?? true);
      }
    });

    // 6. Real-time Order Logs
    const qOrders = query(collection(db, "orders"), orderBy("timestamp", "desc"));
    const unsubscribeOrders = onSnapshot(qOrders, (snapshot) => {
      const logs: OrderLog[] = [];
      snapshot.forEach((doc) => logs.push({ id: doc.id, ...doc.data() } as OrderLog));
      setOrderLogs(logs);
    });

    audioRef.current = new Audio(ADD_TO_CART_SOUND_URL);
    audioRef.current.volume = 0.4;

    // 7. Location Logic
    const hasRequestedThisSession = sessionStorage.getItem('location_requested_v1');
    if (!hasRequestedThisSession) {
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            const { latitude, longitude } = position.coords;
            setAutoLocationUrl(`https://www.google.com/maps?q=${latitude},${longitude}`);
            setLocationPermissionStatus('granted');
          },
          (error) => {
            if (error.code === 1) setLocationPermissionStatus('denied');
          },
          { enableHighAccuracy: true, timeout: 10000 }
        );
      }
      sessionStorage.setItem('location_requested_v1', 'true');
    }

    return () => {
      unsubscribeAuth();
      unsubscribeProducts();
      unsubscribeCategories();
      unsubscribeSettings();
      unsubscribeOrders();
    };
  }, []);

  const handleToggleAdmin = useCallback(() => {
    setView(prev => prev === 'MENU' ? 'ADMIN' : 'MENU');
  }, []);

  const filteredProducts = useMemo(() => {
    if (selectedCategory === 'all') return products;
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const playAddSound = () => {
    if (isSoundEnabled && audioRef.current) {
      const sound = audioRef.current.cloneNode() as HTMLAudioElement;
      sound.volume = 0.4;
      sound.play().catch(e => console.debug("Sound playback blocked:", e));
    }
  };

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    playAddSound();
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id && item.selectedSize === size);
      if (existing) {
        return prev.map(item => (item.id === product.id && item.selectedSize === size)
          ? { ...item, quantity: item.quantity + 1 }
          : item
        );
      }
      return [...prev, { ...product, quantity: 1, selectedSize: size, note: '' }];
    });
  };

  const updateQuantity = (id: string, delta: number, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const updateNote = (id: string, note: string, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        return { ...item, note };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, size?: 'S' | 'M' | 'L') => {
    setCart(prev => prev.filter(item => !(item.id === id && item.selectedSize === size)));
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      {isInAppBrowser && <InAppBrowserOverlay businessLogo={businessLogo} />}

      <Header 
        currentView={view} 
        onToggleAdmin={handleToggleAdmin} 
        businessLogo={businessLogo}
      />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <CategoryBar 
              categories={categories}
              selectedCategoryId={selectedCategory} 
              onSelectCategory={setSelectedCategory} 
            />

            <div className="max-w-6xl mx-auto px-4 py-2">
              <div className="mb-6">
                <h2 className="text-2xl font-bold text-gray-800">تامی ڕەسەن</h2>
                <p className="text-gray-500">خۆشترین خواردنەکان بە کوالێتی بەرز</p>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 animate-in fade-in duration-500 pb-24">
                {filteredProducts.map(product => (
                  <ProductCard 
                    key={product.id} 
                    product={product} 
                    onAddToCart={addToCart} 
                  />
                ))}
              </div>

              {filteredProducts.length === 0 && (
                <div className="text-center py-20 flex flex-col items-center gap-4">
                  <div className="bg-gray-100 p-6 rounded-full">
                    <svg className="w-12 h-12 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.172 9.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                  <p className="text-gray-400 font-medium">لەم بەشەدا هیچ بەرھەمێک نییە</p>
                </div>
              )}
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} 
            categories={categories}
            isSoundEnabled={isSoundEnabled}
            whatsappNumber={whatsappNumber}
            businessLogo={businessLogo}
            orderLogs={orderLogs}
            adminUser={adminUser}
          />
        )}
      </main>

      {view === 'MENU' && (
        <BottomNav 
          cart={cart} 
          onViewCart={() => setIsCartOpen(true)} 
        />
      )}

      <CartModal 
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        cart={cart}
        whatsappNumber={whatsappNumber}
        onUpdateQuantity={updateQuantity}
        onUpdateNote={updateNote}
        onRemove={removeFromCart}
        onOrderLogged={() => {}} // Logging is handled inside CartModal or we can move it to a service
        initialLocationUrl={autoLocationUrl}
        locationPermissionStatus={locationPermissionStatus}
      />

      <footer className="bg-white border-t py-8 text-center text-gray-400 text-sm mt-10">
        <p>© 2024 چێشتخانەی خێرا. هەموو مافەکان پارێزراوە.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { db, auth, storage } from '../firebase';
import { 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  setDoc 
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { 
  signInWithEmailAndPassword, 
  signOut, 
  User 
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-auth.js";
import { 
  ref, 
  uploadBytes, 
  getDownloadURL 
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-storage.js";

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  whatsappNumber: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  adminUser: User | null;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  whatsappNumber,
  businessLogo,
  orderLogs,
  adminUser
}) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Forms state
  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, priceM: string, priceL: string, imageUrl: string, category: string}>({ 
    name: '', price: '', priceM: '', priceL: '', imageUrl: '', category: categories[1]?.id || 'burgers' 
  });
  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [showConfirmDelete, setShowConfirmDelete] = useState<{type: 'P'|'C', id: string} | null>(null);

  const productFileRef = useRef<HTMLInputElement>(null);
  const categoryFileRef = useRef<HTMLInputElement>(null);
  const logoFileRef = useRef<HTMLInputElement>(null);

  // Analytics
  const stats = useMemo(() => {
    const totalOrders = orderLogs.length;
    const catCount: Record<string, number> = {};
    products.forEach(p => {
      catCount[p.category] = (catCount[p.category] || 0) + 1;
    });
    const popularCatId = Object.entries(catCount).sort((a,b) => b[1] - a[1])[0]?.[0];
    const popularCatName = categories.find(c => c.id === popularCatId)?.name || 'نادیار';
    return { totalProducts: products.length, totalOrders, popularCatName };
  }, [products, categories, orderLogs]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      await signInWithEmailAndPassword(auth, email, password);
    } catch (error: any) {
      alert('هەڵەیەک ڕوویدا: ' + error.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => signOut(auth);

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
    setIsUploading(true);
    try {
      const storageRef = ref(storage, `${folder}/${Date.now()}_${file.name}`);
      const snapshot = await uploadBytes(storageRef, file);
      return await getDownloadURL(snapshot.ref);
    } catch (error) {
      console.error('Upload error:', error);
      alert('کێشەیەک لە بارکردنی وێنە ڕوویدا.');
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  const handleProductImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = await uploadFile(file, 'products');
      if (url) setProductForm(prev => ({ ...prev, imageUrl: url }));
    }
  };

  const handleCategoryImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = await uploadFile(file, 'categories');
      if (url) setCategoryForm(prev => ({ ...prev, imageUrl: url }));
    }
  };

  const handleLogoChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = await uploadFile(file, 'branding');
      if (url) {
        await setDoc(doc(db, "settings", "general"), { businessLogo: url }, { merge: true });
      }
    }
  };

  const updateGeneralSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "general"), { [field]: value }, { merge: true });
  };

  const isPizzaCategorySelected = productForm.category === 'pizza';

  const renderDashboard = () => (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
          <div className="text-gray-400 text-sm font-bold mb-2">کۆی خواردنەکان</div>
          <div className="text-4xl font-black text-gray-900">{stats.totalProducts}</div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
          <div className="text-gray-400 text-sm font-bold mb-2">کۆی داواکارییەکان</div>
          <div className="text-4xl font-black text-green-600">{stats.totalOrders}</div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
          <div className="text-gray-400 text-sm font-bold mb-2">باوترین بەش</div>
          <div className="text-4xl font-black text-orange-600 line-clamp-1">{stats.popularCatName}</div>
        </div>
      </div>
    </div>
  );

  const renderProducts = () => (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
        <h3 className="font-bold text-gray-800 mb-6 flex items-center gap-2">
          {productForm.id ? 'دەستکاری بەرھەم' : 'زیادکردنی بەرھەمی نوێ'}
        </h3>
        <form onSubmit={async (e) => {
          e.preventDefault();
          const pData = {
            name: productForm.name,
            price: parseInt(productForm.price),
            imageUrl: productForm.imageUrl,
            category: productForm.category,
            priceM: productForm.priceM ? parseInt(productForm.priceM) : null,
            priceL: productForm.priceL ? parseInt(productForm.priceL) : null,
          };

          if (productForm.id) {
            await updateDoc(doc(db, "products", productForm.id), pData);
          } else {
            await addDoc(collection(db, "products"), pData);
          }
          setProductForm({ name: '', price: '', priceM: '', priceL: '', imageUrl: '', category: categories[0].id });
        }} className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            <input className="input-admin" placeholder="ناوی خواردن" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} required />
            <select className="input-admin" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value})}>
              {categories.filter(c => c.id !== 'all').map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            <input className="input-admin" type="number" placeholder={isPizzaCategorySelected ? "Small نرخی" : "نرخی سەرەکی"} value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
          </div>
          <div className="bg-gray-50 p-6 rounded-2xl border-2 border-dashed border-gray-200 text-center relative overflow-hidden">
            {productForm.imageUrl ? (
              <img src={productForm.imageUrl} className="w-32 h-32 object-cover rounded-2xl mx-auto" />
            ) : (
              <div className="text-gray-400">وێنە لێرە دابنێ</div>
            )}
            <input type="file" ref={productFileRef} onChange={handleProductImageChange} className="absolute inset-0 opacity-0 cursor-pointer" />
            {isUploading && <div className="absolute inset-0 bg-white/50 flex items-center justify-center">خەریکی بارکردنە...</div>}
          </div>
          {isPizzaCategorySelected && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <input className="input-admin" type="number" placeholder="Medium نرخی" value={productForm.priceM} onChange={e => setProductForm({...productForm, priceM: e.target.value})} />
              <input className="input-admin" type="number" placeholder="Large نرخی" value={productForm.priceL} onChange={e => setProductForm({...productForm, priceL: e.target.value})} />
            </div>
          )}
          <button disabled={isUploading} className="w-full bg-orange-600 text-white py-3 rounded-xl font-bold shadow-lg shadow-orange-100">
            {productForm.id ? 'گۆڕین' : 'زیادکردن'}
          </button>
        </form>
      </div>

      <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
        <h3 className="font-bold text-gray-800 mb-6">لیستی بەرھەمەکان</h3>
        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead>
              <tr className="border-b border-gray-100 text-gray-400 text-sm">
                <th className="pb-4 font-bold">وێنە</th>
                <th className="pb-4 font-bold">ناو</th>
                <th className="pb-4 font-bold">بەش</th>
                <th className="pb-4 font-bold">کردارەکان</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {products.map(p => (
                <tr key={p.id}>
                  <td className="py-4"><img src={p.imageUrl} className="w-12 h-12 rounded-xl object-cover" /></td>
                  <td className="py-4 font-bold">{p.name}</td>
                  <td className="py-4 text-gray-500">{categories.find(c => c.id === p.category)?.name}</td>
                  <td className="py-4">
                    <div className="flex gap-2">
                      <button onClick={() => setProductForm({...p, price: p.price.toString(), priceM: (p.priceM || '').toString(), priceL: (p.priceL || '').toString()})} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg">دەستکاری</button>
                      <button onClick={() => setShowConfirmDelete({type: 'P', id: p.id})} className="p-2 text-red-600 hover:bg-red-50 rounded-lg">سڕینەوە</button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );

  const renderCategories = () => (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
        <h3 className="font-bold text-gray-800 mb-6">بەشی نوێ</h3>
        <form onSubmit={async (e) => {
          e.preventDefault();
          await addDoc(collection(db, "categories"), categoryForm);
          setCategoryForm({ name: '', imageUrl: '' });
        }} className="space-y-4">
          <input className="input-admin w-full" placeholder="ناوی بەش" value={categoryForm.name} onChange={e => setCategoryForm({...categoryForm, name: e.target.value})} required />
          <div className="bg-gray-50 p-6 rounded-2xl border-2 border-dashed border-gray-200 text-center relative overflow-hidden">
            {categoryForm.imageUrl ? <img src={categoryForm.imageUrl} className="w-20 h-20 rounded-full mx-auto object-cover" /> : "وێنە"}
            <input type="file" ref={categoryFileRef} onChange={handleCategoryImageChange} className="absolute inset-0 opacity-0 cursor-pointer" />
          </div>
          <button disabled={isUploading} className="w-full bg-orange-600 text-white py-3 rounded-xl font-bold">زیادکردن</button>
        </form>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
        {categories.map(c => (
          <div key={c.id} className="bg-white p-4 rounded-3xl border border-gray-100 flex items-center justify-between group">
            <div className="flex items-center gap-4">
              <img src={c.imageUrl} className="w-12 h-12 rounded-full object-cover" />
              <span className="font-bold text-gray-800">{c.name}</span>
            </div>
            {c.id !== 'all' && (
              <button onClick={() => setShowConfirmDelete({type: 'C', id: c.id})} className="text-red-400 hover:text-red-600">سڕینەوە</button>
            )}
          </div>
        ))}
      </div>
    </div>
  );

  const renderSettings = () => (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
        <h3 className="font-bold text-gray-800 mb-6 text-orange-600">ڕێکخستنەکان</h3>
        <div className="space-y-6">
          <div className="flex flex-col gap-2">
            <label className="text-sm text-gray-500 font-bold px-1">لۆگۆی بازرگانی</label>
            <div className="bg-gray-50 p-6 rounded-2xl border-2 border-dashed border-gray-200 text-center relative overflow-hidden min-h-[160px] flex flex-col items-center justify-center">
              {businessLogo ? <img src={businessLogo} className="max-h-24 object-contain" /> : "بارکردن"}
              <input type="file" ref={logoFileRef} onChange={handleLogoChange} className="absolute inset-0 opacity-0 cursor-pointer" />
            </div>
          </div>
          <div className="flex flex-col gap-2">
            <label className="text-sm text-gray-500 font-bold px-1">ژمارەی واتساپ</label>
            <input className="input-admin w-full" value={whatsappNumber} onChange={e => updateGeneralSetting('whatsappNumber', e.target.value)} placeholder="964..." />
          </div>
          <div className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl">
            <span className="font-bold">دەنگی زیادکردن</span>
            <button onClick={() => updateGeneralSetting('isSoundEnabled', !isSoundEnabled)} className={`w-14 h-8 rounded-full transition-colors ${isSoundEnabled ? 'bg-orange-500' : 'bg-gray-300'}`}>
              <div className={`w-6 h-6 bg-white rounded-full transition-all ${isSoundEnabled ? 'translate-x-7' : 'translate-x-1'}`} />
            </button>
          </div>
          <button onClick={handleLogout} className="w-full bg-red-50 text-red-600 py-3 rounded-xl font-bold border border-red-100">چوونەدەرەوە</button>
        </div>
      </div>
    </div>
  );

  if (!adminUser) {
    return (
      <div className="min-h-[80vh] flex items-center justify-center p-6 text-black">
        <div className="bg-white p-8 rounded-3xl shadow-2xl w-full max-w-md border border-gray-100">
          <div className="text-center mb-8">
            <h2 className="text-2xl font-black">چوونەژوورەوەی بەڕێوەبەر</h2>
            <p className="text-gray-400 text-sm mt-1">تکایە ئیمەیڵ و وشەی نهێنی بنووسە</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="email" placeholder="ئیمەیڵ" className="w-full p-4 bg-gray-50 rounded-2xl border" value={email} onChange={e => setEmail(e.target.value)} required />
            <input type="password" placeholder="وشەی نهێنی" className="w-full p-4 bg-gray-50 rounded-2xl border" value={password} onChange={e => setPassword(e.target.value)} required />
            <button disabled={isLoading} className="w-full bg-orange-600 text-white py-4 rounded-2xl font-bold text-lg">{isLoading ? 'چاوەڕوانبە...' : 'چوونەژوورەوە'}</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col lg:flex-row text-black">
      <nav className="w-full lg:w-64 bg-white border-b lg:border-l border-gray-100 sticky top-0 lg:h-screen z-50">
        <div className="flex lg:flex-col p-4 gap-1">
          {['DASHBOARD', 'PRODUCTS', 'CATEGORIES', 'ORDERS', 'SETTINGS'].map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 py-3 rounded-2xl text-sm font-bold ${activeTab === tab ? 'bg-orange-600 text-white' : 'text-gray-500'}`}>
              {tab === 'DASHBOARD' ? 'سەرەتا' : tab === 'PRODUCTS' ? 'خواردنەکان' : tab === 'CATEGORIES' ? 'بەشەکان' : tab === 'ORDERS' ? 'داواکارییەکان' : 'ڕێکخستن'}
            </button>
          ))}
        </div>
      </nav>

      <div className="flex-grow p-4 lg:p-12 pb-32">
        {activeTab === 'DASHBOARD' && renderDashboard()}
        {activeTab === 'PRODUCTS' && renderProducts()}
        {activeTab === 'CATEGORIES' && renderCategories()}
        {activeTab === 'ORDERS' && (
          <div className="space-y-4">
            {orderLogs.map(log => (
              <div key={log.id} className="p-4 bg-white rounded-2xl border flex justify-between items-center">
                <div>
                  <div className="flex gap-1 mb-1">{log.items.map((it, i) => <span key={i} className="text-xs font-bold bg-gray-50 px-2 py-1 rounded">{it}</span>)}</div>
                  <div className="text-xs text-gray-400">{new Date(log.timestamp).toLocaleString('ku')}</div>
                </div>
                <div className="font-black text-orange-600">{log.total.toLocaleString()} د.ع</div>
              </div>
            ))}
          </div>
        )}
        {activeTab === 'SETTINGS' && renderSettings()}
      </div>

      {showConfirmDelete && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/40">
          <div className="bg-white rounded-3xl p-8 max-w-sm w-full">
            <h3 className="text-xl font-bold mb-8 text-center">دڵنیایت لە سڕینەوە؟</h3>
            <div className="flex gap-4">
              <button onClick={async () => {
                if(showConfirmDelete.type === 'P') await deleteDoc(doc(db, "products", showConfirmDelete.id));
                else await deleteDoc(doc(db, "categories", showConfirmDelete.id));
                setShowConfirmDelete(null);
              }} className="flex-grow bg-red-600 text-white py-4 rounded-2xl font-bold">سڕینەوە</button>
              <button onClick={() => setShowConfirmDelete(null)} className="flex-grow bg-gray-100 py-4 rounded-2xl font-bold">نەخێر</button>
            </div>
          </div>
        </div>
      )}
      <style>{`.input-admin { @apply p-3 bg-gray-50 rounded-xl border border-gray-200 outline-none focus:border-orange-500 transition-colors; }`}</style>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CartItem, OrderLog } from '../types';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  whatsappNumber: string;
  onUpdateQuantity: (id: string, delta: number, size?: 'S' | 'M' | 'L') => void;
  onUpdateNote: (id: string, note: string, size?: 'S' | 'M' | 'L') => void;
  onRemove: (id: string, size?: 'S' | 'M' | 'L') => void;
  onOrderLogged: (log: OrderLog) => void;
  initialLocationUrl?: string | null;
  locationPermissionStatus?: 'prompt' | 'granted' | 'denied' | 'unknown';
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  whatsappNumber,
  onUpdateQuantity,
  onUpdateNote,
  onRemove,
  onOrderLogged,
  initialLocationUrl = null,
  locationPermissionStatus = 'unknown'
}) => {
  const [locationUrl, setLocationUrl] = useState<string | null>(initialLocationUrl);
  const [isLocating, setIsLocating] = useState(false);
  const [locationError, setLocationError] = useState<string | null>(null);

  useEffect(() => {
    if (initialLocationUrl && !locationUrl) setLocationUrl(initialLocationUrl);
  }, [initialLocationUrl]);

  const getItemPrice = (item: CartItem) => {
    if (item.category !== 'pizza' || !item.selectedSize) return item.price;
    if (item.selectedSize === 'M') return item.priceM || (item.price + 2000);
    if (item.selectedSize === 'L') return item.priceL || (item.price + 4000);
    return item.price;
  };

  const total = cart.reduce((acc, item) => acc + (getItemPrice(item) * item.quantity), 0);

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
      setLocationError('گەڕان بۆ شوێن پشتگیری ناکرێت.');
      return;
    }
    setIsLocating(true);
    setLocationError(null);
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        const url = `https://www.google.com/maps?q=${latitude},${longitude}`;
        setLocationUrl(url);
        setIsLocating(false);
      },
      (error) => {
        setIsLocating(false);
        setLocationError(error.code === 1 ? 'ڕێگری لێکرا.' : 'هەڵەیەک ڕوویدا.');
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  const handleOrder = async () => {
    if (cart.length === 0) return;

    // Log to Firebase
    const logData = {
      timestamp: Date.now(),
      items: cart.map(i => `${i.quantity}x ${i.name} ${i.selectedSize ? `(${i.selectedSize})` : ''}`),
      total: total
    };
    try {
        await addDoc(collection(db, "orders"), logData);
    } catch(e) {
        console.error("Failed to log order:", e);
    }

    let message = "سڵاو، دەمەوێت ئەم داواکارییە بکەم:\n\n";
    cart.forEach(item => {
      const sizeLabel = item.selectedSize === 'S' ? 'بچووک' : item.selectedSize === 'M' ? 'ناوەند' : item.selectedSize === 'L' ? 'گەورە' : '';
      const itemTotal = getItemPrice(item) * item.quantity;
      const noteText = item.note ? ` (تێبینی: ${item.note})` : '';
      message += `• ${item.quantity}x ${item.name} ${sizeLabel ? `[${sizeLabel}]` : ''}${noteText} - ${itemTotal.toLocaleString()} IQD\n`;
    });
    message += `\nکۆی گشتی: ${total.toLocaleString()} دینار`;
    if (locationUrl) message += `\n\n📍 شوێنی من:\n${locationUrl}`;

    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  if (!isOpen) return null;

  const getSizeName = (size?: string) => {
    if (size === 'S') return 'بچووک';
    if (size === 'M') return 'ناوەند';
    if (size === 'L') return 'گەورە';
    return '';
  };

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/50">
      <div className="absolute inset-0" onClick={onClose} />
      <div className="bg-white rounded-t-3xl h-[85vh] w-full flex flex-col relative animate-slide-up shadow-2xl overflow-hidden text-black">
        <div className="p-4 border-b flex justify-between items-center sticky top-0 bg-white z-10">
          <h2 className="text-xl font-bold">سەبەتە</h2>
          <button onClick={onClose} className="p-2 text-gray-400">داخستن</button>
        </div>
        <div className="flex-grow overflow-y-auto p-4 space-y-4">
          {cart.map((item, index) => (
            <div key={index} className="flex gap-4 bg-gray-50 p-4 rounded-3xl items-center">
              <img src={item.imageUrl} className="w-16 h-16 rounded-2xl object-cover" />
              <div className="flex-grow">
                <h3 className="font-bold">{item.name} {getSizeName(item.selectedSize)}</h3>
                <p className="text-orange-600 font-bold">{(getItemPrice(item) * item.quantity).toLocaleString()} د.ع</p>
                <div className="flex items-center gap-3 mt-2">
                    <button onClick={() => onUpdateQuantity(item.id, -1, item.selectedSize)} className="w-8 h-8 rounded-full border bg-white">-</button>
                    <span className="font-bold">{item.quantity}</span>
                    <button onClick={() => onUpdateQuantity(item.id, 1, item.selectedSize)} className="w-8 h-8 rounded-full border bg-white">+</button>
                </div>
              </div>
              <button onClick={() => onRemove(item.id, item.selectedSize)} className="text-red-400">لابردن</button>
            </div>
          ))}
        </div>
        <div className="p-6 border-t bg-white sticky bottom-0">
          <button onClick={handleGetLocation} className="w-full mb-4 py-3 bg-blue-50 text-blue-600 rounded-2xl font-bold">
            {locationUrl ? '✅ شوێن وەرگیرا' : '📍 دیاریکردنی شوێن'}
          </button>
          <div className="flex justify-between items-center mb-6">
            <span className="text-gray-500 font-bold">کۆی گشتی</span>
            <span className="text-2xl font-black">{total.toLocaleString()} د.ع</span>
          </div>
          <button onClick={handleOrder} className="w-full bg-green-600 text-white py-4 rounded-3xl font-bold text-xl">داواکردن لە واتساپ</button>
        </div>
      </div>
      <style>{`@keyframes slide-up { from { transform: translateY(100%); } to { transform: translateY(0); } }.animate-slide-up { animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1); }`}</style>
    </div>
  );
};

