import React, { useState, useEffect } from 'react';
import { CartItem, OrderLog } from '../types';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  whatsappNumber: string;
  onUpdateQuantity: (id: string, delta: number, size?: 'S' | 'M' | 'L') => void;
  onUpdateNote: (id: string, note: string, size?: 'S' | 'M' | 'L') => void;
  onRemove: (id: string, size?: 'S' | 'M' | 'L') => void;
  onOrderLogged: (log: OrderLog) => void;
  initialLocationUrl?: string | null;
  locationPermissionStatus?: 'prompt' | 'granted' | 'denied' | 'unknown';
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  whatsappNumber,
  onUpdateQuantity,
  onUpdateNote,
  onRemove,
  onOrderLogged,
  initialLocationUrl = null,
  locationPermissionStatus = 'unknown'
}) => {
  const [locationUrl, setLocationUrl] = useState<string | null>(initialLocationUrl);
  const [isLocating, setIsLocating] = useState(false);
  const [locationError, setLocationError] = useState<string | null>(null);

  useEffect(() => {
    if (initialLocationUrl && !locationUrl) setLocationUrl(initialLocationUrl);
  }, [initialLocationUrl]);

  const getItemPrice = (item: CartItem) => {
    if (item.category !== 'pizza' || !item.selectedSize) return item.price;
    if (item.selectedSize === 'M') return item.priceM || (item.price + 2000);
    if (item.selectedSize === 'L') return item.priceL || (item.price + 4000);
    return item.price;
  };

  const total = cart.reduce((acc, item) => acc + (getItemPrice(item) * item.quantity), 0);

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
      setLocationError('گەڕان بۆ شوێن پشتگیری ناکرێت.');
      return;
    }
    setIsLocating(true);
    setLocationError(null);
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        const url = `https://www.google.com/maps?q=${latitude},${longitude}`;
        setLocationUrl(url);
        setIsLocating(false);
      },
      (error) => {
        setIsLocating(false);
        setLocationError(error.code === 1 ? 'ڕێگری لێکرا.' : 'هەڵەیەک ڕوویدا.');
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  const handleOrder = async () => {
    if (cart.length === 0) return;

    // Log to Firebase
    const logData = {
      timestamp: Date.now(),
      items: cart.map(i => `${i.quantity}x ${i.name} ${i.selectedSize ? `(${i.selectedSize})` : ''}`),
      total: total
    };
    try {
        await addDoc(collection(db, "orders"), logData);
    } catch(e) {
        console.error("Failed to log order:", e);
    }

    let message = "📦 داواکاری نوێ:\n\n";
    cart.forEach(item => {
      const sizeLabel = item.selectedSize === 'S' ? 'بچووک' : item.selectedSize === 'M' ? 'ناوەند' : item.selectedSize === 'L' ? 'گەورە' : '';
      const itemTotal = getItemPrice(item) * item.quantity;
      const noteText = item.note ? `\n   📝 تێبینی: ${item.note}` : '';
      message += `• ${item.quantity}x ${item.name} ${sizeLabel ? `[${sizeLabel}]` : ''} = ${itemTotal.toLocaleString()} IQD${noteText}\n`;
    });
    message += `\n💰 کۆی گشتی: ${total.toLocaleString()} دینار`;
    if (locationUrl) message += `\n\n📍 شوێنی کڕیار:\n${locationUrl}`;

    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  if (!isOpen) return null;

  const getSizeName = (size?: string) => {
    if (size === 'S') return 'بچووک';
    if (size === 'M') return 'ناوەند';
    if (size === 'L') return 'گەورە';
    return '';
  };

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/60 backdrop-blur-sm">
      <div className="absolute inset-0" onClick={onClose} />
      <div className="bg-white rounded-t-[40px] h-[90vh] w-full flex flex-col relative animate-slide-up shadow-2xl overflow-hidden text-black">
        <div className="p-6 border-b flex justify-between items-center sticky top-0 bg-white z-10">
          <h2 className="text-2xl font-black">سەبەتەی من</h2>
          <button onClick={onClose} className="p-2 bg-gray-100 rounded-full text-gray-400">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>
        <div className="flex-grow overflow-y-auto p-4 space-y-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400 py-12">
              <svg className="w-20 h-20 mb-4 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
              <p className="font-bold text-lg">سەبەتەکەت بەتاڵە</p>
            </div>
          ) : cart.map((item, index) => (
            <div key={`${item.id}-${item.selectedSize}`} className="flex flex-col gap-3 bg-gray-50 p-5 rounded-[32px] border border-gray-100">
              <div className="flex gap-4 items-center">
                <img src={item.imageUrl} className="w-20 h-20 rounded-3xl object-cover shadow-sm" />
                <div className="flex-grow">
                  <h3 className="font-black text-gray-800">{item.name} <span className="text-orange-600 text-sm">{getSizeName(item.selectedSize)}</span></h3>
                  <p className="text-gray-500 font-bold text-sm">{(getItemPrice(item) * item.quantity).toLocaleString()} د.ع</p>
                  <div className="flex items-center gap-4 mt-3">
                      <button onClick={() => onUpdateQuantity(item.id, -1, item.selectedSize)} className="w-10 h-10 rounded-2xl border-2 border-gray-200 bg-white flex items-center justify-center text-xl font-black text-black active:bg-gray-100 transition-colors">-</button>
                      <span className="font-black text-xl text-black">{item.quantity}</span>
                      <button onClick={() => onUpdateQuantity(item.id, 1, item.selectedSize)} className="w-10 h-10 rounded-2xl border-2 border-gray-200 bg-white flex items-center justify-center text-xl font-black text-black active:bg-gray-100 transition-colors">+</button>
                  </div>
                </div>
                <button onClick={() => onRemove(item.id, item.selectedSize)} className="p-2 text-red-400 hover:text-red-600 transition-colors">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              </div>
              <textarea 
                placeholder="📝 تێبینی تایبەت (ئەگەر هەبێت)"
                className="w-full bg-white border border-gray-200 rounded-2xl p-3 text-sm font-medium focus:border-orange-500 outline-none transition-all resize-none"
                rows={2}
                value={item.note || ''}
                onChange={(e) => onUpdateNote(item.id, e.target.value, item.selectedSize)}
              />
            </div>
          ))}
        </div>
        <div className="p-8 border-t bg-white sticky bottom-0 space-y-4">
          <button 
            onClick={handleGetLocation} 
            className={`w-full py-4 rounded-3xl font-black text-sm flex items-center justify-center gap-2 transition-all ${locationUrl ? 'bg-blue-50 text-blue-600 border border-blue-100' : 'bg-gray-100 text-gray-600'}`}
          >
            {isLocating ? 'خەریکی وەرگرتنی شوێنە...' : locationUrl ? '✅ شوێنی من وەرگیرا' : '📍 دیاریکردنی شوێنی من'}
          </button>

          <div className="flex justify-between items-center py-2">
            <span className="text-gray-400 font-bold text-lg">کۆی گشتی</span>
            <span className="text-3xl font-black text-orange-600">{total.toLocaleString()} د.ع</span>
          </div>

          <button 
            onClick={handleOrder} 
            disabled={cart.length === 0}
            className="w-full bg-green-600 text-white py-5 rounded-[28px] font-black text-xl shadow-xl shadow-green-100 hover:bg-green-700 active:scale-95 transition-all disabled:opacity-50 disabled:active:scale-100"
          >
            داواکردن لە واتساپ
          </button>
        </div>
      </div>
      <style>{`
        @keyframes slide-up { from { transform: translateY(100%); } to { transform: translateY(0); } }
        .animate-slide-up { animation: slide-up 0.5s cubic-bezier(0.16, 1, 0.3, 1); }
      `}</style>
    </div>
  );
};

