      <nav className="w-full lg:w-64 bg-white border-l border-gray-100 p-4 sticky top-0 h-auto lg:h-screen flex lg:flex-col gap-2 overflow-x-auto no-scrollbar">
        {['DASHBOARD', 'PRODUCTS', 'CATEGORIES', 'SETTINGS'].map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-4 rounded-3xl font-bold whitespace-nowrap transition-all ${activeTab === tab ? 'bg-orange-600 text-white' : 'text-gray-500 hover:bg-gray-50'}`}>
            {tab === 'DASHBOARD' ? 'سەرەتا' : tab === 'PRODUCTS' ? 'خواردنەکان' : tab === 'CATEGORIES' ? 'بەشەکان' : 'ڕێکخستن'}
          </button>
        ))}
      </nav>

      <div className="flex-grow p-4 lg:p-12 space-y-8 max-w-5xl mx-auto w-full">
        {activeTab === 'DASHBOARD' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-bold mb-1">کۆی خواردنەکان</div>
              <div className="text-4xl font-black">{stats.totalProducts}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-bold mb-1">کۆی داواکارییەکان</div>
              <div className="text-4xl font-black text-green-600">{stats.totalOrders}</div>
            </div>
          </div>
        )}

        {activeTab === 'PRODUCTS' && (
          <div className="space-y-8">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100">
              <h3 className="font-black text-xl mb-6">زیادکردنی بەرھەمی نوێ</h3>
              <form onSubmit={async (e) => {
                e.preventDefault();
                setIsLoading(true);
                try {
                  const pData = { name: productForm.name, price: parseInt(productForm.price), imageUrl: productForm.imageUrl, category: productForm.category };
                  await addDoc(collection(db, "menu"), pData);
                  setProductForm({ name: '', price: '', imageUrl: '', category: categories[1]?.id || 'burgers' });
                } catch (err) { alert(err); } finally { setIsLoading(false); }
