import { Product, Category, OrderLog } from '../types';
import { DEFAULT_PRODUCTS, DEFAULT_CATEGORIES } from '../constants';

const PRODUCTS_KEY = 'fastfood_products_v1';
const CATEGORIES_KEY = 'fastfood_categories_v1';
const SOUND_KEY = 'fastfood_sound_enabled_v1';
const ORDERS_KEY = 'fastfood_orders_v1';
const IMGBB_KEY = 'fastfood_imgbb_key_v1';
const LOGO_KEY = 'fastfood_logo_v1';

export const getStoredProducts = (): Product[] => {
  const stored = localStorage.getItem(PRODUCTS_KEY);
  if (!stored) return DEFAULT_PRODUCTS;
  try {
    return JSON.parse(stored);
  } catch (e) {
    return DEFAULT_PRODUCTS;
  }
};

export const saveProducts = (products: Product[]) => {
  localStorage.setItem(PRODUCTS_KEY, JSON.stringify(products));
};

export const getStoredCategories = (): Category[] => {
  const stored = localStorage.getItem(CATEGORIES_KEY);
  if (!stored) return DEFAULT_CATEGORIES;
  try {
    return JSON.parse(stored);
  } catch (e) {
    return DEFAULT_CATEGORIES;
  }
};

export const saveCategories = (categories: Category[]) => {
  localStorage.setItem(CATEGORIES_KEY, JSON.stringify(categories));
};

export const getSoundPreference = (): boolean => {
  const stored = localStorage.getItem(SOUND_KEY);
  return stored === null ? true : stored === 'true';
};

export const saveSoundPreference = (enabled: boolean) => {
  localStorage.setItem(SOUND_KEY, enabled.toString());
};

export const getOrderLogs = (): OrderLog[] => {
  const stored = localStorage.getItem(ORDERS_KEY);
  return stored ? JSON.parse(stored) : [];
};

export const addOrderLog = (log: OrderLog) => {
  const logs = getOrderLogs();
  const updated = [log, ...logs].slice(0, 50); // Keep last 50
  localStorage.setItem(ORDERS_KEY, JSON.stringify(updated));
};

export const getStoredImgBBKey = (): string => {
  return localStorage.getItem(IMGBB_KEY) || '';
};

export const saveImgBBKey = (key: string) => {
  localStorage.setItem(IMGBB_KEY, key);
};

export const getStoredLogo = (): string => {
  return localStorage.getItem(LOGO_KEY) || '';
};

export const saveLogo = (url: string) => {
  localStorage.setItem(LOGO_KEY, url);
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  getDoc
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [imgbbKey, setImgbbKey] = useState(localStorage.getItem('fastfood_imgbb_key_v1') || '');
  const [connectionStatus, setConnectionStatus] = useState({ firestore: true });

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, imageUrl: string, category: string}>({ 
    name: '', price: '', imageUrl: '', category: categories[1]?.id || 'burgers' 
  });
  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [showConfirmDelete, setShowConfirmDelete] = useState<{type: 'P'|'C', id: string} | null>(null);

  const productFileRef = useRef<HTMLInputElement>(null);
  const categoryFileRef = useRef<HTMLInputElement>(null);
  const logoFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const checkConn = async () => {
      try {
        await getDoc(doc(db, "settings", "general"));
        setConnectionStatus({ firestore: true });
      } catch (err) {
        setConnectionStatus({ firestore: false });
      }
    };
    checkConn();
  }, []);

  const stats = useMemo(() => {
    return { 
      totalProducts: products.length, 
      totalOrders: orderLogs.length, 
      popularCatName: categories.find(c => c.id === products[0]?.category)?.name || 'نادیار' 
    };
  }, [products, categories, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      alert('وشەی نهێنی هەڵەیە!');
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    if (!imgbbKey) {
      alert('تکایە سەرەتا کلیل (API Key)ـی ImgBB لە ڕێکخستنەکان دابنێ.');
      return null;
    }
    setIsUploading(true);
    const formData = new FormData();
    formData.append('image', file);
    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${imgbbKey}`, { method: 'POST', body: formData });
      const result = await response.json();
      return result.success ? result.data.url : null;
    } catch (error) {
      alert('هەڵەیەک لە بەرزکردنەوەی وێنە ڕوویدا');
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  const updateGeneralSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "general"), { [field]: value }, { merge: true });
  };

  if (!isLocalAdmin) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center p-6">
        <form onSubmit={handleLogin} className="bg-white p-8 rounded-[40px] shadow-xl w-full max-w-md border border-gray-100">
          <h2 className="text-2xl font-black text-center mb-6">بەشی بەڕێوەبەر</h2>
          <input 
            type="password" 
            placeholder="وشەی نهێنی" 
            className="w-full p-5 bg-gray-50 rounded-3xl border border-gray-200 mb-4 text-center text-2xl tracking-widest outline-none focus:border-orange-500" 
            value={passwordInput} 
            onChange={e => setPasswordInput(e.target.value)} 
          />
          <button className="w-full bg-orange-600 text-white py-5 rounded-3xl font-black text-lg">چوونەژوورەوە</button>
        </form>
      </div>
    );
  }

  return (
    <div className="flex flex-col lg:flex-row min-h-screen">
      <nav className="w-full lg:w-64 bg-white border-l border-gray-100 p-4 sticky top-0 h-auto lg:h-screen flex lg:flex-col gap-2 overflow-x-auto no-scrollbar">
        {['DASHBOARD', 'PRODUCTS', 'CATEGORIES', 'SETTINGS'].map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-4 rounded-3xl font-bold whitespace-nowrap transition-all ${activeTab === tab ? 'bg-orange-600 text-white' : 'text-gray-500 hover:bg-gray-50'}`}>
            {tab === 'DASHBOARD' ? 'سەرەتا' : tab === 'PRODUCTS' ? 'خواردنەکان' : tab === 'CATEGORIES' ? 'بەشەکان' : 'ڕێکخستن'}
          </button>
        ))}
      </nav>

      <div className="flex-grow p-4 lg:p-12 space-y-8 max-w-5xl mx-auto w-full">
        {activeTab === 'DASHBOARD' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-bold mb-1">کۆی خواردنەکان</div>
              <div className="text-4xl font-black">{stats.totalProducts}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-bold mb-1">کۆی داواکارییەکان</div>
              <div className="text-4xl font-black text-green-600">{stats.totalOrders}</div>
            </div>
          </div>
        )}

        {activeTab === 'PRODUCTS' && (
          <div className="space-y-8">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100">
              <h3 className="font-black text-xl mb-6">زیادکردنی بەرھەمی نوێ</h3>
              <form onSubmit={async (e) => {
                e.preventDefault();
                setIsLoading(true);
                try {
                  const pData = { name: productForm.name, price: parseInt(productForm.price), imageUrl: productForm.imageUrl, category: productForm.category };
                  await addDoc(collection(db, "menu"), pData);
                  setProductForm({ name: '', price: '', imageUrl: '', category: categories[1]?.id || 'burgers' });
                } catch (err) { alert(err); } finally { setIsLoading(false); }
              }} className="space-y-4">
                <input className="input-admin w-full" placeholder="ناوی خواردن" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} required />
                <div className="grid grid-cols-2 gap-4">
                  <input className="input-admin" type="number" placeholder="نرخ" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
                  <select className="input-admin" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value})}>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="relative h-48 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center">
                  {productForm.imageUrl ? <img src={productForm.imageUrl} className="h-full w-full object-cover rounded-3xl" /> : "بارکردنی وێنە"}
                  <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      const url = await uploadToImgBB(file);
                      if (url) setProductForm(p => ({...p, imageUrl: url}));
                    }
                  }} />
                  {isUploading && <div className="absolute inset-0 bg-white/80 flex items-center justify-center font-black text-orange-600">خەریکی بارکردنە...</div>}
                </div>
                <button disabled={isUploading || isLoading} className="w-full bg-orange-600 text-white py-5 rounded-3xl font-black">پاشکەوتکردن</button>
              </form>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {products.map(p => (
                <div key={p.id} className="bg-white p-4 rounded-3xl border border-gray-100 flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <img src={p.imageUrl} className="w-16 h-16 rounded-2xl object-cover" />
                    <div>
                      <div className="font-black">{p.name}</div>
                      <div className="text-orange-600 font-bold">{p.price.toLocaleString()} د.ع</div>
                    </div>
                  </div>
                  <button onClick={async () => { if(confirm('دڵنیایت؟')) await deleteDoc(doc(db, "menu", p.id)); }} className="text-red-500 font-bold px-4">سڕینەوە</button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'SETTINGS' && (
          <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 space-y-6">
            <div>
              <label className="block text-sm font-bold text-gray-400 mb-2">ImgBB API Key</label>
              <input className="input-admin w-full" value={imgbbKey} onChange={e => { setImgbbKey(e.target.value); localStorage.setItem('fastfood_imgbb_key_v1', e.target.value); }} />
            </div>
            <div>
              <label className="block text-sm font-bold text-gray-400 mb-2">Telegram Chat ID</label>
              <input className="input-admin w-full" value={telegramChatId} onChange={e => updateGeneralSetting('telegramChatId', e.target.value)} placeholder="Enter Chat ID" />
            </div>
            <button onClick={() => { onAdminAuthChange(false); sessionStorage.removeItem('isAdminAuthenticated'); }} className="w-full py-4 rounded-3xl text-red-600 font-black bg-red-50">چوونەدەرەوە</button>
          </div>
        )}
      </div>
      <style>{`.input-admin { @apply p-5 bg-gray-50 rounded-3xl border border-gray-200 outline-none focus:border-orange-500 font-bold; }`}</style>
    </div>
  );
