import React, { useState } from 'react';
import { CartItem } from '../types';
import { TELEGRAM_BOT_TOKEN } from '../constants';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  telegramChatId: string;
  onUpdateQuantity: (id: string, delta: number) => void;
  onRemove: (id: string) => void;
  onClearCart: () => void;
  locationUrl: string | null;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  telegramChatId,
  onUpdateQuantity,
  onRemove,
  onClearCart,
  locationUrl
}) => {
  const [isSending, setIsSending] = useState(false);
  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleOrder = async () => {
    if (cart.length === 0 || !telegramChatId) {
      alert(!telegramChatId ? "تکایە سەرەتا Chat ID لە ڕێکخستنەکان دابنێ." : "سەبەتە بەتاڵە.");
      return;
    }

    setIsSending(true);
    let text = `📦 **داواکاری نوێ لە Aram Food**\n\n`;
    cart.forEach((item, index) => {
      text += `${index + 1}. ${item.name} (${item.quantity} دانە) - ${(item.price * item.quantity).toLocaleString()} IQD\n`;
    });
    text += `\n💰 **کۆی گشتی:** ${total.toLocaleString()} IQD`;

    if (locationUrl) {
      text += `\n\n📍 **لوکێشنی کڕیار:**\n${locationUrl}`;
    }

    try {
      await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: telegramChatId,
          text: text,
          parse_mode: "Markdown"
        })
      });

      // Log to Firebase
      await addDoc(collection(db, "orders"), {
        items: cart.map(i => `${i.quantity}x ${i.name}`),
        total,
        timestamp: Date.now()
      });

      alert("داواکارییەکەت نێردرا! سوپاس بۆ کڕینەکەت.");
      onClearCart();
      onClose();
    } catch (error) {
      alert("هەڵەیەک لە ناردن هەبوو، دووبارە هەوڵبدەرەوە.");
    } finally {
      setIsSending(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/60 backdrop-blur-sm">
      <div className="absolute inset-0" onClick={onClose} />
      <div className="bg-white rounded-t-[40px] h-[85vh] w-full flex flex-col relative animate-slide-up overflow-hidden text-black">
        <div className="p-8 border-b flex justify-between items-center">
          <h2 className="text-3xl font-black">سەبەتەکەم</h2>
          <button onClick={onClose} className="p-3 bg-gray-100 rounded-full">✕</button>
        </div>

        <div className="flex-grow overflow-y-auto p-6 space-y-4">
          {cart.map(item => (
            <div key={item.id} className="bg-gray-50 p-5 rounded-[32px] flex items-center gap-4">
              <img src={item.imageUrl} className="w-20 h-20 rounded-3xl object-cover" />
              <div className="flex-grow">
                <h3 className="font-black">{item.name}</h3>
                <div className="flex items-center gap-4 mt-2">
                  <button onClick={() => onUpdateQuantity(item.id, -1)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black">-</button>
                  <span className="font-black text-xl">{item.quantity}</span>
                  <button onClick={() => onUpdateQuantity(item.id, 1)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black">+</button>
                </div>
              </div>
              <button onClick={() => onRemove(item.id)} className="text-red-500">سڕینەوە</button>
            </div>
          ))}
        </div>

        <div className="p-8 border-t bg-white space-y-4">
          <div className="flex justify-between items-center">
            <span className="text-gray-400 font-bold">کۆی گشتی</span>
            <span className="text-3xl font-black text-orange-600">{total.toLocaleString()} د.ع</span>
          </div>
          <button 
            disabled={isSending || cart.length === 0}
            onClick={handleOrder}
            className="w-full bg-[#0088cc] text-white py-6 rounded-[30px] font-black text-xl shadow-xl active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3"
          >
            <svg className="w-7 h-7" viewBox="0 0 24 24" fill="currentColor">
              <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.64 6.8c-.15 1.58-.8 5.42-1.13 7.19-.14.75-.42 1-.68 1.03-.58.05-1.02-.38-1.58-.75-.88-.58-1.38-.94-2.23-1.5-.99-.65-.35-1.01.22-1.59.15-.15 2.71-2.48 2.76-2.69a.2.2 0 00-.05-.18c-.06-.05-.14-.03-.21-.02-.09.02-1.49.95-4.22 2.79-.4.27-.76.41-1.08.4-.35-.01-1.02-.2-1.52-.36-.61-.2-1.1-.3-1.05-.63.02-.17.25-.34.69-.51 2.69-1.17 4.49-1.94 5.39-2.31 2.57-1.05 3.1-.1.23-3.1-.1.23-.2.43-.05.51z"/>
            </svg>
            {isSending ? 'خەریکی ناردنە...' : 'ناردنی داواکاری'}
          </button>
        </div>
      </div>
      <style>{`@keyframes slide-up { from { transform: translateY(100%); } to { transform: translateY(0); } } .animate-slide-up { animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1); }`}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { CategoryBar } from './components/CategoryBar';
import { InAppBrowserOverlay } from './components/InAppBrowserOverlay';
import { Product, CartItem, ViewState, Category, OrderLog } from './types';
import { DEFAULT_CATEGORIES, ADD_TO_CART_SOUND_URL } from './constants';
import { db } from './firebase';
import { collection, onSnapshot, query, orderBy, doc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [telegramChatId, setTelegramChatId] = useState('');
  const [businessLogo, setBusinessLogo] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);
  const [isLocalAdmin, setIsLocalAdmin] = useState(() => sessionStorage.getItem('isAdminAuthenticated') === 'true');
  const [locationUrl, setLocationUrl] = useState<string | null>(null);
  const [isInAppBrowser, setIsInAppBrowser] = useState(false);

  useEffect(() => {
    // Detection
    const ua = navigator.userAgent || navigator.vendor;
    if (ua.indexOf("FBAN") > -1 || ua.indexOf("FBAV") > -1 || ua.indexOf("Messenger") > -1) setIsInAppBrowser(true);

    // Auto Location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setLocationUrl(`https://www.google.com/maps?q=${pos.coords.latitude},${pos.coords.longitude}`),
        null,
        { enableHighAccuracy: true }
      );
    }

    // Real-time
    const unsubProducts = onSnapshot(query(collection(db, "menu"), orderBy("name")), (snap) => {
      const p: Product[] = [];
      snap.forEach(d => p.push({ id: d.id, ...d.data() } as Product));
      setProducts(p);
    });

    const unsubSettings = onSnapshot(doc(db, "settings", "general"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setTelegramChatId(data.telegramChatId || '');
        setBusinessLogo(data.businessLogo || '');
      }
    });

    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("timestamp", "desc")), (snap) => {
      const o: OrderLog[] = [];
      snap.forEach(d => o.push({ id: d.id, ...d.data() } as OrderLog));
      setOrderLogs(o);
    });

    return () => { unsubProducts(); unsubSettings(); unsubOrders(); };
  }, []);

  const filteredProducts = useMemo(() => {
    return selectedCategory === 'all' ? products : products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const addToCart = (product: Product) => {
    new Audio(ADD_TO_CART_SOUND_URL).play().catch(() => {});
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-black overflow-x-hidden">
      {isInAppBrowser && <InAppBrowserOverlay businessLogo={businessLogo} />}
      <Header currentView={view} onToggleAdmin={() => setView(v => v === 'MENU' ? 'ADMIN' : 'MENU')} businessLogo={businessLogo} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <CategoryBar categories={DEFAULT_CATEGORIES} selectedCategoryId={selectedCategory} onSelectCategory={setSelectedCategory} />
            <div className="max-w-4xl mx-auto px-4 py-8 pb-32">
              <div className="mb-8">
                <h2 className="text-3xl font-black">Aram Food Menu</h2>
                <p className="text-gray-400 font-bold mt-1">باشترین تامی بەرگەر و پیتزا لێرەیە</p>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                {filteredProducts.map(p => <ProductCard key={p.id} product={p} onAddToCart={addToCart} />)}
              </div>
              {filteredProducts.length === 0 && (
                <div className="text-center py-20 text-gray-300 font-black text-xl">هیچ خواردنێک نییە</div>
              )}
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} categories={DEFAULT_CATEGORIES} isSoundEnabled={true} 
            telegramChatId={telegramChatId} businessLogo={businessLogo} 
            orderLogs={orderLogs} isLocalAdmin={isLocalAdmin} onAdminAuthChange={setIsLocalAdmin} 
          />
        )}
      </main>

      {view === 'MENU' && cart.length > 0 && <BottomNav cart={cart} onViewCart={() => setIsCartOpen(true)} />}

      <CartModal 
        isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} 
        telegramChatId={telegramChatId} locationUrl={locationUrl}
        onUpdateQuantity={(id, delta) => setCart(c => c.map(i => i.id === id ? {...i, quantity: Math.max(1, i.quantity + delta)} : i))}
        onRemove={(id) => setCart(c => c.filter(i => i.id !== id))}
        onClearCart={() => setCart([])}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { CartItem } from '../types';
import { TELEGRAM_BOT_TOKEN } from '../constants';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

declare var Swal: any;

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  telegramChatId: string;
  onUpdateQuantity: (id: string, delta: number) => void;
  onRemove: (id: string) => void;
  onClearCart: () => void;
  locationUrl: string | null;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  telegramChatId,
  onUpdateQuantity,
  onRemove,
  onClearCart,
  locationUrl
}) => {
  const [isSending, setIsSending] = useState(false);
  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleOrder = async () => {
    // Basic validation
    if (cart.length === 0) {
      Swal.fire({
        icon: 'warning',
        title: 'سەبەتە بەتاڵە',
        text: 'تکایە سەرەتا خواردن زیاد بکە بۆ سەبەتەکەت.',
        confirmButtonText: 'باشە'
      });
      return;
    }

    if (!telegramChatId) {
      Swal.fire({
        icon: 'error',
        title: 'هەڵە لە ڕێکخستن',
        text: 'تکایە سەرەتا Telegram Chat ID لە بەشی بەڕێوەبەر دابنێ.',
        confirmButtonText: 'تێگەیشتم'
      });
      return;
    }

    setIsSending(true);

    // Construct order text
    let text = `📦 **داواکاری نوێ لە Aram Food**\n\n`;
    cart.forEach((item, index) => {
      text += `${index + 1}. **${item.name}**\n   - بڕ: ${item.quantity} دانە\n   - نرخ: ${(item.price * item.quantity).toLocaleString()} IQD\n`;
    });
    text += `\n💰 **کۆی گشتی:** ${total.toLocaleString()} IQD`;

    if (locationUrl) {
      text += `\n\n📍 **لوکێشنی کڕیار:**\n${locationUrl}`;
    } else {
      text += `\n\n📍 **لوکێشن:** وەرنەگیراوە`;
    }

    try {
      console.log("Sending order to Telegram...");
      const response = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: telegramChatId,
          text: text,
          parse_mode: "Markdown"
        })
      });

      const result = await response.json();
      console.log("Telegram API Response:", result);

      if (!response.ok) {
        throw new Error(result.description || "هەڵەیەک لە ناردنی داتاکان بۆ تێلیگرام ڕوویدا.");
      }

      // Log to Firebase for record keeping
      await addDoc(collection(db, "orders"), {
        items: cart.map(i => `${i.quantity}x ${i.name}`),
        total,
        timestamp: Date.now()
      });

      // Show success message
      await Swal.fire({
        icon: 'success',
        title: 'داواکارییەکەت نێردرا',
        text: 'سوپاس بۆ کڕینەکەت، داواکارییەکەت گەیشتە بەشە پەیوەندیدارەکان.',
        confirmButtonText: 'باشە',
        confirmButtonColor: '#ea580c'
      });

      onClearCart();
      onClose();
    } catch (error: any) {
      console.error("Order process error:", error);
      Swal.fire({
        icon: 'error',
        title: 'هەڵەیەک ڕوویدا',
        text: `هەڵە: ${error.message || error}`,
        confirmButtonText: 'دووبارە هەوڵبدەرەوە'
      });
    } finally {
      setIsSending(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/60 backdrop-blur-sm">
      <div className="absolute inset-0" onClick={onClose} />
      <div className="bg-white rounded-t-[40px] h-[85vh] w-full flex flex-col relative animate-slide-up overflow-hidden text-black">
        <div className="p-8 border-b flex justify-between items-center">
          <h2 className="text-3xl font-black">سەبەتەکەم</h2>
          <button onClick={onClose} className="p-3 bg-gray-100 rounded-full">✕</button>
        </div>

        <div className="flex-grow overflow-y-auto p-6 space-y-4">
          {cart.map(item => (
            <div key={item.id} className="bg-gray-50 p-5 rounded-[32px] flex items-center gap-4">
              <img src={item.imageUrl} className="w-20 h-20 rounded-3xl object-cover" />
              <div className="flex-grow">
                <h3 className="font-black">{item.name}</h3>
                <div className="flex items-center gap-4 mt-2">
                  <button onClick={() => onUpdateQuantity(item.id, -1)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black">-</button>
                  <span className="font-black text-xl">{item.quantity}</span>
                  <button onClick={() => onUpdateQuantity(item.id, 1)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black">+</button>
                </div>
              </div>
              <button onClick={() => onRemove(item.id)} className="text-red-500 font-bold p-2">سڕینەوە</button>
            </div>
          ))}
          {cart.length === 0 && (
            <div className="text-center py-20 text-gray-400 font-bold">سەبەتەکەت بەتاڵە</div>
          )}
        </div>

        <div className="p-8 border-t bg-white space-y-4">
          <div className="flex justify-between items-center">
            <span className="text-gray-400 font-bold">کۆی گشتی</span>
            <span className="text-3xl font-black text-orange-600">{total.toLocaleString()} د.ع</span>
          </div>
          <button 
            disabled={isSending || cart.length === 0}
            onClick={handleOrder}
            className="w-full bg-[#0088cc] text-white py-6 rounded-[30px] font-black text-xl shadow-xl active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3"
          >
            {isSending ? (
              <div className="flex items-center gap-2">
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                <span>خەریکی ناردنە...</span>
              </div>
            ) : (
              <>
                <svg className="w-7 h-7" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.64 6.8c-.15 1.58-.8 5.42-1.13 7.19-.14.75-.42 1-.68 1.03-.58.05-1.02-.38-1.58-.75-.88-.58-1.38-.94-2.23-1.5-.99-.65-.35-1.01.22-1.59.15-.15 2.71-2.48 2.76-2.69a.2.2 0 00-.05-.18c-.06-.05-.14-.03-.21-.02-.09.02-1.49.95-4.22 2.79-.4.27-.76.41-1.08.4-.35-.01-1.02-.2-1.52-.36-.61-.2-1.1-.3-1.05-.63.02-.17.25-.34.69-.51 2.69-1.17 4.49-1.94 5.39-2.31 2.57-1.05 3.1-.1.23-3.1-.1.23-.2.43-.05.51z"/>
                </svg>
                <span>ناردنی داواکاری</span>
              </>
            )}
          </button>
        </div>
      </div>
      <style>{`@keyframes slide-up { from { transform: translateY(100%); } to { transform: translateY(0); } } .animate-slide-up { animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1); }`}</style>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  getDoc
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [imgbbKey, setImgbbKey] = useState(localStorage.getItem('fastfood_imgbb_key_v1') || '');
  const [connectionStatus, setConnectionStatus] = useState({ firestore: true });

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, imageUrl: string, category: string}>({ 
    name: '', price: '', imageUrl: '', category: categories[1]?.id || 'burgers' 
  });
  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [showConfirmDelete, setShowConfirmDelete] = useState<{type: 'P'|'C', id: string} | null>(null);

  const productFileRef = useRef<HTMLInputElement>(null);
  const categoryFileRef = useRef<HTMLInputElement>(null);
  const logoFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const checkConn = async () => {
      try {
        await getDoc(doc(db, "settings", "general"));
        setConnectionStatus({ firestore: true });
      } catch (err) {
        setConnectionStatus({ firestore: false });
      }
    };
    checkConn();
  }, []);

  const stats = useMemo(() => {
    return { 
      totalProducts: products.length, 
      totalOrders: orderLogs.length, 
      popularCatName: categories.find(c => c.id === products[0]?.category)?.name || 'نادیار' 
    };
  }, [products, categories, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      alert('وشەی نهێنی هەڵەیە!');
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    if (!imgbbKey) {
      alert('تکایە سەرەتا کلیل (API Key)ـی ImgBB لە ڕێکخستنەکان دابنێ.');
      return null;
    }
    setIsUploading(true);
    const formData = new FormData();
    formData.append('image', file);
    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${imgbbKey}`, { method: 'POST', body: formData });
      const result = await response.json();
      return result.success ? result.data.url : null;
    } catch (error) {
      alert('هەڵەیەک لە بەرزکردنەوەی وێنە ڕوویدا');
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  const updateGeneralSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "general"), { [field]: value }, { merge: true });
  };

  if (!isLocalAdmin) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center p-6">
