                    if (file) {
                      const url = await uploadToImgBB(file);
                      if (url) setProductForm(p => ({...p, imageUrl: url}));
                    }
                  }} />
                  {isUploading && <div className="absolute inset-0 bg-white/80 flex items-center justify-center font-black text-orange-600">خەریکی بارکردنە...</div>}
                </div>
                <button disabled={isUploading || isLoading} className="w-full bg-orange-600 text-white py-5 rounded-3xl font-black">پاشکەوتکردن</button>
              </form>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {products.map(p => (
                <div key={p.id} className="bg-white p-4 rounded-3xl border border-gray-100 flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <img src={p.imageUrl} className="w-16 h-16 rounded-2xl object-cover" />
                    <div>
                      <div className="font-black">{p.name}</div>
                      <div className="text-orange-600 font-bold">{p.price.toLocaleString()} د.ع</div>
                    </div>
                  </div>
                  <button onClick={async () => { if(confirm('دڵنیایت؟')) await deleteDoc(doc(db, "menu", p.id)); }} className="text-red-500 font-bold px-4">سڕینەوە</button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'SETTINGS' && (
          <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 space-y-6">
            <div>
              <label className="block text-sm font-bold text-gray-400 mb-2">ImgBB API Key</label>
              <input className="input-admin w-full" value={imgbbKey} onChange={e => { setImgbbKey(e.target.value); localStorage.setItem('fastfood_imgbb_key_v1', e.target.value); }} placeholder="Paste ImgBB Key here" />
            </div>
            <div>
