          <div className="space-y-8">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100">
              <h3 className="font-black text-xl mb-6">زیادکردنی بەرھەمی نوێ</h3>
              <form onSubmit={async (e) => {
                e.preventDefault();
                if (!productForm.img) {
                  alert("تکایە سەرەتا وێنەیەک بار بکە.");
                  return;
                }
                setIsLoading(true);
                try {
                  // Using 'img' field as requested
                  const pData = { 
                    name: productForm.name, 
                    price: parseInt(productForm.price), 
                    img: productForm.img, 
                    category: productForm.category 
                  };
                  await addDoc(collection(db, "menu"), pData);
                  setProductForm({ name: '', price: '', img: '', category: categories[1]?.id || 'burgers' });
                } catch (err) { 
                  alert(err); 
                } finally { 
                  setIsLoading(false); 
                }
              }} className="space-y-4">
                <input className="input-admin w-full" placeholder="ناوی خواردن" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} required />
                <div className="grid grid-cols-2 gap-4">
                  <input className="input-admin" type="number" placeholder="نرخ" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
                  <select className="input-admin" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value})}>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="relative h-48 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center overflow-hidden">
                  {productForm.img ? (
                    <img src={productForm.img} className="h-full w-full object-cover" />
                  ) : (
                    <div className="flex flex-col items-center text-gray-400">
                      <svg className="w-10 h-10 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                      </svg>
                      <span className="font-bold">بارکردنی وێنە</span>
                    </div>
                  )}
                  <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      const url = await uploadToImgBB(file);
                      if (url) setProductForm(p => ({...p, img: url}));
                    }
                  }} />
                  {isUploading && (
                    <div className="absolute inset-0 bg-white/80 flex flex-col items-center justify-center">
                      <div className="w-8 h-8 border-4 border-orange-500 border-t-transparent rounded-full animate-spin mb-2"></div>
                      <span className="font-black text-orange-600">خەریکی بارکردنە...</span>
                    </div>
                  )}
                </div>
                <button disabled={isUploading || isLoading} className="w-full bg-orange-600 text-white py-5 rounded-3xl font-black active:scale-95 disabled:opacity-50">پاشکەوتکردن</button>
              </form>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {products.map(p => (
                <div key={p.id} className="bg-white p-4 rounded-3xl border border-gray-100 flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <img src={p.img} className="w-16 h-16 rounded-2xl object-cover" />
                    <div>
                      <div className="font-black">{p.name}</div>
                      <div className="text-orange-600 font-bold">{p.price.toLocaleString()} د.ع</div>
