                  <button onClick={async () => { if(confirm('دڵنیایت لە سڕینەوەی ئەم خواردنە؟')) await deleteDoc(doc(db, "menu", p.id)); }} className="text-red-500 font-bold px-4 hover:bg-red-50 py-2 rounded-xl transition-colors">سڕینەوە</button>
                </div>
              ))}
