        )}

        {activeTab === 'SETTINGS' && (
          <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 space-y-6">
            <div>
              <label className="block text-sm font-bold text-gray-400 mb-2">ImgBB API Key</label>
              <input className="input-admin w-full" value={imgbbKey} onChange={e => { setImgbbKey(e.target.value); localStorage.setItem('fastfood_imgbb_key_v1', e.target.value); }} placeholder="Paste ImgBB Key here" />
            </div>
            <div>
              <label className="block text-sm font-bold text-gray-400 mb-2">Telegram Chat ID</label>
              <input className="input-admin w-full" value={telegramChatId} onChange={e => updateGeneralSetting('telegramChatId', e.target.value)} placeholder="ژمارەی Chat ID بنووسە لێرە" />
              <p className="text-[10px] text-gray-400 mt-2">بۆ وەرگرتنی Chat ID، مەسج بنێرە بۆ بۆتی @userinfobot لە تێلیگرام.</p>
            </div>
            <button onClick={() => { onAdminAuthChange(false); sessionStorage.removeItem('isAdminAuthenticated'); }} className="w-full py-4 rounded-3xl text-red-600 font-black bg-red-50">چوونەدەرەوە</button>
          </div>
        )}
      </div>
      <style>{`.input-admin { @apply p-5 bg-gray-50 rounded-3xl border border-gray-200 outline-none focus:border-orange-500 font-bold; }`}</style>
    </div>
  );
};

