import React, { useState } from 'react';
import { CartItem } from '../types';
import { TELEGRAM_BOT_TOKEN } from '../constants';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

declare var Swal: any;

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  telegramChatId: string;
  onUpdateQuantity: (id: string, delta: number) => void;
  onRemove: (id: string) => void;
  onClearCart: () => void;
  locationUrl: string | null;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  telegramChatId,
  onUpdateQuantity,
  onRemove,
  onClearCart,
  locationUrl
}) => {
  const [isSending, setIsSending] = useState(false);
  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleOrder = async () => {
    // Basic validation
    if (cart.length === 0) {
      Swal.fire({
        icon: 'warning',
        title: 'سەبەتە بەتاڵە',
        text: 'تکایە سەرەتا خواردن زیاد بکە بۆ سەبەتەکەت.',
        confirmButtonText: 'باشە'
      });
      return;
    }

    if (!telegramChatId) {
      Swal.fire({
        icon: 'error',
        title: 'هەڵە لە ڕێکخستن',
        text: 'تکایە سەرەتا Telegram Chat ID لە بەشی بەڕێوەبەر دابنێ.',
        confirmButtonText: 'تێگەیشتم'
      });
      return;
    }

    setIsSending(true);

    // Construct order text
    let text = `📦 **داواکاری نوێ لە Aram Food**\n\n`;
    cart.forEach((item, index) => {
      text += `${index + 1}. **${item.name}**\n   - بڕ: ${item.quantity} دانە\n   - نرخ: ${(item.price * item.quantity).toLocaleString()} IQD\n`;
    });
    text += `\n💰 **کۆی گشتی:** ${total.toLocaleString()} IQD`;

    if (locationUrl) {
      text += `\n\n📍 **لوکێشنی کڕیار:**\n${locationUrl}`;
    } else {
      text += `\n\n📍 **لوکێشن:** وەرنەگیراوە`;
    }

    try {
      console.log("Sending order to Telegram...");
      const response = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: telegramChatId,
          text: text,
          parse_mode: "Markdown"
        })
      });

      const result = await response.json();
      console.log("Telegram API Response:", result);

      if (!response.ok) {
        throw new Error(result.description || "هەڵەیەک لە ناردنی داتاکان بۆ تێلیگرام ڕوویدا.");
      }

      // Log to Firebase for record keeping
      await addDoc(collection(db, "orders"), {
        items: cart.map(i => `${i.quantity}x ${i.name}`),
        total,
        timestamp: Date.now()
      });

      // Show success message
      await Swal.fire({
        icon: 'success',
        title: 'داواکارییەکەت نێردرا',
        text: 'سوپاس بۆ کڕینەکەت، داواکارییەکەت گەیشتە بەشە پەیوەندیدارەکان.',
        confirmButtonText: 'باشە',
        confirmButtonColor: '#ea580c'
      });

      onClearCart();
      onClose();
    } catch (error: any) {
      console.error("Order process error:", error);
      Swal.fire({
        icon: 'error',
        title: 'هەڵەیەک ڕوویدا',
        text: `هەڵە: ${error.message || error}`,
        confirmButtonText: 'دووبارە هەوڵبدەرەوە'
      });
    } finally {
      setIsSending(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/60 backdrop-blur-sm">
      <div className="absolute inset-0" onClick={onClose} />
      <div className="bg-white rounded-t-[40px] h-[85vh] w-full flex flex-col relative animate-slide-up overflow-hidden text-black">
        <div className="p-8 border-b flex justify-between items-center">
          <h2 className="text-3xl font-black">سەبەتەکەم</h2>
          <button onClick={onClose} className="p-3 bg-gray-100 rounded-full">✕</button>
        </div>

        <div className="flex-grow overflow-y-auto p-6 space-y-4">
          {cart.map(item => (
            <div key={item.id} className="bg-gray-50 p-5 rounded-[32px] flex items-center gap-4">
              <img src={item.img} className="w-20 h-20 rounded-3xl object-cover bg-white" />
              <div className="flex-grow">
                <h3 className="font-black">{item.name}</h3>
                <div className="flex items-center gap-4 mt-2">
                  <button onClick={() => onUpdateQuantity(item.id, -1)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black">-</button>
                  <span className="font-black text-xl">{item.quantity}</span>
                  <button onClick={() => onUpdateQuantity(item.id, 1)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black">+</button>
                </div>
              </div>
              <button onClick={() => onRemove(item.id)} className="text-red-500 font-bold p-2">سڕینەوە</button>
            </div>
          ))}
          {cart.length === 0 && (
            <div className="text-center py-20 text-gray-400 font-bold">سەبەتەکەت بەتاڵە</div>
          )}
        </div>

        <div className="p-8 border-t bg-white space-y-4">
          <div className="flex justify-between items-center">
            <span className="text-gray-400 font-bold">کۆی گشتی</span>
            <span className="text-3xl font-black text-orange-600">{total.toLocaleString()} د.ع</span>
          </div>
          <button 
            disabled={isSending || cart.length === 0}
            onClick={handleOrder}
            className="w-full bg-[#0088cc] text-white py-6 rounded-[30px] font-black text-xl shadow-xl active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3"
          >
            {isSending ? (
              <div className="flex items-center gap-2">
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                <span>خەریکی ناردنە...</span>
              </div>
            ) : (
              <>
                <svg className="w-7 h-7" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.64 6.8c-.15 1.58-.8 5.42-1.13 7.19-.14.75-.42 1-.68 1.03-.58.05-1.02-.38-1.58-.75-.88-.58-1.38-.94-2.23-1.5-.99-.65-.35-1.01.22-1.59.15-.15 2.71-2.48 2.76-2.69a.2.2 0 00-.05-.18c-.06-.05-.14-.03-.21-.02-.09.02-1.49.95-4.22 2.79-.4.27-.76.41-1.08.4-.35-.01-1.02-.2-1.52-.36-.61-.2-1.1-.3-1.05-.63.02-.17.25-.34.69-.51 2.69-1.17 4.49-1.94 5.39-2.31 2.57-1.05 3.1-.1.23-3.1-.1.23-.2.43-.05.51z"/>
                </svg>
                <span>ناردنی داواکاری</span>
              </>
            )}
          </button>
        </div>
      </div>
      <style>{`@keyframes slide-up { from { transform: translateY(100%); } to { transform: translateY(0); } } .animate-slide-up { animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1); }`}</style>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  getDoc
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  // Defaulting to the new API key provided by the user if none is stored
  const [imgbbKey, setImgbbKey] = useState(localStorage.getItem('fastfood_imgbb_key_v1') || 'a88e98edaf80481202b926e42a5a7f3e');
  const [connectionStatus, setConnectionStatus] = useState({ firestore: true });

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, img: string, category: string}>({ 
    name: '', price: '', img: '', category: categories[1]?.id || 'burgers' 
  });

  useEffect(() => {
    const checkConn = async () => {
      try {
        await getDoc(doc(db, "settings", "general"));
        setConnectionStatus({ firestore: true });
      } catch (err) {
        setConnectionStatus({ firestore: false });
      }
    };
    checkConn();
  }, []);

  const stats = useMemo(() => {
    return { 
      totalProducts: products.length, 
      totalOrders: orderLogs.length, 
      popularCatName: categories.find(c => c.id === products[0]?.category)?.name || 'نادیار' 
    };
  }, [products, categories, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      alert('وشەی نهێنی هەڵەیە!');
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    const keyToUse = imgbbKey || 'a88e98edaf80481202b926e42a5a7f3e';
    setIsUploading(true);
    const formData = new FormData();
    formData.append('image', file);
    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${keyToUse}`, { method: 'POST', body: formData });
      const result = await response.json();

      if (result.success) {
        // Use display_url as requested, fallback to url (direct link)
        const directLink = result.data.display_url || result.data.url;
        console.log("Image uploaded successfully:", directLink);
        return directLink;
      } else {
        console.error("ImgBB Upload Failed:", result);
        alert(`نەتوانرا وێنەکە بەرزبکرێتەوە: ${result.error?.message || 'هەڵەیەکی نەزانراو'}`);
        return null;
      }
    } catch (error) {
      console.error("Upload Error:", error);
      alert('هەڵەیەک لە پەیوەندی بە ڕاژەی وێنە ڕوویدا');
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  const updateGeneralSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "general"), { [field]: value }, { merge: true });
  };

  if (!isLocalAdmin) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center p-6">
        <form onSubmit={handleLogin} className="bg-white p-8 rounded-[40px] shadow-xl w-full max-w-md border border-gray-100">
          <h2 className="text-2xl font-black text-center mb-6">بەشی بەڕێوەبەر</h2>
          <input 
            type="password" 
            placeholder="وشەی نهێنی" 
            className="w-full p-5 bg-gray-50 rounded-3xl border border-gray-200 mb-4 text-center text-2xl tracking-widest outline-none focus:border-orange-500" 
            value={passwordInput} 
            onChange={e => setPasswordInput(e.target.value)} 
          />
          <button className="w-full bg-orange-600 text-white py-5 rounded-3xl font-black text-lg">چوونەژوورەوە</button>
        </form>
      </div>
    );
  }

  return (
    <div className="flex flex-col lg:flex-row min-h-screen">
      <nav className="w-full lg:w-64 bg-white border-l border-gray-100 p-4 sticky top-0 h-auto lg:h-screen flex lg:flex-col gap-2 overflow-x-auto no-scrollbar">
        {['DASHBOARD', 'PRODUCTS', 'CATEGORIES', 'SETTINGS'].map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-4 rounded-3xl font-bold whitespace-nowrap transition-all ${activeTab === tab ? 'bg-orange-600 text-white' : 'text-gray-500 hover:bg-gray-50'}`}>
            {tab === 'DASHBOARD' ? 'سەرەتا' : tab === 'PRODUCTS' ? 'خواردنەکان' : tab === 'CATEGORIES' ? 'بەشەکان' : 'ڕێکخستن'}
          </button>
        ))}
      </nav>

      <div className="flex-grow p-4 lg:p-12 space-y-8 max-w-5xl mx-auto w-full">
        {activeTab === 'DASHBOARD' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-bold mb-1">کۆی خواردنەکان</div>
              <div className="text-4xl font-black">{stats.totalProducts}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-bold mb-1">کۆی داواکارییەکان</div>
              <div className="text-4xl font-black text-green-600">{stats.totalOrders}</div>
            </div>
          </div>
        )}

        {activeTab === 'PRODUCTS' && (
          <div className="space-y-8">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100">
              <h3 className="font-black text-xl mb-6">زیادکردنی بەرھەمی نوێ</h3>
              <form onSubmit={async (e) => {
                e.preventDefault();
                if (!productForm.img) {
                  alert("تکایە سەرەتا وێنەیەک بار بکە.");
                  return;
                }
                setIsLoading(true);
                try {
                  const pData = { 
                    name: productForm.name, 
                    price: parseInt(productForm.price), 
                    img: productForm.img, 
                    category: productForm.category 
                  };
                  await addDoc(collection(db, "menu"), pData);
                  setProductForm({ name: '', price: '', img: '', category: categories[1]?.id || 'burgers' });
                  alert("بەرھەمەکە بە سەرکەوتوویی زیادکرا");
                } catch (err) { 
                  alert("نەتوانرا بەرھەمەکە پاشکەوت بکرێت"); 
                } finally { 
                  setIsLoading(false); 
                }
              }} className="space-y-4">
                <input className="input-admin w-full" placeholder="ناوی خواردن" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} required />
                <div className="grid grid-cols-2 gap-4">
                  <input className="input-admin" type="number" placeholder="نرخ" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
                  <select className="input-admin" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value})}>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="relative h-48 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center overflow-hidden">
                  {productForm.img ? (
                    <img src={productForm.img} className="h-full w-full object-cover" alt="Preview" />
                  ) : (
                    <div className="flex flex-col items-center text-gray-400 text-center px-4">
                      <svg className="w-10 h-10 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                      </svg>
                      <span className="font-bold">کرتە بکە بۆ بارکردنی وێنە</span>
                      <p className="text-[10px] mt-1">تەنها وێنەی بەرھەمەکان</p>
                    </div>
                  )}
