              <input className="input-admin w-full" value={telegramChatId} onChange={e => updateGeneralSetting('telegramChatId', e.target.value)} />
            </div>
            <button onClick={() => { onAdminAuthChange(false); sessionStorage.removeItem('isAdminAuthenticated'); }} className="w-full py-5 rounded-[24px] text-red-600 font-black bg-red-50 hover:bg-red-100 transition-colors">چوونەدەرەوە</button>
          </div>
        )}
      </div>
      <style>{`.input-admin { @apply p-5 bg-slate-50 rounded-[20px] border border-slate-100 outline-none focus:border-orange-500 focus:bg-white font-black text-slate-700 transition-all; } .no-scrollbar::-webkit-scrollbar { display: none; }`}</style>
    </div>
  );
};

export interface Category {
  id: string;
  name: string;
  imageUrl: string;
}

export interface Product {
  id: string;
  name: string;
  price: number; // Base price (Small or Regular)
  priceM?: number; // Medium price
  priceL?: number; // Large price
  img: string;
  category: string;
}

export interface CartItem extends Product {
  quantity: number;
  selectedSize?: 'S' | 'M' | 'L';
  note?: string;
}

export interface OrderLog {
  id: string;
  timestamp: number;
  items: string[];
  total: number;
}

export type ViewState = 'MENU' | 'ADMIN';
export type AdminSubView = 'DASHBOARD' | 'PRODUCTS' | 'CATEGORIES' | 'ORDERS' | 'SETTINGS';

import React, { useState, useEffect, useMemo } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { CategoryBar } from './components/CategoryBar';
import { InAppBrowserOverlay } from './components/InAppBrowserOverlay';
import { Product, CartItem, ViewState, Category, OrderLog } from './types';
import { DEFAULT_CATEGORIES, ADD_TO_CART_SOUND_URL } from './constants';
import { db } from './firebase';
import { collection, onSnapshot, query, orderBy, doc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('');
  const [telegramChatId, setTelegramChatId] = useState('');
  const [businessLogo, setBusinessLogo] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);
  const [isLocalAdmin, setIsLocalAdmin] = useState(() => sessionStorage.getItem('isAdminAuthenticated') === 'true');
  const [locationUrl, setLocationUrl] = useState<string | null>(null);
  const [isInAppBrowser, setIsInAppBrowser] = useState(false);

  useEffect(() => {
    // Detection
    const ua = navigator.userAgent || navigator.vendor;
    if (ua.indexOf("FBAN") > -1 || ua.indexOf("FBAV") > -1 || ua.indexOf("Messenger") > -1) setIsInAppBrowser(true);

    // Auto Location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setLocationUrl(`https://www.google.com/maps?q=${pos.coords.latitude},${pos.coords.longitude}`),
        null,
        { enableHighAccuracy: true }
      );
    }

    // Real-time Products
    const unsubProducts = onSnapshot(query(collection(db, "menu"), orderBy("name")), (snap) => {
      const p: Product[] = [];
      snap.forEach(d => p.push({ id: d.id, ...d.data() } as Product));
      setProducts(p);
    });

    // Real-time Categories
    const unsubCategories = onSnapshot(query(collection(db, "categories"), orderBy("name")), (snap) => {
      const c: Category[] = [];
      snap.forEach(d => c.push({ id: d.id, ...d.data() } as Category));
      const finalCategories = c.length > 0 ? c : DEFAULT_CATEGORIES;
      setCategories(finalCategories);
    });

    const unsubSettings = onSnapshot(doc(db, "settings", "general"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setTelegramChatId(data.telegramChatId || '');
        setBusinessLogo(data.businessLogo || '');
      }
    });

    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("timestamp", "desc")), (snap) => {
      const o: OrderLog[] = [];
      snap.forEach(d => o.push({ id: d.id, ...d.data() } as OrderLog));
      setOrderLogs(o);
    });

    return () => { unsubProducts(); unsubCategories(); unsubSettings(); unsubOrders(); };
  }, []);

  // Automatically select the first category if none is selected
  useEffect(() => {
    if (categories.length > 0 && !selectedCategory) {
      setSelectedCategory(categories[0].id);
    } else if (categories.length > 0 && !categories.find(c => c.id === selectedCategory)) {
      setSelectedCategory(categories[0].id);
    }
  }, [categories, selectedCategory]);

  const filteredProducts = useMemo(() => {
    if (!selectedCategory) return [];
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    new Audio(ADD_TO_CART_SOUND_URL).play().catch(() => {});
    setCart(prev => {
      // Find if item with same ID and same SIZE exists
      const existing = prev.find(i => i.id === product.id && i.selectedSize === size);

      // Get correct price based on size
      let finalPrice = product.price;
      if (size === 'M' && product.priceM) finalPrice = product.priceM;
      if (size === 'L' && product.priceL) finalPrice = product.priceL;

      if (existing) {
        return prev.map(i => 
          (i.id === product.id && i.selectedSize === size) 
            ? { ...i, quantity: i.quantity + 1, price: finalPrice } 
            : i
        );
      }
      return [...prev, { ...product, price: finalPrice, quantity: 1, selectedSize: size }];
    });
  };

  const currentCategoryName = categories.find(c => c.id === selectedCategory)?.name || '';

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-black overflow-x-hidden">
      {isInAppBrowser && <InAppBrowserOverlay businessLogo={businessLogo} />}
      <Header currentView={view} onToggleAdmin={() => setView(v => v === 'MENU' ? 'ADMIN' : 'MENU')} businessLogo={businessLogo} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <CategoryBar categories={categories} selectedCategoryId={selectedCategory} onSelectCategory={setSelectedCategory} />
            <div className="max-w-4xl mx-auto px-4 py-8 pb-32">
              <div className="mb-8">
                <h2 className="text-3xl font-black">Aram Food Menu</h2>
                <p className="text-gray-400 font-bold mt-1">
                  {currentCategoryName ? `بەخێربێیت، سەیری ${currentCategoryName} بکە` : 'بەخێربێیت بۆ Aram Food'}
                </p>
              </div>

              {categories.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[40px] shadow-sm border border-gray-100">
                  <div className="text-5xl mb-4">👋</div>
                  <h3 className="text-2xl font-black text-slate-800">بەخێربێیت بۆ Aram Food</h3>
                  <p className="text-gray-400 font-bold mt-2 px-6">بەداخەوە ئێستا هیچ خواردنێک بەردەست نییە، تکایە کەمێکی تر سەردانمان بکەرەوە.</p>
                </div>
              ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {filteredProducts.map(p => {
                    const category = categories.find(c => c.id === p.category);
                    const isPizza = category?.name.toLowerCase().includes('pizza') || category?.name.includes('پیتزا');
                    return (
                      <ProductCard 
                        key={p.id} 
                        product={p} 
                        onAddToCart={(prod, size) => addToCart(prod, size)}
                        isPizza={isPizza}
                      />
                    );
                  })}
                </div>
              )}

              {categories.length > 0 && filteredProducts.length === 0 && (
                <div className="text-center py-20 text-gray-300 font-black text-xl">
                  هیچ خواردنێک لەم بەشەدا نییە
                </div>
              )}
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} categories={categories} isSoundEnabled={true} 
            telegramChatId={telegramChatId} businessLogo={businessLogo} 
            orderLogs={orderLogs} isLocalAdmin={isLocalAdmin} onAdminAuthChange={setIsLocalAdmin} 
          />
        )}
      </main>

      {view === 'MENU' && cart.length > 0 && <BottomNav cart={cart} onViewCart={() => setIsCartOpen(true)} />}

      <CartModal 
        isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} 
        telegramChatId={telegramChatId} locationUrl={locationUrl}
        onUpdateQuantity={(id, delta, size) => {
          setCart(c => c.map(i => (i.id === id && i.selectedSize === size) ? {...i, quantity: Math.max(1, i.quantity + delta)} : i));
        }}
        onRemove={(id, size) => setCart(c => c.filter(i => !(i.id === id && i.selectedSize === size)))}
        onClearCart={() => setCart([])}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  updateDoc
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

declare var Swal: any;

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [imgbbKey, setImgbbKey] = useState(localStorage.getItem('fastfood_imgbb_key_v1') || 'a88e98edaf80481202b926e42a5a7f3e');

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, priceM: string, priceL: string, img: string, category: string}>({ 
    name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' 
  });
  const [editingProductId, setEditingProductId] = useState<string | null>(null);

  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);

  useEffect(() => {
    if (!productForm.category && categories.length > 0) {
      setProductForm(prev => ({ ...prev, category: categories[0].id }));
    }
  }, [categories, productForm.category]);

  const stats = useMemo(() => {
    return { 
      totalProducts: products.length, 
      totalOrders: orderLogs.length, 
      totalRevenue: orderLogs.reduce((acc, curr) => acc + curr.total, 0)
    };
  }, [products, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      Swal.fire({
        icon: 'error',
        title: 'هەڵە',
        text: 'وشەی نهێنی هەڵەیە!',
        confirmButtonText: 'باشە'
      });
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    const keyToUse = imgbbKey || 'a88e98edaf80481202b926e42a5a7f3e';
    setIsUploading(true);
    const formData = new FormData();
    formData.append('image', file);
    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${keyToUse}`, { method: 'POST', body: formData });
      const result = await response.json();
      if (result.success) {
        return result.data.display_url || result.data.url;
      } else {
        Swal.fire({ icon: 'error', title: 'هەڵە لە بارکردن', text: result.error?.message || 'هەڵەیەکی نەزانراو ڕوویدا' });
        return null;
      }
    } catch (error) {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'هەڵەیەک لە پەیوەندی بە ڕاژەی وێنە ڕوویدا' });
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  const updateGeneralSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "general"), { [field]: value }, { merge: true });
  };

  const handleDeleteProduct = async (id: string, name: string) => {
    const result = await Swal.fire({
      title: 'دڵنیایت؟',
      text: `ئایا دڵنیایت لە سڕینەوەی (${name})؟`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'بەڵێ، بسڕەوە',
      cancelButtonText: 'نەخێر'
    });

    if (result.isConfirmed) {
      try {
        await deleteDoc(doc(db, "menu", id));
        Swal.fire({ title: 'سڕایەوە!', text: 'خواردنەکە بە سەرکەوتوویی سڕایەوە.', icon: 'success', timer: 1500, showConfirmButton: false });
      } catch (error) {
        Swal.fire({ title: 'هەڵە!', text: 'کێشەیەک لە سڕینەوە ڕوویدا.', icon: 'error' });
      }
    }
  };

  const startEditProduct = (p: Product) => {
    setEditingProductId(p.id);
    setProductForm({
      name: p.name,
      price: p.price.toString(),
      priceM: p.priceM?.toString() || '',
      priceL: p.priceL?.toString() || '',
      img: p.img,
      category: p.category
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cancelEditProduct = () => {
    setEditingProductId(null);
    setProductForm({ name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' });
  };

  const isPizzaCategory = useMemo(() => {
    const cat = categories.find(c => c.id === productForm.category);
    return cat?.name.toLowerCase().includes('pizza') || cat?.name.includes('پیتزا');
  }, [productForm.category, categories]);

  if (!isLocalAdmin) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center p-6">
        <form onSubmit={handleLogin} className="bg-white p-8 rounded-[40px] shadow-xl w-full max-w-md border border-gray-100">
          <h2 className="text-2xl font-black text-center mb-6 text-slate-800">بەشی بەڕێوەبەر</h2>
          <input 
            type="password" 
            placeholder="وشەی نهێنی" 
            className="w-full p-5 bg-gray-50 rounded-3xl border border-gray-200 mb-4 text-center text-2xl tracking-widest outline-none focus:border-orange-500 transition-all" 
            value={passwordInput} 
            onChange={e => setPasswordInput(e.target.value)} 
          />
          <button className="w-full bg-orange-600 text-white py-5 rounded-3xl font-black text-lg active:scale-95 shadow-lg shadow-orange-100">چوونەژوورەوە</button>
        </form>
      </div>
    );
  }

  return (
    <div className="flex flex-col lg:flex-row min-h-screen bg-slate-50">
      <nav className="w-full lg:w-64 bg-white border-l border-gray-100 p-4 sticky top-0 h-auto lg:h-screen flex lg:flex-col gap-2 overflow-x-auto no-scrollbar z-30">
        <div className="hidden lg:block p-4 mb-4">
          <h2 className="font-black text-xl text-slate-800">بەڕێوەبەر</h2>
          <p className="text-xs text-slate-400 font-bold">دەستکاری خواردنەکان بکە</p>
        </div>
        {[
          { id: 'DASHBOARD', icon: '📊', label: 'سەرەتا' },
          { id: 'ORDERS', icon: '📦', label: 'داواکارییەکان' },
          { id: 'PRODUCTS', icon: '🍔', label: 'خواردنەکان' },
          { id: 'CATEGORIES', icon: '📁', label: 'بەشەکان' },
          { id: 'SETTINGS', icon: '⚙️', label: 'ڕێکخستن' }
        ].map(tab => (
          <button 
            key={tab.id} 
            onClick={() => setActiveTab(tab.id as any)} 
            className={`px-6 py-4 rounded-3xl font-black whitespace-nowrap transition-all flex items-center gap-3 ${activeTab === tab.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-100' : 'text-gray-500 hover:bg-gray-50'}`}
          >
            <span>{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </nav>

      <div className="flex-grow p-4 lg:p-12 space-y-8 max-w-5xl mx-auto w-full">
        {activeTab === 'DASHBOARD' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی خواردنەکان</div>
              <div className="text-5xl font-black text-slate-800">{stats.totalProducts}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی داواکارییەکان</div>
              <div className="text-5xl font-black text-green-600">{stats.totalOrders}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی فرۆش</div>
              <div className="text-3xl font-black text-orange-600">{stats.totalRevenue.toLocaleString()} د.ع</div>
            </div>
          </div>
        )}

        {activeTab === 'PRODUCTS' && (
          <div className="space-y-8">
            <div className={`bg-white p-8 rounded-[40px] shadow-sm border-2 transition-colors ${editingProductId ? 'border-orange-500' : 'border-gray-100'}`}>
              <h3 className="font-black text-xl mb-6 text-slate-800">
                {editingProductId ? 'دەستکاری کردنی خواردن' : 'زیادکردنی بەرھەمی نوێ'}
              </h3>
              <form onSubmit={async (e) => {
                e.preventDefault();
                if (!productForm.img) {
                  Swal.fire({ icon: 'warning', title: 'وێنە نییە', text: 'تکایە سەرەتا وێنەیەەک بار بکە.' });
                  return;
                }
                setIsLoading(true);
                try {
                  const pData: any = { 
                    name: productForm.name, 
                    price: parseInt(productForm.price), 
                    img: productForm.img, 
                    category: productForm.category 
                  };

                  if (isPizzaCategory) {
                    if (productForm.priceM) pData.priceM = parseInt(productForm.priceM);
                    if (productForm.priceL) pData.priceL = parseInt(productForm.priceL);
                  }

                  if (editingProductId) {
                    await updateDoc(doc(db, "menu", editingProductId), pData);
                    setEditingProductId(null);
                    Swal.fire({ icon: 'success', title: 'نوێکرایەوە', text: 'بەرھەمەکە نوێکرایەوە', timer: 1500, showConfirmButton: false });
                  } else {
                    await addDoc(collection(db, "menu"), pData);
                    Swal.fire({ icon: 'success', title: 'سەرکەوتوو', text: 'بەرھەمەکە زیادکرا', timer: 1500, showConfirmButton: false });
                  }
                  setProductForm({ ...productForm, name: '', price: '', priceM: '', priceL: '', img: '' });
                } catch (err) { 
                  Swal.fire({ icon: 'error', title: 'هەڵە', text: 'کێشەیەک ڕوویدا' });
                } finally { 
                  setIsLoading(false); 
                }
              }} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 mr-2">ناوی خواردن</label>
                    <input className="input-admin w-full" placeholder="بۆ نموونە: پیتزای گۆشت" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} required />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 mr-2">بەش</label>
                    <select className="input-admin w-full appearance-none" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value})} required>
                      <option value="" disabled>بەشێک هەڵبژێرە</option>
                      {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                </div>

                {isPizzaCategory ? (
                  <div className="grid grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 mr-2">نرخ (S)</label>
                      <input className="input-admin w-full" type="number" placeholder="5000" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 mr-2">نرخ (M)</label>
                      <input className="input-admin w-full" type="number" placeholder="8000" value={productForm.priceM} onChange={e => setProductForm({...productForm, priceM: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 mr-2">نرخ (L)</label>
                      <input className="input-admin w-full" type="number" placeholder="12000" value={productForm.priceL} onChange={e => setProductForm({...productForm, priceL: e.target.value})} />
                    </div>
                  </div>
                ) : (
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 mr-2">نرخ (IQD)</label>
                    <input className="input-admin w-full" type="number" placeholder="٥٠٠٠" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
                  </div>
                )}

                <div className="relative h-56 bg-slate-50 rounded-[32px] border-2 border-dashed border-slate-200 flex flex-col items-center justify-center overflow-hidden transition-all hover:border-orange-200">
                  {productForm.img ? (
                    <img src={productForm.img} className="h-full w-full object-cover" alt="Preview" />
                  ) : (
                    <div className="flex flex-col items-center text-slate-400 text-center px-4">
                      <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center shadow-sm mb-3 text-orange-500">📸</div>
                      <span className="font-black text-sm">بارکردنی وێنە</span>
                    </div>
                  )}
                  <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      const url = await uploadToImgBB(file);
                      if (url) setProductForm(p => ({...p, img: url}));
                    }
                  }} />
                </div>
                <div className="flex gap-4">
                  <button disabled={isUploading || isLoading} className="flex-grow bg-orange-600 text-white py-5 rounded-[24px] font-black active:scale-95 shadow-xl shadow-orange-100">
                    {isLoading ? 'پاشکەوت دەکرێت...' : editingProductId ? 'نوێکردنەوەی بەرھەم' : 'پاشکەوتکردنی بەرھەم'}
                  </button>
                  {editingProductId && (
                    <button type="button" onClick={cancelEditProduct} className="bg-gray-100 text-gray-500 px-8 rounded-[24px] font-black hover:bg-gray-200 transition-colors">هەڵوەشاندنەوە</button>
                  )}
                </div>
              </form>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <h4 className="font-black text-slate-800 col-span-full mt-4">لیستی خواردنەکان ({products.length})</h4>
              {products.map(p => (
                <div key={p.id} className="bg-white p-4 rounded-[32px] border border-gray-100 flex items-center justify-between shadow-sm">
                  <div className="flex items-center gap-4">
                    <img src={p.img} className="w-20 h-20 rounded-2xl object-cover bg-slate-50" />
                    <div>
                      <div className="font-black text-slate-800">{p.name}</div>
                      <div className="text-orange-600 font-black text-sm">{p.price.toLocaleString()} IQD</div>
                      <div className="text-[10px] text-gray-400 font-black uppercase">{categories.find(c => c.id === p.category)?.name || 'بێ بەش'}</div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => startEditProduct(p)} className="w-10 h-10 flex items-center justify-center text-blue-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all">✏️</button>
                    <button onClick={() => handleDeleteProduct(p.id, p.name)} className="w-10 h-10 flex items-center justify-center text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all">🗑️</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
        {/* Rest of the AdminPanel remains same for CATEGORIES and SETTINGS */}
        {activeTab === 'CATEGORIES' && (
          <div className="space-y-8">
            <div className={`bg-white p-8 rounded-[40px] shadow-sm border-2 transition-colors ${editingCategoryId ? 'border-orange-500' : 'border-gray-100'}`}>
              <h3 className="font-black text-xl mb-6 text-slate-800">{editingCategoryId ? 'دەستکاری کردنی بەش' : 'زیادکردنی بەشی نوێ'}</h3>
              <form onSubmit={async (e) => {
                e.preventDefault();
                if (!categoryForm.imageUrl) { Swal.fire({ icon: 'warning', title: 'وێنە نییە', text: 'تکایە وێنەیەەک هەڵبژێرە.' }); return; }
                setIsLoading(true);
                try {
                  const cData = { name: categoryForm.name, imageUrl: categoryForm.imageUrl };
                  if (editingCategoryId) { await updateDoc(doc(db, "categories", editingCategoryId), cData); setEditingCategoryId(null); }
                  else { await addDoc(collection(db, "categories"), cData); }
                  setCategoryForm({ name: '', imageUrl: '' });
                } catch (err) { Swal.fire({ icon: 'error', title: 'هەڵە', text: 'کێشەیەک ڕوویدا' }); } finally { setIsLoading(false); }
              }} className="space-y-4">
                <input className="input-admin w-full" placeholder="ناوی بەش" value={categoryForm.name} onChange={e => setCategoryForm({...categoryForm, name: e.target.value})} required />
                <div className="relative h-40 bg-slate-50 rounded-[32px] border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden">
                  {categoryForm.imageUrl ? <img src={categoryForm.imageUrl} className="h-full w-full object-cover" /> : <span className="font-black text-slate-400">بارکردنی وێنەی بەش</span>}
                  <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={async (e) => { const file = e.target.files?.[0]; if (file) { const url = await uploadToImgBB(file); if (url) setCategoryForm(c => ({...c, imageUrl: url})); } }} />
                </div>
                <button className="w-full bg-orange-600 text-white py-5 rounded-[24px] font-black shadow-xl shadow-orange-100">پاشکەوتکردن</button>
              </form>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {categories.map(c => (
                <div key={c.id} className="bg-white p-4 rounded-[32px] border border-gray-100 flex items-center justify-between shadow-sm">
                  <div className="flex items-center gap-4"><img src={c.imageUrl} className="w-14 h-14 rounded-2xl object-cover" /><div className="font-black text-slate-800">{c.name}</div></div>
                  <div className="flex gap-2">
                    <button onClick={() => { setEditingCategoryId(c.id); setCategoryForm({ name: c.name, imageUrl: c.imageUrl }); window.scrollTo({top: 0, behavior:'smooth'}); }} className="w-10 h-10 flex items-center justify-center text-blue-400">✏️</button>
                    <button onClick={() => handleDeleteCategory(c.id, c.name)} className="w-10 h-10 flex items-center justify-center text-red-400">🗑️</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
        {activeTab === 'SETTINGS' && (
          <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 space-y-6">
            <h3 className="font-black text-xl text-slate-800">ڕێکخستنی گشتی</h3>
            <div><label className="block text-sm font-black text-slate-400 mb-2">ImgBB API Key</label><input className="input-admin w-full" value={imgbbKey} onChange={e => { setImgbbKey(e.target.value); localStorage.setItem('fastfood_imgbb_key_v1', e.target.value); }} /></div>
            <div><label className="block text-sm font-black text-slate-400 mb-2">Telegram Chat ID</label><input className="input-admin w-full" value={telegramChatId} onChange={e => updateGeneralSetting('telegramChatId', e.target.value)} /></div>
            <button onClick={() => { onAdminAuthChange(false); sessionStorage.removeItem('isAdminAuthenticated'); }} className="w-full py-5 rounded-[24px] text-red-600 font-black bg-red-50">چوونەدەرەوە</button>
          </div>
        )}
      </div>
      <style>{`.input-admin { @apply p-5 bg-slate-50 rounded-[20px] border border-slate-100 outline-none focus:border-orange-500 focus:bg-white font-black text-slate-700 transition-all; } .no-scrollbar::-webkit-scrollbar { display: none; }`}</style>
    </div>
  );
};

import React, { useState } from 'react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onAddToCart: (product: Product, size?: 'S' | 'M' | 'L') => void;
  isPizza?: boolean;
}

export const ProductCard: React.FC<ProductCardProps> = ({ product, onAddToCart, isPizza }) => {
  const [selectedSize, setSelectedSize] = useState<'S' | 'M' | 'L'>('S');

  const currentPrice = isPizza 
    ? (selectedSize === 'S' ? product.price : selectedSize === 'M' ? (product.priceM || product.price) : (product.priceL || product.price))
    : product.price;

  return (
    <div className="bg-white rounded-[32px] overflow-hidden flex flex-col border border-gray-100 shadow-sm transition-all hover:shadow-md">
      <div className="aspect-square overflow-hidden bg-gray-50">
        <img src={product.img} className="w-full h-full object-cover transition-transform hover:scale-105" alt={product.name} />
      </div>
      <div className="p-4 flex flex-col flex-grow">
        <h3 className="font-black text-sm mb-1 truncate">{product.name}</h3>

        {isPizza && (
          <div className="flex gap-2 my-2">
            {(['S', 'M', 'L'] as const).map(size => {
              // Hide size option if price for that size doesn't exist (except for S which is mandatory)
              if (size === 'M' && !product.priceM) return null;
              if (size === 'L' && !product.priceL) return null;

              return (
                <button
                  key={size}
                  onClick={() => setSelectedSize(size)}
                  className={`w-8 h-8 rounded-full text-[10px] font-black transition-all border ${
                    selectedSize === size 
                      ? 'bg-orange-600 text-white border-orange-600 shadow-md' 
                      : 'bg-white text-gray-400 border-gray-100'
                  }`}
                >
                  {size}
                </button>
              );
            })}
          </div>
        )}

        <p className="text-orange-600 font-black text-lg mb-3">
          {currentPrice.toLocaleString()} د.ع
        </p>

        <button 
          onClick={() => onAddToCart(product, isPizza ? selectedSize : undefined)}
          className="mt-auto w-full bg-orange-600 text-white py-3 rounded-2xl font-black text-xs active:scale-95 transition-all shadow-md shadow-orange-100"
        >
          زیادکردن +
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { CartItem } from '../types';
import { TELEGRAM_BOT_TOKEN } from '../constants';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

declare var Swal: any;

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  telegramChatId: string;
  onUpdateQuantity: (id: string, delta: number, size?: 'S' | 'M' | 'L') => void;
  onRemove: (id: string, size?: 'S' | 'M' | 'L') => void;
  onClearCart: () => void;
  locationUrl: string | null;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  telegramChatId,
  onUpdateQuantity,
  onRemove,
  onClearCart,
  locationUrl
}) => {
  const [isSending, setIsSending] = useState(false);
  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleOrder = async () => {
    if (cart.length === 0) {
      Swal.fire({ icon: 'warning', title: 'سەبەتە بەتاڵە', text: 'تکایە سەرەتا خواردن زیاد بکە بۆ سەبەتەکەت.', confirmButtonText: 'باشە' });
      return;
    }

    if (!telegramChatId) {
      Swal.fire({ icon: 'error', title: 'هەڵە لە ڕێکخستن', text: 'تکایە سەرەتا Telegram Chat ID لە بەشی بەڕێوەبەر دابنێ.', confirmButtonText: 'تێگەیشتم' });
      return;
    }

    setIsSending(true);

    let text = `📦 **داواکاری نوێ لە Aram Food**\n\n`;
    cart.forEach((item, index) => {
      const sizeStr = item.selectedSize ? ` (${item.selectedSize})` : '';
      text += `${index + 1}. **${item.name}${sizeStr}**\n   - بڕ: ${item.quantity} دانە\n   - نرخ: ${(item.price * item.quantity).toLocaleString()} IQD\n`;
    });
    text += `\n💰 **کۆی گشتی:** ${total.toLocaleString()} IQD`;

    if (locationUrl) text += `\n\n📍 **لوکێشنی کڕیار:**\n${locationUrl}`;
    else text += `\n\n📍 **لوکێشن:** وەرنەگیراوە`;

    try {
      const response = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ chat_id: telegramChatId, text: text, parse_mode: "Markdown" })
      });

      const result = await response.json();
      if (!response.ok) throw new Error(result.description || "هەڵەیەک لە ناردنی داتاکان بۆ تێلیگرام ڕوویدا.");

      await addDoc(collection(db, "orders"), {
        items: cart.map(i => `${i.quantity}x ${i.name}${i.selectedSize ? ' ('+i.selectedSize+')' : ''}`),
        total,
        timestamp: Date.now()
      });

      await Swal.fire({
        icon: 'success',
        title: 'داواکارییەکەت نێردرا',
        text: 'سوپاس بۆ کڕینەکەت، داواکارییەکەت گەیشتە بەشە پەیوەندیدارەکان.',
        confirmButtonText: 'باشە',
        confirmButtonColor: '#ea580c'
      });

      onClearCart();
      onClose();
    } catch (error: any) {
      Swal.fire({ icon: 'error', title: 'هەڵەیەک ڕوویدا', text: `هەڵە: ${error.message || error}`, confirmButtonText: 'دووبارە هەوڵبدەرەوە' });
    } finally {
      setIsSending(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/60 backdrop-blur-sm">
      <div className="absolute inset-0" onClick={onClose} />
      <div className="bg-white rounded-t-[40px] h-[85vh] w-full flex flex-col relative animate-slide-up overflow-hidden text-black">
        <div className="p-8 border-b flex justify-between items-center">
          <h2 className="text-3xl font-black">سەبەتەکەم</h2>
          <button onClick={onClose} className="p-3 bg-gray-100 rounded-full">✕</button>
        </div>

        <div className="flex-grow overflow-y-auto p-6 space-y-4">
          {cart.map((item, idx) => (
            <div key={`${item.id}-${item.selectedSize}-${idx}`} className="bg-gray-50 p-5 rounded-[32px] flex items-center gap-4">
              <img src={item.img} className="w-20 h-20 rounded-3xl object-cover bg-white" />
              <div className="flex-grow">
                <div className="flex items-center gap-2">
                  <h3 className="font-black">{item.name}</h3>
                  {item.selectedSize && (
                    <span className="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-black">{item.selectedSize}</span>
                  )}
                </div>
                <div className="flex items-center gap-4 mt-2">
                  <button onClick={() => onUpdateQuantity(item.id, -1, item.selectedSize)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black">-</button>
                  <span className="font-black text-xl">{item.quantity}</span>
                  <button onClick={() => onUpdateQuantity(item.id, 1, item.selectedSize)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black">+</button>
                </div>
              </div>
              <button onClick={() => onRemove(item.id, item.selectedSize)} className="text-red-500 font-bold p-2">سڕینەوە</button>
            </div>
          ))}
          {cart.length === 0 && <div className="text-center py-20 text-gray-400 font-bold">سەبەتەکەت بەتاڵە</div>}
        </div>

        <div className="p-8 border-t bg-white space-y-4">
          <div className="flex justify-between items-center">
            <span className="text-gray-400 font-bold">کۆی گشتی</span>
            <span className="text-3xl font-black text-orange-600">{total.toLocaleString()} د.ع</span>
          </div>
          <button 
            disabled={isSending || cart.length === 0}
            onClick={handleOrder}
            className="w-full bg-[#0088cc] text-white py-6 rounded-[30px] font-black text-xl shadow-xl active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3"
          >
            {isSending ? (
              <div className="flex items-center gap-2"><div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div><span>خەریکی ناردنە...</span></div>
            ) : (
              <>
                <svg className="w-7 h-7" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.64 6.8c-.15 1.58-.8 5.42-1.13 7.19-.14.75-.42 1-.68 1.03-.58.05-1.02-.38-1.58-.75-.88-.58-1.38-.94-2.23-1.5-.99-.65-.35-1.01.22-1.59.15-.15 2.71-2.48 2.76-2.69a.2.2 0 00-.05-.18c-.06-.05-.14-.03-.21-.02-.09.02-1.49.95-4.22 2.79-.4.27-.76.41-1.08.4-.35-.01-1.02-.2-1.52-.36-.61-.2-1.1-.3-1.05-.63.02-.17.25-.34.69-.51 2.69-1.17 4.49-1.94 5.39-2.31 2.57-1.05 3.1-.1.23-3.1-.1.23-.2.43-.05.51z"/></svg>
                <span>ناردنی داواکاری</span>
              </>
            )}
          </button>
        </div>
      </div>
      <style>{`@keyframes slide-up { from { transform: translateY(100%); } to { transform: translateY(0); } } .animate-slide-up { animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1); }`}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  updateDoc
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

declare var Swal: any;

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [imgbbKey, setImgbbKey] = useState(localStorage.getItem('fastfood_imgbb_key_v1') || 'a88e98edaf80481202b926e42a5a7f3e');

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, priceM: string, priceL: string, img: string, category: string}>({ 
    name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' 
  });
  const [editingProductId, setEditingProductId] = useState<string | null>(null);

  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);

  useEffect(() => {
    if (!productForm.category && categories.length > 0) {
      setProductForm(prev => ({ ...prev, category: categories[0].id }));
    }
  }, [categories, productForm.category]);

  const stats = useMemo(() => {
    return { 
      totalProducts: products.length, 
      totalOrders: orderLogs.length, 
      totalRevenue: orderLogs.reduce((acc, curr) => acc + curr.total, 0)
    };
  }, [products, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      Swal.fire({
        icon: 'error',
        title: 'هەڵە',
        text: 'وشەی نهێنی هەڵەیە!',
        confirmButtonText: 'باشە'
      });
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    const keyToUse = imgbbKey || 'a88e98edaf80481202b926e42a5a7f3e';
    setIsUploading(true);
    const formData = new FormData();
    formData.append('image', file);
    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${keyToUse}`, { method: 'POST', body: formData });
      const result = await response.json();
      if (result.success) {
        return result.data.display_url || result.data.url;
      } else {
        Swal.fire({ icon: 'error', title: 'هەڵە لە بارکردن', text: result.error?.message || 'هەڵەیەکی نەزانراو ڕوویدا' });
        return null;
      }
    } catch (error) {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'هەڵەیەک لە پەیوەندی بە ڕاژەی وێنە ڕوویدا' });
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  const updateGeneralSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "general"), { [field]: value }, { merge: true });
  };

  const handleDeleteProduct = async (id: string, name: string) => {
    const result = await Swal.fire({
      title: 'دڵنیایت؟',
      text: `ئایا دڵنیایت لە سڕینەوەی (${name})؟`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'بەڵێ، بسڕەوە',
      cancelButtonText: 'نەخێر'
    });

    if (result.isConfirmed) {
      try {
        await deleteDoc(doc(db, "menu", id));
        Swal.fire({ title: 'سڕایەوە!', text: 'خواردنەکە بە سەرکەوتوویی سڕایەوە.', icon: 'success', timer: 1500, showConfirmButton: false });
      } catch (error) {
        Swal.fire({ title: 'هەڵە!', text: 'کێشەیەک لە سڕینەوە ڕوویدا.', icon: 'error' });
      }
    }
  };

  // Fix: Added missing handleDeleteCategory function
  const handleDeleteCategory = async (id: string, name: string) => {
    const result = await Swal.fire({
      title: 'دڵنیایت؟',
      text: `ئایا دڵنیایت لە سڕینەوەی بەشی (${name})؟ خواردنەکانی ئەم بەشە لەوانەیە وەک بێ بەش دەربکەون.`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'بەڵێ، بسڕەوە',
      cancelButtonText: 'نەخێر'
    });

    if (result.isConfirmed) {
      try {
        await deleteDoc(doc(db, "categories", id));
        Swal.fire({ title: 'سڕایەوە!', text: 'بەشەکە بە سەرکەوتوویی سڕایەوە.', icon: 'success', timer: 1500, showConfirmButton: false });
      } catch (error) {
        Swal.fire({ title: 'هەڵە!', text: 'کێشەیەک لە سڕینەوە ڕوویدا.', icon: 'error' });
      }
    }
  };

  const startEditProduct = (p: Product) => {
    setEditingProductId(p.id);
    setProductForm({
      name: p.name,
      price: p.price.toString(),
      priceM: p.priceM?.toString() || '',
      priceL: p.priceL?.toString() || '',
      img: p.img,
      category: p.category
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cancelEditProduct = () => {
    setEditingProductId(null);
    setProductForm({ name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' });
  };

  const isPizzaCategory = useMemo(() => {
    const cat = categories.find(c => c.id === productForm.category);
    return cat?.name.toLowerCase().includes('pizza') || cat?.name.includes('پیتزا');
  }, [productForm.category, categories]);

  if (!isLocalAdmin) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center p-6">
        <form onSubmit={handleLogin} className="bg-white p-8 rounded-[40px] shadow-xl w-full max-w-md border border-gray-100">
          <h2 className="text-2xl font-black text-center mb-6 text-slate-800">بەشی بەڕێوەبەر</h2>
          <input 
            type="password" 
            placeholder="وشەی نهێنی" 
            className="w-full p-5 bg-gray-50 rounded-3xl border border-gray-200 mb-4 text-center text-2xl tracking-widest outline-none focus:border-orange-500 transition-all" 
            value={passwordInput} 
            onChange={e => setPasswordInput(e.target.value)} 
          />
          <button className="w-full bg-orange-600 text-white py-5 rounded-3xl font-black text-lg active:scale-95 shadow-lg shadow-orange-100">چوونەژوورەوە</button>
        </form>
      </div>
    );
  }

  return (
    <div className="flex flex-col lg:flex-row min-h-screen bg-slate-50">
      <nav className="w-full lg:w-64 bg-white border-l border-gray-100 p-4 sticky top-0 h-auto lg:h-screen flex lg:flex-col gap-2 overflow-x-auto no-scrollbar z-30">
        <div className="hidden lg:block p-4 mb-4">
          <h2 className="font-black text-xl text-slate-800">بەڕێوەبەر</h2>
          <p className="text-xs text-slate-400 font-bold">دەستکاری خواردنەکان بکە</p>
        </div>
        {[
          { id: 'DASHBOARD', icon: '📊', label: 'سەرەتا' },
          { id: 'ORDERS', icon: '📦', label: 'داواکارییەکان' },
          { id: 'PRODUCTS', icon: '🍔', label: 'خواردنەکان' },
          { id: 'CATEGORIES', icon: '📁', label: 'بەشەکان' },
          { id: 'SETTINGS', icon: '⚙️', label: 'ڕێکخستن' }
        ].map(tab => (
          <button 
            key={tab.id} 
            onClick={() => setActiveTab(tab.id as any)} 
            className={`px-6 py-4 rounded-3xl font-black whitespace-nowrap transition-all flex items-center gap-3 ${activeTab === tab.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-100' : 'text-gray-500 hover:bg-gray-50'}`}
          >
            <span>{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </nav>

      <div className="flex-grow p-4 lg:p-12 space-y-8 max-w-5xl mx-auto w-full">
        {activeTab === 'DASHBOARD' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی خواردنەکان</div>
              <div className="text-5xl font-black text-slate-800">{stats.totalProducts}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی داواکارییەکان</div>
              <div className="text-5xl font-black text-green-600">{stats.totalOrders}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی فرۆش</div>
              <div className="text-3xl font-black text-orange-600">{stats.totalRevenue.toLocaleString()} د.ع</div>
            </div>
          </div>
        )}

        {activeTab === 'PRODUCTS' && (
          <div className="space-y-8">
            <div className={`bg-white p-8 rounded-[40px] shadow-sm border-2 transition-colors ${editingProductId ? 'border-orange-500' : 'border-gray-100'}`}>
              <h3 className="font-black text-xl mb-6 text-slate-800">
                {editingProductId ? 'دەستکاری کردنی خواردن' : 'زیادکردنی بەرھەمی نوێ'}
              </h3>
              <form onSubmit={async (e) => {
                e.preventDefault();
                if (!productForm.img) {
                  Swal.fire({ icon: 'warning', title: 'وێنە نییە', text: 'تکایە سەرەتا وێنەیەەک بار بکە.' });
                  return;
                }
                setIsLoading(true);
                try {
                  const pData: any = { 
                    name: productForm.name, 
                    price: parseInt(productForm.price), 
                    img: productForm.img, 
                    category: productForm.category 
                  };

                  if (isPizzaCategory) {
                    if (productForm.priceM) pData.priceM = parseInt(productForm.priceM);
                    if (productForm.priceL) pData.priceL = parseInt(productForm.priceL);
                  }

                  if (editingProductId) {
                    await updateDoc(doc(db, "menu", editingProductId), pData);
                    setEditingProductId(null);
                    Swal.fire({ icon: 'success', title: 'نوێکرایەوە', text: 'بەرھەمەکە نوێکرایەوە', timer: 1500, showConfirmButton: false });
                  } else {
                    await addDoc(collection(db, "menu"), pData);
                    Swal.fire({ icon: 'success', title: 'سەرکەوتوو', text: 'بەرھەمەکە زیادکرا', timer: 1500, showConfirmButton: false });
                  }
                  setProductForm({ ...productForm, name: '', price: '', priceM: '', priceL: '', img: '' });
                } catch (err) { 
                  Swal.fire({ icon: 'error', title: 'هەڵە', text: 'کێشەیەک ڕوویدا' });
                } finally { 
                  setIsLoading(false); 
                }
              }} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 mr-2">ناوی خواردن</label>
                    <input className="input-admin w-full" placeholder="بۆ نموونە: پیتزای گۆشت" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} required />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 mr-2">بەش</label>
                    <select className="input-admin w-full appearance-none" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value})} required>
                      <option value="" disabled>بەشێک هەڵبژێرە</option>
                      {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                </div>

                {isPizzaCategory ? (
                  <div className="grid grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 mr-2">نرخ (S)</label>
                      <input className="input-admin w-full" type="number" placeholder="5000" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 mr-2">نرخ (M)</label>
                      <input className="input-admin w-full" type="number" placeholder="8000" value={productForm.priceM} onChange={e => setProductForm({...productForm, priceM: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 mr-2">نرخ (L)</label>
                      <input className="input-admin w-full" type="number" placeholder="12000" value={productForm.priceL} onChange={e => setProductForm({...productForm, priceL: e.target.value})} />
                    </div>
                  </div>
                ) : (
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 mr-2">نرخ (IQD)</label>
                    <input className="input-admin w-full" type="number" placeholder="٥٠٠٠" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
                  </div>
                )}

                <div className="relative h-56 bg-slate-50 rounded-[32px] border-2 border-dashed border-slate-200 flex flex-col items-center justify-center overflow-hidden transition-all hover:border-orange-200">
                  {productForm.img ? (
                    <img src={productForm.img} className="h-full w-full object-cover" alt="Preview" />
                  ) : (
                    <div className="flex flex-col items-center text-slate-400 text-center px-4">
                      <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center shadow-sm mb-3 text-orange-500">📸</div>
                      <span className="font-black text-sm">بارکردنی وێنە</span>
                    </div>
                  )}
                  <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      const url = await uploadToImgBB(file);
                      if (url) setProductForm(p => ({...p, img: url}));
                    }
                  }} />
                </div>
                <div className="flex gap-4">
                  <button disabled={isUploading || isLoading} className="flex-grow bg-orange-600 text-white py-5 rounded-[24px] font-black active:scale-95 shadow-xl shadow-orange-100">
                    {isLoading ? 'پاشکەوت دەکرێت...' : editingProductId ? 'نوێکردنەوەی بەرھەم' : 'پاشکەوتکردنی بەرھەم'}
                  </button>
                  {editingProductId && (
                    <button type="button" onClick={cancelEditProduct} className="bg-gray-100 text-gray-500 px-8 rounded-[24px] font-black hover:bg-gray-200 transition-colors">هەڵوەشاندنەوە</button>
                  )}
                </div>
              </form>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <h4 className="font-black text-slate-800 col-span-full mt-4">لیستی خواردنەکان ({products.length})</h4>
              {products.map(p => (
                <div key={p.id} className="bg-white p-4 rounded-[32px] border border-gray-100 flex items-center justify-between shadow-sm">
                  <div className="flex items-center gap-4">
                    <img src={p.img} className="w-20 h-20 rounded-2xl object-cover bg-slate-50" />
                    <div>
                      <div className="font-black text-slate-800">{p.name}</div>
                      <div className="text-orange-600 font-black text-sm">{p.price.toLocaleString()} IQD</div>
                      <div className="text-[10px] text-gray-400 font-black uppercase">{categories.find(c => c.id === p.category)?.name || 'بێ بەش'}</div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => startEditProduct(p)} className="w-10 h-10 flex items-center justify-center text-blue-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all">✏️</button>
                    <button onClick={() => handleDeleteProduct(p.id, p.name)} className="w-10 h-10 flex items-center justify-center text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all">🗑️</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'CATEGORIES' && (
          <div className="space-y-8">
            <div className={`bg-white p-8 rounded-[40px] shadow-sm border-2 transition-colors ${editingCategoryId ? 'border-orange-500' : 'border-gray-100'}`}>
              <h3 className="font-black text-xl mb-6 text-slate-800">{editingCategoryId ? 'دەستکاری کردنی بەش' : 'زیادکردنی بەشی نوێ'}</h3>
              <form onSubmit={async (e) => {
                e.preventDefault();
                if (!categoryForm.imageUrl) { Swal.fire({ icon: 'warning', title: 'وێنە نییە', text: 'تکایە وێنەیەەک هەڵبژێرە.' }); return; }
                setIsLoading(true);
                try {
                  const cData = { name: categoryForm.name, imageUrl: categoryForm.imageUrl };
                  if (editingCategoryId) { 
                    await updateDoc(doc(db, "categories", editingCategoryId), cData); 
                    setEditingCategoryId(null); 
                    Swal.fire({ icon: 'success', title: 'نوێکرایەوە', text: 'بەشەکە نوێکرایەوە', timer: 1500, showConfirmButton: false });
                  } else { 
                    await addDoc(collection(db, "categories"), cData); 
                    Swal.fire({ icon: 'success', title: 'سەرکەوتوو', text: 'بەشەکە زیادکرا', timer: 1500, showConfirmButton: false });
                  }
                  setCategoryForm({ name: '', imageUrl: '' });
                } catch (err) { 
                  Swal.fire({ icon: 'error', title: 'هەڵە', text: 'کێشەیەک ڕوویدا' }); 
                } finally { 
                  setIsLoading(false); 
                }
              }} className="space-y-4">
                <input className="input-admin w-full" placeholder="ناوی بەش" value={categoryForm.name} onChange={e => setCategoryForm({...categoryForm, name: e.target.value})} required />
                <div className="relative h-40 bg-slate-50 rounded-[32px] border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden">
                  {categoryForm.imageUrl ? <img src={categoryForm.imageUrl} className="h-full w-full object-cover" /> : <span className="font-black text-slate-400">بارکردنی وێنەی بەش</span>}
                  <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={async (e) => { const file = e.target.files?.[0]; if (file) { const url = await uploadToImgBB(file); if (url) setCategoryForm(c => ({...c, imageUrl: url})); } }} />
                </div>
                <button disabled={isUploading || isLoading} className="w-full bg-orange-600 text-white py-5 rounded-[24px] font-black shadow-xl shadow-orange-100">
                  {isLoading ? 'پاشکەوت دەکرێت...' : editingCategoryId ? 'نوێکردنەوەی بەش' : 'پاشکەوتکردنی بەش'}
                </button>
                {editingCategoryId && (
                  <button type="button" onClick={() => { setEditingCategoryId(null); setCategoryForm({ name: '', imageUrl: '' }); }} className="w-full mt-2 bg-gray-100 text-gray-500 py-3 rounded-[24px] font-black hover:bg-gray-200 transition-colors">هەڵوەشاندنەوە</button>
                )}
              </form>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {categories.map(c => (
                <div key={c.id} className="bg-white p-4 rounded-[32px] border border-gray-100 flex items-center justify-between shadow-sm">
                  <div className="flex items-center gap-4"><img src={c.imageUrl} className="w-14 h-14 rounded-2xl object-cover" /><div className="font-black text-slate-800">{c.name}</div></div>
                  <div className="flex gap-2">
                    <button onClick={() => { setEditingCategoryId(c.id); setCategoryForm({ name: c.name, imageUrl: c.imageUrl }); window.scrollTo({top: 0, behavior:'smooth'}); }} className="w-10 h-10 flex items-center justify-center text-blue-400">✏️</button>
                    <button onClick={() => handleDeleteCategory(c.id, c.name)} className="w-10 h-10 flex items-center justify-center text-red-400">🗑️</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'ORDERS' && (
          <div className="space-y-4">
            <h3 className="font-black text-xl text-slate-800">دوایین داواکارییەکان</h3>
            {orderLogs.length === 0 ? (
              <div className="bg-white p-12 rounded-[40px] text-center border border-gray-100 text-gray-400 font-black">هیچ داواکارییەک تۆمار نەکراوە</div>
            ) : (
              <div className="space-y-4">
                {orderLogs.map(log => (
                  <div key={log.id} className="bg-white p-6 rounded-[32px] border border-gray-100 shadow-sm">
                    <div className="flex justify-between items-start mb-4">
                      <div>
                        <div className="text-xs text-gray-400 font-black mb-1">
                          {new Date(log.timestamp).toLocaleString('ku-IQ', { hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit', year: 'numeric' })}
                        </div>
                        <div className="font-black text-slate-800">داواکاری #{log.id.slice(-4)}</div>
                      </div>
                      <div className="text-orange-600 font-black">{log.total.toLocaleString()} IQD</div>
                    </div>
                    <div className="space-y-2 border-t pt-4">
                      {log.items.map((item, idx) => (
                        <div key={idx} className="text-sm text-gray-600 font-bold flex gap-2">
                          <span className="text-orange-500">•</span>
                          {item}
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'SETTINGS' && (
          <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 space-y-6">
            <h3 className="font-black text-xl text-slate-800">ڕێکخستنی گشتی</h3>
            <div><label className="block text-sm font-black text-slate-400 mb-2">ImgBB API Key</label><input className="input-admin w-full" value={imgbbKey} onChange={e => { setImgbbKey(e.target.value); localStorage.setItem('fastfood_imgbb_key_v1', e.target.value); }} /></div>
            <div><label className="block text-sm font-black text-slate-400 mb-2">Telegram Chat ID</label><input className="input-admin w-full" value={telegramChatId} onChange={e => updateGeneralSetting('telegramChatId', e.target.value)} /></div>
            <button onClick={() => { onAdminAuthChange(false); sessionStorage.removeItem('isAdminAuthenticated'); }} className="w-full py-5 rounded-[24px] text-red-600 font-black bg-red-50 hover:bg-red-100 transition-colors">چوونەدەرەوە</button>
          </div>
        )}
      </div>
      <style>{`.input-admin { @apply p-5 bg-slate-50 rounded-[20px] border border-slate-100 outline-none focus:border-orange-500 focus:bg-white font-black text-slate-700 transition-all; } .no-scrollbar::-webkit-scrollbar { display: none; }`}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  updateDoc
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

declare var Swal: any;

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLogoUploading, setIsLogoUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [imgbbKey, setImgbbKey] = useState(localStorage.getItem('fastfood_imgbb_key_v1') || 'a88e98edaf80481202b926e42a5a7f3e');

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, priceM: string, priceL: string, img: string, category: string}>({ 
    name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' 
  });
  const [editingProductId, setEditingProductId] = useState<string | null>(null);

  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);

  useEffect(() => {
    if (!productForm.category && categories.length > 0) {
      setProductForm(prev => ({ ...prev, category: categories[0].id }));
    }
  }, [categories, productForm.category]);

  const stats = useMemo(() => {
    return { 
      totalProducts: products.length, 
      totalOrders: orderLogs.length, 
      totalRevenue: orderLogs.reduce((acc, curr) => acc + curr.total, 0)
    };
  }, [products, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      Swal.fire({
        icon: 'error',
        title: 'هەڵە',
        text: 'وشەی نهێنی هەڵەیە!',
        confirmButtonText: 'باشە'
      });
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    const keyToUse = imgbbKey || 'a88e98edaf80481202b926e42a5a7f3e';
    const formData = new FormData();
    formData.append('image', file);
    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${keyToUse}`, { method: 'POST', body: formData });
      const result = await response.json();
      if (result.success) {
        return result.data.display_url || result.data.url;
      } else {
        Swal.fire({ icon: 'error', title: 'هەڵە لە بارکردن', text: result.error?.message || 'هەڵەیەکی نەزانراو ڕوویدا' });
        return null;
      }
    } catch (error) {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'هەڵەیەک لە پەیوەندی بە ڕاژەی وێنە ڕوویدا' });
      return null;
    }
  };

  const updateGeneralSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "general"), { [field]: value }, { merge: true });
  };

  const handleDeleteProduct = async (id: string, name: string) => {
    const result = await Swal.fire({
      title: 'دڵنیایت؟',
      text: `ئایا دڵنیایت لە سڕینەوەی (${name})؟`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'بەڵێ، بسڕەوە',
      cancelButtonText: 'نەخێر'
    });

    if (result.isConfirmed) {
      try {
        await deleteDoc(doc(db, "menu", id));
        Swal.fire({ title: 'سڕایەوە!', text: 'خواردنەکە بە سەرکەوتوویی سڕایەوە.', icon: 'success', timer: 1500, showConfirmButton: false });
      } catch (error) {
        Swal.fire({ title: 'هەڵە!', text: 'کێشەیەک لە سڕینەوە ڕوویدا.', icon: 'error' });
      }
    }
  };

  const handleDeleteCategory = async (id: string, name: string) => {
    const result = await Swal.fire({
      title: 'دڵنیایت؟',
      text: `ئایا دڵنیایت لە سڕینەوەی بەشی (${name})؟ خواردنەکانی ئەم بەشە لەوانەیە وەک بێ بەش دەربکەون.`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'بەڵێ، بسڕەوە',
      cancelButtonText: 'نەخێر'
    });

    if (result.isConfirmed) {
      try {
        await deleteDoc(doc(db, "categories", id));
        Swal.fire({ title: 'سڕایەوە!', text: 'بەشەکە بە سەرکەوتوویی سڕایەوە.', icon: 'success', timer: 1500, showConfirmButton: false });
      } catch (error) {
        Swal.fire({ title: 'هەڵە!', text: 'کێشەیەک لە سڕینەوە ڕوویدا.', icon: 'error' });
      }
    }
  };

  const startEditProduct = (p: Product) => {
    setEditingProductId(p.id);
    setProductForm({
