import React, { useState, useMemo, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  updateDoc
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

declare var Swal: any;

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLogoUploading, setIsLogoUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [imgbbKey, setImgbbKey] = useState(localStorage.getItem('fastfood_imgbb_key_v1') || 'a88e98edaf80481202b926e42a5a7f3e');

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, priceM: string, priceL: string, img: string, category: string}>({ 
    name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' 
  });
  const [editingProductId, setEditingProductId] = useState<string | null>(null);

  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);

  useEffect(() => {
    if (!productForm.category && categories.length > 0) {
      setProductForm(prev => ({ ...prev, category: categories[0].id }));
    }
  }, [categories, productForm.category]);

  const stats = useMemo(() => {
    return { 
      totalProducts: products.length, 
      totalOrders: orderLogs.length, 
      totalRevenue: orderLogs.reduce((acc, curr) => acc + curr.total, 0)
    };
  }, [products, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      Swal.fire({
        icon: 'error',
        title: 'هەڵە',
        text: 'وشەی نهێنی هەڵەیە!',
        confirmButtonText: 'باشە'
      });
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    const keyToUse = imgbbKey || 'a88e98edaf80481202b926e42a5a7f3e';
    const formData = new FormData();
    formData.append('image', file);
    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${keyToUse}`, { method: 'POST', body: formData });
      const result = await response.json();
      if (result.success) {
        return result.data.display_url || result.data.url;
      } else {
        Swal.fire({ icon: 'error', title: 'هەڵە لە بارکردن', text: result.error?.message || 'هەڵەیەکی نەزانراو ڕوویدا' });
        return null;
      }
    } catch (error) {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'هەڵەیەک لە پەیوەندی بە ڕاژەی وێنە ڕوویدا' });
      return null;
    }
  };

  const updateGeneralSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "general"), { [field]: value }, { merge: true });
  };

  const updateThemeSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "theme"), { [field]: value }, { merge: true });
  };

  const handleDeleteProduct = async (id: string, name: string) => {
    const result = await Swal.fire({
      title: 'دڵنیایت؟',
      text: `ئایا دڵنیایت لە سڕینەوەی (${name})؟`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'بەڵێ، بسڕەوە',
      cancelButtonText: 'نەخێر'
    });

    if (result.isConfirmed) {
      try {
        await deleteDoc(doc(db, "menu", id));
        Swal.fire({ title: 'سڕایەوە!', text: 'خواردنەکە بە سەرکەوتوویی سڕایەوە.', icon: 'success', timer: 1500, showConfirmButton: false });
      } catch (error) {
        Swal.fire({ title: 'هەڵە!', text: 'کێشەیەک لە سڕینەوە ڕوویدا.', icon: 'error' });
      }
    }
  };

  const handleDeleteCategory = async (id: string, name: string) => {
    const result = await Swal.fire({
      title: 'دڵنیایت؟',
      text: `ئایا دڵنیایت لە سڕینەوەی بەشی (${name})؟ خواردنەکانی ئەم بەشە لەوانەیە وەک بێ بەش دەربکەون.`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'بەڵێ، بسڕەوە',
      cancelButtonText: 'نەخێر'
    });

    if (result.isConfirmed) {
      try {
        await deleteDoc(doc(db, "categories", id));
        Swal.fire({ title: 'سڕایەوە!', text: 'بەشەکە بە سەرکەوتوویی سڕایەوە.', icon: 'success', timer: 1500, showConfirmButton: false });
      } catch (error) {
        Swal.fire({ title: 'هەڵە!', text: 'کێشەیەک لە سڕینەوە ڕوویدا.', icon: 'error' });
      }
    }
  };

  const startEditProduct = (p: Product) => {
    setEditingProductId(p.id);
    setProductForm({
      name: p.name,
      price: p.price.toString(),
      priceM: p.priceM?.toString() || '',
      priceL: p.priceL?.toString() || '',
      img: p.img,
      category: p.category
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cancelEditProduct = () => {
    setEditingProductId(null);
    setProductForm({ name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' });
  };

  const isPizzaCategory = useMemo(() => {
    const cat = categories.find(c => c.id === productForm.category);
    return cat?.name.toLowerCase().includes('pizza') || cat?.name.includes('پیتزا');
  }, [productForm.category, categories]);

  if (!isLocalAdmin) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center p-6">
        <form onSubmit={handleLogin} className="bg-white p-8 rounded-[40px] shadow-xl w-full max-w-md border border-gray-100">
          <h2 className="text-2xl font-black text-center mb-6 text-slate-800">بەشی بەڕێوەبەر</h2>
          <input 
            type="password" 
            placeholder="وشەی نهێنی" 
            className="w-full p-5 bg-gray-50 rounded-3xl border border-gray-200 mb-4 text-center text-2xl tracking-widest outline-none focus:border-orange-500 transition-all" 
            value={passwordInput} 
            onChange={e => setPasswordInput(e.target.value)} 
          />
          <button className="w-full bg-orange-600 text-white py-5 rounded-3xl font-black text-lg active:scale-95 shadow-lg shadow-orange-100">چوونەژوورەوە</button>
        </form>
      </div>
    );
  }

  return (
    <div className="flex flex-col lg:flex-row min-h-screen bg-slate-50">
      <nav className="w-full lg:w-64 bg-white border-l border-gray-100 p-4 sticky top-0 h-auto lg:h-screen flex lg:flex-col gap-2 overflow-x-auto no-scrollbar z-30">
        <div className="hidden lg:block p-4 mb-4 text-center">
          {businessLogo && <img src={businessLogo} className="w-20 h-20 object-contain mx-auto mb-2 rounded-xl" />}
          <h2 className="font-black text-xl text-slate-800">Boom Pizza</h2>
          <p className="text-xs text-slate-400 font-bold">Admin Panel</p>
        </div>
        {[
          { id: 'DASHBOARD', icon: '📊', label: 'سەرەتا' },
          { id: 'ORDERS', icon: '📦', label: 'داواکارییەکان' },
          { id: 'PRODUCTS', icon: '🍔', label: 'خواردنەکان' },
          { id: 'CATEGORIES', icon: '📁', label: 'بەشەکان' },
          { id: 'SETTINGS', icon: '⚙️', label: 'ڕێکخستن' }
        ].map(tab => (
          <button 
            key={tab.id} 
            onClick={() => setActiveTab(tab.id as any)} 
            className={`px-6 py-4 rounded-3xl font-black whitespace-nowrap transition-all flex items-center gap-3 ${activeTab === tab.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-100' : 'text-gray-500 hover:bg-gray-50'}`}
          >
            <span>{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </nav>

      <div className="flex-grow p-4 lg:p-12 space-y-8 max-w-5xl mx-auto w-full">
        {activeTab === 'DASHBOARD' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی خواردنەکان</div>
              <div className="text-5xl font-black text-slate-800">{stats.totalProducts}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی داواکارییەکان</div>
              <div className="text-5xl font-black text-green-600">{stats.totalOrders}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی فرۆش</div>
              <div className="text-3xl font-black text-orange-600">{stats.totalRevenue.toLocaleString()} د.ع</div>
            </div>
          </div>
        )}

        {activeTab === 'PRODUCTS' && (
          <div className="space-y-8">
            <div className={`bg-white p-8 rounded-[40px] shadow-sm border-2 transition-colors ${editingProductId ? 'border-orange-500' : 'border-gray-100'}`}>
              <h3 className="font-black text-xl mb-6 text-slate-800">
                {editingProductId ? 'دەستکاری کردنی خواردن' : 'زیادکردنی بەرھەمی نوێ'}
              </h3>
              <form onSubmit={async (e) => {
                e.preventDefault();
                if (!productForm.img) {
                  Swal.fire({ icon: 'warning', title: 'وێنە نییە', text: 'تکایە سەرەتا وێنەیەەک بار بکە.' });
                  return;
                }
                setIsLoading(true);
                try {
                  const pData: any = { 
                    name: productForm.name, 
                    price: parseInt(productForm.price), 
                    img: productForm.img, 
                    category: productForm.category 
                  };

                  if (isPizzaCategory) {
                    if (productForm.priceM) pData.priceM = parseInt(productForm.priceM);
                    if (productForm.priceL) pData.priceL = parseInt(productForm.priceL);
                  }

                  if (editingProductId) {
                    await updateDoc(doc(db, "menu", editingProductId), pData);
                    setEditingProductId(null);
                    Swal.fire({ icon: 'success', title: 'نوێکرایەوە', text: 'بەرھەمەکە نوێکرایەوە', timer: 1500, showConfirmButton: false });
                  } else {
                    await addDoc(collection(db, "menu"), pData);
                    Swal.fire({ icon: 'success', title: 'سەرکەوتوو', text: 'بەرھەمەکە زیادکرا', timer: 1500, showConfirmButton: false });
                  }
                  setProductForm({ ...productForm, name: '', price: '', priceM: '', priceL: '', img: '' });
                } catch (err) { 
                  Swal.fire({ icon: 'error', title: 'هەڵە', text: 'کێشەیەک ڕوویدا' });
                } finally { 
                  setIsLoading(false); 
                }
              }} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 mr-2">ناوی خواردن</label>
                    <input className="input-admin w-full" placeholder="بۆ نموونە: پیتزای گۆشت" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} required />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 mr-2">بەش</label>
                    <select className="input-admin w-full appearance-none" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value})} required>
                      <option value="" disabled>بەشێک هەڵبژێرە</option>
                      {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                </div>

                {isPizzaCategory ? (
                  <div className="grid grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 mr-2">نرخ (S)</label>
                      <input className="input-admin w-full" type="number" placeholder="5000" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 mr-2">نرخ (M)</label>
                      <input className="input-admin w-full" type="number" placeholder="8000" value={productForm.priceM} onChange={e => setProductForm({...productForm, priceM: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-400 mr-2">نرخ (L)</label>
                      <input className="input-admin w-full" type="number" placeholder="12000" value={productForm.priceL} onChange={e => setProductForm({...productForm, priceL: e.target.value})} />
                    </div>
                  </div>
                ) : (
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 mr-2">نرخ (IQD)</label>
                    <input className="input-admin w-full" type="number" placeholder="٥٠٠٠" value={productForm.price} onChange={e => setProductForm({...productForm, price: e.target.value})} required />
                  </div>
                )}

                <div className="relative h-56 bg-slate-50 rounded-[32px] border-2 border-dashed border-slate-200 flex flex-col items-center justify-center overflow-hidden transition-all hover:border-orange-200">
                  {productForm.img ? (
                    <img src={productForm.img} className="h-full w-full object-cover" alt="Preview" />
                  ) : (
                    <div className="flex flex-col items-center text-slate-400 text-center px-4">
                      <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center shadow-sm mb-3 text-orange-500">📸</div>
                      <span className="font-black text-sm">بارکردنی وێنە</span>
                    </div>
                  )}
                  <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      setIsUploading(true);
                      const url = await uploadToImgBB(file);
                      if (url) setProductForm(p => ({...p, img: url}));
                      setIsUploading(false);
                    }
                  }} />
                  {isUploading && <div className="absolute inset-0 bg-white/80 flex items-center justify-center backdrop-blur-sm font-black text-orange-600">خەریکی بارکردنە...</div>}
                </div>
                <div className="flex gap-4">
                  <button disabled={isUploading || isLoading} className="flex-grow bg-orange-600 text-white py-5 rounded-[24px] font-black active:scale-95 shadow-xl shadow-orange-100">
                    {isLoading ? 'پاشکەوت دەکرێت...' : editingProductId ? 'نوێکردنەوەی بەرھەم' : 'پاشکەوتکردنی بەرھەم'}
                  </button>
                  {editingProductId && (
                    <button type="button" onClick={cancelEditProduct} className="bg-gray-100 text-gray-500 px-8 rounded-[24px] font-black hover:bg-gray-200 transition-colors">هەڵوەشاندنەوە</button>
                  )}
                </div>
              </form>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <h4 className="font-black text-slate-800 col-span-full mt-4">لیستی خواردنەکان ({products.length})</h4>
              {products.map(p => (
