  /**
   * Implements API Key Rotation for ImgBB
   * Tries available keys until one succeeds or all fail.
   */
  const uploadToImgBB = async (file: File): Promise<string | null> => {
    // Start from the last successful key index or 0
    let startIndex = parseInt(localStorage.getItem('working_imgbb_index') || '0');

    for (let i = 0; i < IMGBB_KEYS.length; i++) {
      const currentIndex = (startIndex + i) % IMGBB_KEYS.length;
      const currentKey = IMGBB_KEYS[currentIndex];

      const formData = new FormData();
      formData.append('image', file);

      try {
        const response = await fetch(`https://api.imgbb.com/1/upload?key=${currentKey}`, { 
          method: 'POST', 
          body: formData 
        });
        const result = await response.json();

        if (result.success) {
          // Success! Save this index as the working one
          localStorage.setItem('working_imgbb_index', currentIndex.toString());
          return result.data.display_url || result.data.url;
        } else {
          // Key at currentIndex failed (likely limit reached), move to next
          console.warn(`ImgBB Key Rotation: Key ${currentIndex + 1} failed.`, result.error?.message);
        }
      } catch (error) {
        console.error(`ImgBB Key Rotation: Network error with Key ${currentIndex + 1}`);
      }
    }

    // If loop finishes without success
    Swal.fire({ 
      icon: 'error', 
      title: 'هەڵە لە بارکردن', 
      text: 'هەموو سێرڤەرەکانی وێنە پڕ بوون، تکایە پەیوەندی بە بەڕێوەبەرەوە بکە.' 
