import React, { useState, useMemo, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  updateDoc,
  onSnapshot
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

declare var Swal: any;

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
  mainBanner?: string;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange,
  mainBanner
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLogoUploading, setIsLogoUploading] = useState(false);
  const [isBannerUploading, setIsBannerUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // ImgBB Multi-Key Management states
  const [imgbbKeys, setImgbbKeys] = useState<string[]>(['', '', '', '', '']);
  const [activeIndex, setActiveIndex] = useState<number>(0);

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, priceM: string, priceL: string, img: string, category: string}>({ 
    name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' 
  });
  const [editingProductId, setEditingProductId] = useState<string | null>(null);

  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);

  useEffect(() => {
    if (!productForm.category && categories.length > 0) {
      setProductForm(prev => ({ ...prev, category: categories[0].id }));
    }
  }, [categories, productForm.category]);

  // Fetch ImgBB Keys and Active Index from Firestore on mount
  useEffect(() => {
    if (isLocalAdmin) {
      const unsub = onSnapshot(doc(db, "settings", "api_keys"), (d) => {
        if (d.exists()) {
          const data = d.data();
          const keys = data.keys || ['', '', '', '', ''];
          const index = typeof data.activeIndex === 'number' ? data.activeIndex : 0;
          setImgbbKeys(keys);
          setActiveIndex(index);
        }
      });
      return () => unsub();
    }
  }, [isLocalAdmin]);

  const stats = useMemo(() => {
    return { 
      totalProducts: products.length, 
      totalOrders: orderLogs.length, 
      totalRevenue: orderLogs.reduce((acc, curr) => acc + curr.total, 0)
    };
  }, [products, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      Swal.fire({
        icon: 'error',
        title: 'هەڵە',
        text: 'وشەی نهێنی هەڵەیە!',
        confirmButtonText: 'باشە'
      });
    }
  };

  /**
   * Uploads image using the designated active key from the multi-key set.
   */
  const uploadToImgBB = async (file: File): Promise<string | null> => {
    const activeKey = imgbbKeys[activeIndex];

    if (!activeKey || activeKey.trim() === '') {
      Swal.fire({ 
        icon: 'error', 
        title: 'کلیلی API نییە', 
        text: 'تکایە سەرەتا کلیلی ImgBB کارا لە بەشی ڕێکخستن بنووسە و پاشەکەوتی بکە.' 
      });
      return null;
    }

    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${activeKey}`, { 
        method: 'POST', 
        body: formData 
      });
      const result = await response.json();

      if (result.success) {
        return result.data.display_url || result.data.url;
      } else {
        console.error("ImgBB Upload Error:", result.error?.message);
        Swal.fire({ 
          icon: 'error', 
          title: 'هەڵە لە بارکردن', 
          text: 'وەک دیارە ئەم کلیلە پڕ بووە یان کار ناکات. تکایە کلیلێکی تر لە ڕێکخستن هەڵبژێرە.' 
        });
        return null;
      }
    } catch (error) {
      console.error("Network Error during ImgBB upload:", error);
      Swal.fire({ 
        icon: 'error', 
        title: 'هەڵەی ڕاژە', 
        text: 'پەیوەندی ئینتەرنێتەکەت بپشکنە یان کلیلێکی تر تاقی بکەرەوە.' 
      });
      return null;
    }
  };

  const saveApiKeysToFirestore = async () => {
    if (!imgbbKeys[activeIndex] || imgbbKeys[activeIndex].trim() === '') {
      Swal.fire({ 
        icon: 'warning', 
        title: 'ئاگاداری', 
        text: 'تکایە کلیلێکی دروست بنووسە بۆ ئەو بژاردەیەی کە هەڵت بژاردووە وەک Active.' 
      });
      return;
    }

    try {
      setIsLoading(true);
      await setDoc(doc(db, "settings", "api_keys"), { 
        keys: imgbbKeys,
        activeIndex: activeIndex
      }, { merge: true });
      Swal.fire({ icon: 'success', title: 'سەرکەوتوو', text: 'ڕێکخستنەکانی API بە سەرکەوتوویی پاشەکەوت کران.', timer: 1500, showConfirmButton: false });
    } catch (error) {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'نەتوانرا ڕێکخستنەکان پاشەکەوت بکرێت.' });
