import React, { useState, useEffect, useRef } from 'react';
import { LuckyWheelSettings } from '../types';

declare var Swal: any;

interface LuckyWheelProps {
  settings: LuckyWheelSettings;
  onClose: () => void;
}

export const LuckyWheel: React.FC<LuckyWheelProps> = ({ settings, onClose }) => {
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotation, setRotation] = useState(0);
  const wheelRef = useRef<HTMLDivElement>(null);

  const spin = () => {
    if (isSpinning) return;

    // Probability Logic
    const totalWeight = settings.prizes.reduce((acc, p) => acc + p.weight, 0);
    let random = Math.random() * totalWeight;
    let winningIndex = 0;

    for (let i = 0; i < settings.prizes.length; i++) {
      if (random < settings.prizes[i].weight) {
        winningIndex = i;
        break;
      }
      random -= settings.prizes[i].weight;
    }

    setIsSpinning(true);

    // Calculate rotation
    // Each slice is 360 / length
    const sliceAngle = 360 / settings.prizes.length;
    // We want the winning slice to land at the top (pointer position)
    // The wheel starts at 0. Slice 0 is from 0 to sliceAngle.
    // To put index i at the top, we need to rotate by (360 - (i * sliceAngle) - (sliceAngle/2))
    const extraSpins = 5 * 360; // 5 full circles
    const targetRotation = extraSpins + (360 - (winningIndex * sliceAngle) - (sliceAngle / 2));

    setRotation(targetRotation);

    setTimeout(() => {
      setIsSpinning(false);
      const prize = settings.prizes[winningIndex];
      const isWin = !prize.text.toLowerCase().includes('luck') && !prize.text.includes('ببورە');

      if (isWin) {
        const code = `BOOM-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;
        Swal.fire({
          title: 'پیرۆزە! 🎉',
          html: `<div class="p-4"><p class="text-lg font-bold mb-2">تۆ برابوویت بە: <span class="text-orange-600">${prize.text}</span></p><p class="text-sm text-gray-500">ئەم کۆدە لە کاتی داواکردن بنووسە:</p><div class="mt-4 p-4 bg-orange-50 border-2 border-dashed border-orange-200 rounded-2xl font-black text-2xl tracking-widest text-orange-600 select-all">${code}</div></div>`,
          icon: 'success',
          confirmButtonText: 'زۆر باشە',
          confirmButtonColor: '#ea580c'
        });
      } else {
        Swal.fire({
          title: 'بەداخەوە! 😔',
          text: prize.text,
          icon: 'info',
          confirmButtonText: 'باشە',
          confirmButtonColor: '#ea580c'
        });
      }

      // Mark as spun for today
      localStorage.setItem('last_spin_date', new Date().toDateString());
      onClose();
    }, 4500);
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white rounded-[40px] w-full max-w-sm p-8 relative overflow-hidden flex flex-col items-center">
        <button onClick={onClose} className="absolute top-4 left-4 text-gray-400 hover:text-black">✕</button>

        <div className="text-center mb-8">
          <h2 className="text-2xl font-black text-gray-900">چەرخی بەخت 🎡</h2>
          <p className="text-gray-500 font-bold mt-1 text-sm">بەختت تاقی بکەرەوە و خەڵات بەرە!</p>
        </div>

        <div className="relative w-64 h-64 mb-8">
          {/* Pointer */}
          <div className="absolute -top-2 left-1/2 -translate-x-1/2 z-20">
            <div className="w-0 h-0 border-l-[15px] border-l-transparent border-r-[15px] border-r-transparent border-t-[25px] border-t-orange-600 filter drop-shadow-md"></div>
          </div>

          {/* Wheel */}
          <div 
            className="w-full h-full rounded-full border-8 border-slate-100 shadow-2xl relative transition-transform duration-[4000ms] cubic-bezier(0.15, 0, 0.15, 1)"
            style={{ 
              transform: `rotate(${rotation}deg)`,
              background: `conic-gradient(${settings.prizes.map((p, i) => `${p.color} ${i * (360/settings.prizes.length)}deg ${(i+1) * (360/settings.prizes.length)}deg`).join(', ')})` 
            }}
          >
            {settings.prizes.map((p, i) => (
              <div 
                key={i}
                className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 h-full w-full flex items-start justify-center p-2"
                style={{ transform: `rotate(${(i * (360/settings.prizes.length)) + (360/settings.prizes.length)/2}deg)` }}
              >
                <span className="text-[10px] font-black text-white text-center mt-4 w-12 drop-shadow-sm leading-tight rotate-180" style={{ writingMode: 'vertical-rl' }}>
                  {p.text}
                </span>
              </div>
            ))}
          </div>

          {/* Center Button */}
          <button 
            onClick={spin}
            disabled={isSpinning}
            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-16 h-16 bg-white rounded-full shadow-xl flex items-center justify-center font-black text-orange-600 hover:scale-105 active:scale-95 transition-all z-30 border-4 border-orange-500 disabled:opacity-50"
          >
            SPIN
          </button>
        </div>

        <div className="text-xs text-gray-400 font-bold">
          هەموو ٢٤ کاتژمێرێک یەک جار دەتوانیت بیسووڕێنیت
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog, WheelPrize, LuckyWheelSettings } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  updateDoc,
  onSnapshot
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

declare var Swal: any;

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
  mainBanner?: string;
}

const DEFAULT_WHEEL_COLORS = ['#ea580c', '#f97316', '#fb923c', '#fdba74', '#ea580c', '#f97316', '#fb923c', '#fdba74'];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange,
  mainBanner
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLogoUploading, setIsLogoUploading] = useState(false);
  const [isBannerUploading, setIsBannerUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Lucky Wheel States
  const [wheelSettings, setWheelSettings] = useState<LuckyWheelSettings>({
    isEnabled: false,
    prizes: Array(8).fill(null).map((_, i) => ({ text: '', weight: 1, color: DEFAULT_WHEEL_COLORS[i] }))
  });

  // ImgBB Multi-Key Management states
  const [imgbbKeys, setImgbbKeys] = useState<string[]>(['', '', '', '', '']);
  const [activeIndex, setActiveIndex] = useState<number>(0);

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, priceM: string, priceL: string, img: string, category: string}>({ 
    name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' 
  });
  const [editingProductId, setEditingProductId] = useState<string | null>(null);

  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);

  useEffect(() => {
    if (!productForm.category && categories.length > 0) {
      setProductForm(prev => ({ ...prev, category: categories[0].id }));
    }
  }, [categories, productForm.category]);

  // Fetch Settings from Firestore
  useEffect(() => {
    if (isLocalAdmin) {
      const unsubKeys = onSnapshot(doc(db, "settings", "api_keys"), (d) => {
        if (d.exists()) {
          const data = d.data();
          setImgbbKeys(data.keys || ['', '', '', '', '']);
          setActiveIndex(data.activeIndex || 0);
        }
      });

      const unsubWheel = onSnapshot(doc(db, "settings", "lucky_wheel"), (d) => {
        if (d.exists()) {
          setWheelSettings(d.data() as LuckyWheelSettings);
        }
      });

      return () => { unsubKeys(); unsubWheel(); };
    }
  }, [isLocalAdmin]);

  const stats = useMemo(() => {
    return { 
      totalProducts: products.length, 
      totalOrders: orderLogs.length, 
      totalRevenue: orderLogs.reduce((acc, curr) => acc + curr.total, 0)
    };
  }, [products, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      Swal.fire({
        icon: 'error',
        title: 'هەڵە',
        text: 'وشەی نهێنی هەڵەیە!',
        confirmButtonText: 'باشە'
      });
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    const activeKey = imgbbKeys[activeIndex];
    if (!activeKey) return null;
    const formData = new FormData();
    formData.append('image', file);
    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${activeKey}`, { method: 'POST', body: formData });
      const result = await response.json();
      return result.success ? (result.data.display_url || result.data.url) : null;
    } catch { return null; }
  };

  const saveWheelSettings = async () => {
    try {
      setIsLoading(true);
      await setDoc(doc(db, "settings", "lucky_wheel"), wheelSettings);
      Swal.fire({ icon: 'success', title: 'پاشەکەوت کرا', timer: 1500, showConfirmButton: false });
