    await setDoc(doc(db, "settings", "api_keys"), { keys: imgbbKeys, activeIndex }, { merge: true });
    Swal.fire({ icon: 'success', title: 'سەرکەوتوو', timer: 1500, showConfirmButton: false });
  };

