import React, { useState } from 'react';
import { CartItem } from '../types';
import { TELEGRAM_BOT_TOKEN } from '../constants';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

declare var Swal: any;

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  telegramChatId: string;
  onUpdateQuantity: (id: string, delta: number, size?: 'S' | 'M' | 'L') => void;
  onRemove: (id: string, size?: 'S' | 'M' | 'L') => void;
  onClearCart: () => void;
  locationUrl: string | null;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  telegramChatId,
  onUpdateQuantity,
  onRemove,
  onClearCart,
  locationUrl: initialLocationUrl
}) => {
  const [isSending, setIsSending] = useState(false);
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [phone, setPhone] = useState('');
  const [manualAddress, setManualAddress] = useState('');
  const [note, setNote] = useState('');
  const [promoCode, setPromoCode] = useState('');
  const [userCoords, setUserCoords] = useState<{lat: number, lng: number} | null>(null);
  const [isGettingLocation, setIsGettingLocation] = useState(false);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleGetLocation = () => {
    setIsGettingLocation(true);
    if (!navigator.geolocation) {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'براوسەرەکەت پشتگیری لۆکەیشن ناکات' });
      setIsGettingLocation(false);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        setUserCoords({ lat: position.coords.latitude, lng: position.coords.longitude });
        setIsGettingLocation(false);
      },
      () => setIsGettingLocation(false)
    );
  };

  const handleOrder = async () => {
    if (!phone || phone.length < 10) {
      Swal.fire({ icon: 'warning', title: 'زانیاری ناتەواو', text: 'تکایە ژمارەی مۆبایلەکەت بنووسە.' });
      return;
    }

    setIsSending(true);

    const now = new Date().toLocaleString('ku-IQ', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

    let text = `📦 **NEW ORDER - BOOM PIZZA**\n`;
    text += `━━━━━━━━━━━━━━━━━━━━\n\n`;

    text += `🍕 **ITEMS LIST:**\n`;
    cart.forEach((item) => {
      const sizeStr = item.selectedSize ? ` (${item.selectedSize})` : '';
      text += `• **${item.name}${sizeStr}** x ${item.quantity} — \`${(item.price * item.quantity).toLocaleString()} IQD\`\n`;
    });

    text += `\n━━━━━━━━━━━━━━━━━━━━\n`;
    text += `💰 **TOTAL AMOUNT: \`${total.toLocaleString()} IQD\`**\n`;
    if (promoCode) {
      text += `🎁 **PROMO CODE: \`${promoCode.toUpperCase()}\`**\n`;
    }
    text += `━━━━━━━━━━━━━━━━━━━━\n\n`;

    text += `👤 **CUSTOMER INFO:**\n`;
    text += `📞 Phone: \`${phone}\`\n`;
    text += `📝 Note: ${note.trim() || '_No notes_'}\n`;

    if (manualAddress.trim()) text += `🏠 Address: \`${manualAddress.trim()}\`\n`;
    if (userCoords) text += `📍 Google Maps: https://www.google.com/maps?q=${userCoords.lat},${userCoords.lng}\n`;
    text += `\n⏰ Date: ${now}`;

    try {
      await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ chat_id: telegramChatId, text: text, parse_mode: "Markdown" })
      });

      await addDoc(collection(db, "orders"), {
        items: cart.map(i => `${i.quantity}x ${i.name}${i.selectedSize ? ' ('+i.selectedSize+')' : ''}`),
        total,
        promoCode,
        customerPhone: phone,
        manualAddress,
        customerNote: note,
        timestamp: Date.now()
      });

      await Swal.fire({ icon: 'success', title: 'داواکارییەکەت گەیشت!', confirmButtonText: 'باشە', confirmButtonColor: '#ea580c' });
      onClearCart();
      setIsCheckingOut(false);
      onClose();
    } catch {
      Swal.fire({ icon: 'error', title: 'هەڵەیەک ڕوویدا' });
    } finally {
      setIsSending(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/60 backdrop-blur-sm">
      <div className="absolute inset-0" onClick={() => { setIsCheckingOut(false); onClose(); }} />
      <div className="bg-white rounded-t-[40px] h-[85vh] w-full flex flex-col relative animate-slide-up overflow-hidden text-black">
        <div className="p-8 border-b flex justify-between items-center sticky top-0 bg-white z-10">
          <div className="flex items-center gap-3">
            {isCheckingOut && <button onClick={() => setIsCheckingOut(false)} className="p-2 bg-gray-100 rounded-xl">←</button>}
            <h2 className="text-2xl font-black">{isCheckingOut ? 'ناونیشان و گەیاندن' : 'سەبەتەکەم'}</h2>
          </div>
          <button onClick={() => { setIsCheckingOut(false); onClose(); }} className="p-3 bg-gray-100 rounded-full">✕</button>
        </div>

        <div className="flex-grow overflow-y-auto p-6">
          {!isCheckingOut ? (
            <div className="space-y-4">
              {cart.map((item, idx) => (
                <div key={idx} className="bg-gray-50 p-5 rounded-[32px] flex items-center gap-4 border border-gray-100">
                  <img src={item.img} className="w-20 h-20 rounded-3xl object-cover" />
                  <div className="flex-grow">
                    <h3 className="font-black text-slate-800">{item.name} {item.selectedSize && `(${item.selectedSize})`}</h3>
                    <div className="text-orange-600 font-bold">{(item.price * item.quantity).toLocaleString()} IQD</div>
                    <div className="flex items-center gap-4 mt-2">
                      <button onClick={() => onUpdateQuantity(item.id, -1, item.selectedSize)} className="w-10 h-10 bg-white rounded-xl border border-gray-200">-</button>
                      <span className="font-black">{item.quantity}</span>
                      <button onClick={() => onUpdateQuantity(item.id, 1, item.selectedSize)} className="w-10 h-10 bg-white rounded-xl border border-gray-200">+</button>
                    </div>
                  </div>
                  <button onClick={() => onRemove(item.id, item.selectedSize)} className="text-red-400">🗑️</button>
                </div>
              ))}
            </div>
          ) : (
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-500 mr-2">ژمارەی مۆبایل</label>
                <input className="w-full p-5 bg-slate-50 rounded-[24px] border border-slate-200 outline-none font-black" value={phone} onChange={e => setPhone(e.target.value)} placeholder="0750XXXXXXX" />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-black text-orange-600 mr-2">کۆدی دیاری / داشکاندن (ئارەزوومەندانە)</label>
                <input 
                  className="w-full p-5 bg-orange-50/50 rounded-[24px] border border-orange-100 outline-none font-black text-orange-600 placeholder:text-orange-200 uppercase tracking-widest" 
                  value={promoCode} 
                  onChange={e => setPromoCode(e.target.value)} 
                  placeholder="BOOM-XXXX" 
                />
              </div>

              <div className="p-6 bg-slate-50 rounded-[32px] space-y-4">
                <button onClick={handleGetLocation} className={`w-full py-5 rounded-[24px] font-black border-2 ${userCoords ? 'bg-green-50 border-green-500 text-green-600' : 'bg-white border-blue-500 text-blue-600'}`}>
                  {userCoords ? 'لۆکەیشن وەرگیرا ✓' : 'ناردنی لۆکەیشن'}
                </button>
                <textarea className="w-full p-5 bg-white rounded-[24px] border border-slate-200 outline-none font-black min-h-[100px]" value={manualAddress} onChange={e => setManualAddress(e.target.value)} placeholder="ناونیشانی دەستی بنووسە..." />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-black text-slate-500 mr-2">تێبینی</label>
                <input className="w-full p-5 bg-slate-50 rounded-[24px] border border-slate-200 outline-none font-black" value={note} onChange={e => setNote(e.target.value)} placeholder="بێ بیبەر بێت..." />
              </div>
            </div>
          )}
        </div>

        <div className="p-8 border-t bg-white space-y-4 shadow-xl">
          <div className="flex justify-between items-center">
            <span className="text-gray-400 font-bold">کۆی گشتی</span>
            <span className="text-3xl font-black text-orange-600">{total.toLocaleString()} د.ع</span>
          </div>
          <button 
            disabled={cart.length === 0 || isSending} 
            onClick={() => isCheckingOut ? handleOrder() : setIsCheckingOut(true)} 
            className="w-full bg-orange-600 text-white py-6 rounded-[30px] font-black text-xl shadow-xl shadow-orange-100 active:scale-95 transition-all"
          >
            {isSending ? 'خەریکی ناردنە...' : isCheckingOut ? 'جێگیرکردنی داواکاری' : 'بەردەوامبوون'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { CategoryBar } from './components/CategoryBar';
import { InAppBrowserOverlay } from './components/InAppBrowserOverlay';
import { LuckyWheel } from './components/LuckyWheel';
import { Product, CartItem, ViewState, Category, OrderLog, LuckyWheelSettings } from './types';
import { DEFAULT_CATEGORIES, ADD_TO_CART_SOUND_URL } from './constants';
import { db } from './firebase';
import { collection, onSnapshot, query, orderBy, doc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('');
  const [telegramChatId, setTelegramChatId] = useState('');
  const [businessLogo, setBusinessLogo] = useState('');
  const [mainBanner, setMainBanner] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);
  const [isLocalAdmin, setIsLocalAdmin] = useState(() => sessionStorage.getItem('isAdminAuthenticated') === 'true');
  const [locationUrl, setLocationUrl] = useState<string | null>(null);
  const [isInAppBrowser, setIsInAppBrowser] = useState(false);

  // Wheel States
  const [wheelSettings, setWheelSettings] = useState<LuckyWheelSettings | null>(null);
  const [showWheel, setShowWheel] = useState(false);

  useEffect(() => {
    const ua = navigator.userAgent || navigator.vendor;
    if (ua.indexOf("FBAN") > -1 || ua.indexOf("FBAV") > -1 || ua.indexOf("Messenger") > -1) setIsInAppBrowser(true);

    const unsubProducts = onSnapshot(query(collection(db, "menu"), orderBy("name")), (snap) => {
      const p: Product[] = [];
      snap.forEach(d => p.push({ id: d.id, ...d.data() } as Product));
      setProducts(p);
    });

    const unsubCategories = onSnapshot(query(collection(db, "categories"), orderBy("name")), (snap) => {
      const c: Category[] = [];
      snap.forEach(d => c.push({ id: d.id, ...d.data() } as Category));
      setCategories(c.length > 0 ? c : DEFAULT_CATEGORIES);
    });

    const unsubSettings = onSnapshot(doc(db, "settings", "general"), (d) => {
      if (d.exists()) setTelegramChatId(d.data().telegramChatId || '');
    });

    const unsubTheme = onSnapshot(doc(db, "settings", "theme"), (d) => {
      if (d.exists()) setBusinessLogo(d.data().logoUrl || '');
    });

    const unsubBanner = onSnapshot(doc(db, "settings", "banner"), (d) => {
      if (d.exists()) setMainBanner(d.data().url || '');
    });

    const unsubWheel = onSnapshot(doc(db, "settings", "lucky_wheel"), (d) => {
      if (d.exists()) {
        const settings = d.data() as LuckyWheelSettings;
        setWheelSettings(settings);

        // Logic to show wheel
        const lastSpin = localStorage.getItem('last_spin_date');
        const today = new Date().toDateString();

        if (settings.isEnabled && lastSpin !== today) {
          setTimeout(() => setShowWheel(true), 3000);
        }
      }
    });

    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("timestamp", "desc")), (snap) => {
      const o: OrderLog[] = [];
      snap.forEach(d => o.push({ id: d.id, ...d.data() } as OrderLog));
      setOrderLogs(o);
    });

    return () => { unsubProducts(); unsubCategories(); unsubSettings(); unsubTheme(); unsubBanner(); unsubWheel(); unsubOrders(); };
  }, []);

  useEffect(() => {
    if (categories.length > 0 && !selectedCategory) setSelectedCategory(categories[0].id);
  }, [categories, selectedCategory]);

  const filteredProducts = useMemo(() => {
    if (!selectedCategory) return [];
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    new Audio(ADD_TO_CART_SOUND_URL).play().catch(() => {});
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id && i.selectedSize === size);
      let finalPrice = product.price;
      if (size === 'M' && product.priceM) finalPrice = product.priceM;
      if (size === 'L' && product.priceL) finalPrice = product.priceL;

      if (existing) {
        return prev.map(i => (i.id === product.id && i.selectedSize === size) ? { ...i, quantity: i.quantity + 1, price: finalPrice } : i);
      }
      return [...prev, { ...product, price: finalPrice, quantity: 1, selectedSize: size }];
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-black overflow-x-hidden">
      {isInAppBrowser && <InAppBrowserOverlay businessLogo={businessLogo} />}

      {showWheel && wheelSettings && (
        <LuckyWheel settings={wheelSettings} onClose={() => setShowWheel(false)} />
      )}

      <Header currentView={view} onToggleAdmin={() => setView(v => v === 'MENU' ? 'ADMIN' : 'MENU')} businessLogo={businessLogo} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <div className="px-4 pt-6">
              <div className="max-w-4xl mx-auto h-48 sm:h-64 rounded-[40px] overflow-hidden shadow-2xl shadow-orange-100 bg-gray-200">
                {mainBanner ? <img src={mainBanner} alt="Banner" className="w-full h-full object-cover" /> : <div className="w-full h-full bg-orange-500" />}
              </div>
            </div>
            <CategoryBar categories={categories} selectedCategoryId={selectedCategory} onSelectCategory={setSelectedCategory} />
            <div className="max-w-4xl mx-auto px-4 py-8 pb-32">
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                {filteredProducts.map(p => (
                  <ProductCard 
                    key={p.id} 
                    product={p} 
                    onAddToCart={(prod, size) => addToCart(prod, size)}
                    isPizza={categories.find(c => c.id === p.category)?.name.includes('پیتزا')}
                  />
                ))}
              </div>
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} categories={categories} isSoundEnabled={true} 
            telegramChatId={telegramChatId} businessLogo={businessLogo} 
            orderLogs={orderLogs} isLocalAdmin={isLocalAdmin} onAdminAuthChange={setIsLocalAdmin} 
            mainBanner={mainBanner}
          />
        )}
      </main>

      {view === 'MENU' && cart.length > 0 && <BottomNav cart={cart} onViewCart={() => setIsCartOpen(true)} />}

      <CartModal 
        isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} 
        telegramChatId={telegramChatId} locationUrl={locationUrl}
        onUpdateQuantity={(id, delta, size) => {
          setCart(c => c.map(i => (i.id === id && i.selectedSize === size) ? {...i, quantity: Math.max(1, i.quantity + delta)} : i));
        }}
        onRemove={(id, size) => setCart(c => c.filter(i => !(i.id === id && i.selectedSize === size)))}
        onClearCart={() => setCart([])}
      />
    </div>
  );
};

