export type ViewState = 'MENU' | 'ADMIN';
export type AdminSubView = 'DASHBOARD' | 'PRODUCTS' | 'CATEGORIES' | 'ORDERS' | 'SETTINGS';

import React, { useState, useRef } from 'react';
import { LuckyWheelSettings } from '../types';

declare var Swal: any;

interface LuckyWheelProps {
  settings: LuckyWheelSettings;
  onClose: () => void;
}

export const LuckyWheel: React.FC<LuckyWheelProps> = ({ settings, onClose }) => {
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotation, setRotation] = useState(0);

  const spin = () => {
    if (isSpinning) return;

    // Weight-based random selection
    const totalWeight = settings.prizes.reduce((acc, p) => acc + p.weight, 0);
    let random = Math.random() * totalWeight;
    let winningIndex = 0;

    for (let i = 0; i < settings.prizes.length; i++) {
      if (random < settings.prizes[i].weight) {
        winningIndex = i;
        break;
      }
      random -= settings.prizes[i].weight;
    }

    setIsSpinning(true);

    const sliceAngle = 360 / settings.prizes.length;
    const extraSpins = 8 * 360; // 8 full circles
    // Calculate rotation to put winning index at the top
    const targetRotation = extraSpins + (360 - (winningIndex * sliceAngle) - (sliceAngle / 2));

    setRotation(targetRotation);

    setTimeout(() => {
      setIsSpinning(false);
      const prize = settings.prizes[winningIndex];
      const isWin = !prize.text.toLowerCase().includes('luck') && !prize.text.includes('ببورە');

      if (isWin) {
        const code = `BOOM-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;
        Swal.fire({
          title: 'پیرۆزە! 🎉',
          html: `
            <div class="p-2">
              <p class="text-lg font-bold mb-1">تۆ برابوویت بە: <span class="text-orange-600">${prize.text}</span></p>
              <p class="text-sm text-gray-500 mb-4">ئەم کۆدە لە کاتی داواکردن بنووسە:</p>
              <div class="p-4 bg-orange-50 border-2 border-dashed border-orange-200 rounded-2xl font-black text-2xl tracking-widest text-orange-600 select-all">
                ${code}
              </div>
            </div>
          `,
          icon: 'success',
          confirmButtonText: 'زۆر باشە',
          confirmButtonColor: '#ea580c'
        });
      } else {
        Swal.fire({
          title: 'بەداخەوە! 😔',
          text: prize.text,
          icon: 'info',
          confirmButtonText: 'باشە',
          confirmButtonColor: '#ea580c'
        });
      }

      localStorage.setItem('last_spin_date', new Date().toDateString());
      onClose();
    }, 4500);
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white rounded-[40px] w-full max-w-sm p-8 relative overflow-hidden flex flex-col items-center">
        <button onClick={onClose} className="absolute top-4 left-4 text-gray-400 hover:text-black p-2">✕</button>

        <div className="text-center mb-8">
          <h2 className="text-2xl font-black text-gray-900">چەرخی بەخت 🎡</h2>
          <p className="text-gray-400 font-bold mt-1 text-sm">بەختت تاقی بکەرەوە و خەڵات بەرە!</p>
        </div>

        <div className="relative w-64 h-64 mb-8">
          {/* Pointer */}
          <div className="absolute -top-3 left-1/2 -translate-x-1/2 z-20">
            <div className="w-0 h-0 border-l-[15px] border-l-transparent border-r-[15px] border-r-transparent border-t-[30px] border-t-orange-600 filter drop-shadow-md"></div>
          </div>

          {/* Wheel Canvas Area */}
          <div 
            className="w-full h-full rounded-full border-8 border-slate-100 shadow-2xl relative transition-transform duration-[4500ms] cubic-bezier(0.15, 0, 0.15, 1) overflow-hidden"
            style={{ 
              transform: `rotate(${rotation}deg)`,
              background: `conic-gradient(${settings.prizes.map((p, i) => `${p.color} ${i * (360/settings.prizes.length)}deg ${(i+1) * (360/settings.prizes.length)}deg`).join(', ')})` 
            }}
          >
            {settings.prizes.map((p, i) => (
              <div 
                key={i}
                className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 h-full w-full flex items-start justify-center p-1"
                style={{ transform: `rotate(${(i * (360/settings.prizes.length)) + (360/settings.prizes.length)/2}deg)` }}
              >
                <span className="text-[9px] font-black text-white text-center mt-6 w-14 drop-shadow-md leading-tight" style={{ writingMode: 'vertical-rl', transform: 'rotate(180deg)' }}>
                  {p.text}
                </span>
              </div>
            ))}
          </div>

          {/* Center Button */}
          <button 
            onClick={spin}
            disabled={isSpinning}
            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-16 h-16 bg-white rounded-full shadow-xl flex items-center justify-center font-black text-orange-600 hover:scale-105 active:scale-95 transition-all z-30 border-4 border-orange-500 disabled:opacity-50"
          >
            SPIN
          </button>
        </div>

        <div className="text-[10px] text-gray-400 font-black text-center">
          هەموو ڕۆژێک یەک جار دەتوانیت بەختت تاقی بکەیتەوە
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog, LuckyWheelSettings } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  updateDoc,
  onSnapshot
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

declare var Swal: any;

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
  mainBanner?: string;
}

const DEFAULT_WHEEL_COLORS = ['#ea580c', '#f97316', '#fb923c', '#fdba74', '#ea580c', '#f97316', '#fb923c', '#fdba74'];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  isSoundEnabled,
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange,
  mainBanner
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<AdminSubView>('DASHBOARD');
  const [isUploading, setIsUploading] = useState(false);
  const [isLogoUploading, setIsLogoUploading] = useState(false);
  const [isBannerUploading, setIsBannerUploading] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Wheel State
  const [wheelSettings, setWheelSettings] = useState<LuckyWheelSettings>({
    isEnabled: false,
    prizes: Array(8).fill(null).map((_, i) => ({ text: '', weight: 1, color: DEFAULT_WHEEL_COLORS[i] }))
  });

  // ImgBB keys
  const [imgbbKeys, setImgbbKeys] = useState<string[]>(['', '', '', '', '']);
  const [activeIndex, setActiveIndex] = useState<number>(0);

  const [productForm, setProductForm] = useState<{id?: string, name: string, price: string, priceM: string, priceL: string, img: string, category: string}>({ 
    name: '', price: '', priceM: '', priceL: '', img: '', category: categories[0]?.id || '' 
  });
  const [editingProductId, setEditingProductId] = useState<string | null>(null);

  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);

  useEffect(() => {
    if (isLocalAdmin) {
      const unsubKeys = onSnapshot(doc(db, "settings", "api_keys"), (d) => {
        if (d.exists()) {
          const data = d.data();
          setImgbbKeys(data.keys || ['', '', '', '', '']);
          setActiveIndex(data.activeIndex || 0);
        }
      });

      const unsubWheel = onSnapshot(doc(db, "settings", "lucky_wheel"), (d) => {
        if (d.exists()) {
          setWheelSettings(d.data() as LuckyWheelSettings);
        }
      });

      return () => { unsubKeys(); unsubWheel(); };
    }
  }, [isLocalAdmin]);

  const stats = useMemo(() => ({
    totalProducts: products.length, 
    totalOrders: orderLogs.length, 
    totalRevenue: orderLogs.reduce((acc, curr) => acc + curr.total, 0)
  }), [products, orderLogs]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'وشەی نهێنی هەڵەیە!' });
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    const activeKey = imgbbKeys[activeIndex];
    if (!activeKey) return null;
    const formData = new FormData();
    formData.append('image', file);
    try {
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${activeKey}`, { method: 'POST', body: formData });
      const result = await response.json();
      return result.success ? (result.data.display_url || result.data.url) : null;
    } catch { return null; }
  };

  const saveWheelSettings = async () => {
    try {
      setIsLoading(true);
      await setDoc(doc(db, "settings", "lucky_wheel"), wheelSettings);
      Swal.fire({ icon: 'success', title: 'پاشەکەوت کرا', timer: 1500, showConfirmButton: false });
    } catch {
      Swal.fire({ icon: 'error', title: 'کێشەیەک لە پاشەکەوتکردن هەبوو' });
    } finally {
      setIsLoading(false);
    }
  };

  const saveApiKeysToFirestore = async () => {
    await setDoc(doc(db, "settings", "api_keys"), { keys: imgbbKeys, activeIndex }, { merge: true });
    Swal.fire({ icon: 'success', title: 'سەرکەوتوو', timer: 1500, showConfirmButton: false });
  };

  const updateGeneralSetting = async (field: string, value: any) => {
    await setDoc(doc(db, "settings", "general"), { [field]: value }, { merge: true });
  };

  const handleDeleteProduct = async (id: string, name: string) => {
    if ((await Swal.fire({ title: 'دڵنیایت؟', text: `سڕینەوەی ${name}`, icon: 'warning', showCancelButton: true })).isConfirmed) {
      await deleteDoc(doc(db, "menu", id));
    }
  };

  const handleDeleteCategory = async (id: string, name: string) => {
    if ((await Swal.fire({ 
      title: 'سڕینەوەی بەش؟', 
      text: `ئایا دڵنیایت لە سڕینەوەی بەشی (${name})؟`, 
      icon: 'warning', 
      showCancelButton: true,
      confirmButtonText: 'بەڵێ، بسڕەوە',
      cancelButtonText: 'نەخێر'
    })).isConfirmed) {
      try {
        await deleteDoc(doc(db, "categories", id));
        Swal.fire({ icon: 'success', title: 'سڕایەوە', timer: 1000, showConfirmButton: false });
      } catch {
        Swal.fire({ icon: 'error', title: 'هەڵەیەک ڕوویدا' });
      }
    }
  };

  if (!isLocalAdmin) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center p-6">
        <form onSubmit={handleLogin} className="bg-white p-8 rounded-[40px] shadow-xl w-full max-w-md border border-gray-100">
          <h2 className="text-2xl font-black text-center mb-6 text-slate-800">بەشی بەڕێوەبەر</h2>
          <input 
            type="password" 
            placeholder="وشەی نهێنی" 
            className="w-full p-5 bg-gray-50 rounded-3xl border border-gray-200 mb-4 text-center text-2xl tracking-widest outline-none focus:border-orange-500 transition-all" 
            value={passwordInput} 
            onChange={e => setPasswordInput(e.target.value)} 
          />
          <button className="w-full bg-orange-600 text-white py-5 rounded-3xl font-black text-lg active:scale-95 shadow-lg shadow-orange-100">چوونەژوورەوە</button>
        </form>
      </div>
    );
  }

  return (
    <div className="flex flex-col lg:flex-row min-h-screen bg-slate-50">
      <nav className="w-full lg:w-64 bg-white border-l border-gray-100 p-4 sticky top-0 h-auto lg:h-screen flex lg:flex-col gap-2 overflow-x-auto no-scrollbar z-30">
        <div className="hidden lg:block p-4 mb-4 text-center">
          {businessLogo && <img src={businessLogo} className="w-20 h-20 object-contain mx-auto mb-2 rounded-xl" />}
          <h2 className="font-black text-xl text-slate-800">Admin Panel</h2>
        </div>
        {[
          { id: 'DASHBOARD', icon: '📊', label: 'سەرەتا' },
          { id: 'ORDERS', icon: '📦', label: 'داواکارییەکان' },
          { id: 'PRODUCTS', icon: '🍔', label: 'خواردنەکان' },
          { id: 'CATEGORIES', icon: '📁', label: 'بەشەکان' },
          { id: 'SETTINGS', icon: '⚙️', label: 'ڕێکخستن' }
        ].map(tab => (
          <button 
            key={tab.id} 
            onClick={() => setActiveTab(tab.id as any)} 
            className={`px-6 py-4 rounded-3xl font-black whitespace-nowrap transition-all flex items-center gap-3 ${activeTab === tab.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-100' : 'text-gray-500 hover:bg-gray-50'}`}
          >
            <span>{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </nav>

      <div className="flex-grow p-4 lg:p-12 space-y-8 max-w-5xl mx-auto w-full">
        {activeTab === 'DASHBOARD' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی خواردنەکان</div>
              <div className="text-5xl font-black text-slate-800">{stats.totalProducts}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی داواکارییەکان</div>
              <div className="text-5xl font-black text-green-600">{stats.totalOrders}</div>
            </div>
            <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm text-center">
              <div className="text-gray-400 text-sm font-black mb-1">کۆی فرۆش</div>
              <div className="text-3xl font-black text-orange-600">{stats.totalRevenue.toLocaleString()} د.ع</div>
            </div>
          </div>
        )}

        {activeTab === 'CATEGORIES' && (
          <div className="space-y-8">
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100">
               <h3 className="font-black text-xl mb-6 text-slate-800">بەڕێوەبردنی بەشەکان</h3>
               <form onSubmit={async (e) => {
                 e.preventDefault();
                 setIsLoading(true);
                 try {
                   const data = { name: categoryForm.name, imageUrl: categoryForm.imageUrl };
                   if (editingCategoryId) await updateDoc(doc(db, "categories", editingCategoryId), data);
                   else await addDoc(collection(db, "categories"), data);
                   setCategoryForm({ name: '', imageUrl: '' });
                   setEditingCategoryId(null);
                 } finally { setIsLoading(false); }
               }} className="space-y-4">
                 <input className="input-admin w-full" placeholder="ناوی بەش" value={categoryForm.name} onChange={e => setCategoryForm({...categoryForm, name: e.target.value})} required />
                 <div className="flex gap-4">
                   <input className="input-admin flex-grow" placeholder="لینکی وێنە" value={categoryForm.imageUrl} onChange={e => setCategoryForm({...categoryForm, imageUrl: e.target.value})} required />
                   <button type="button" className="bg-slate-100 px-6 rounded-2xl font-black text-xs" onClick={async () => {
                     const input = document.createElement('input');
                     input.type = 'file';
                     input.onchange = async (e: any) => {
                       const url = await uploadToImgBB(e.target.files[0]);
                       if (url) setCategoryForm(prev => ({...prev, imageUrl: url}));
                     };
                     input.click();
                   }}>بارکردن</button>
                 </div>
                 <button className="w-full bg-orange-600 text-white py-4 rounded-2xl font-black">{editingCategoryId ? 'نوێکردنەوە' : 'زیادکردن'}</button>
               </form>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {categories.map(c => (
                <div key={c.id} className="bg-white p-4 rounded-[32px] border border-gray-100 flex items-center justify-between shadow-sm">
                  <div className="flex items-center gap-4">
                    <img src={c.imageUrl} className="w-14 h-14 rounded-2xl object-cover" />
                    <div className="font-black text-slate-800">{c.name}</div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => { setEditingCategoryId(c.id); setCategoryForm({ name: c.name, imageUrl: c.imageUrl }); }} className="w-10 h-10 flex items-center justify-center text-blue-400">✏️</button>
                    <button onClick={() => handleDeleteCategory(c.id, c.name)} className="w-10 h-10 flex items-center justify-center text-red-500 bg-red-50 rounded-xl">🗑️</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'SETTINGS' && (
          <div className="space-y-8">
            {/* Lucky Wheel Settings */}
            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 space-y-6">
              <div className="flex items-center justify-between">
                <h3 className="font-black text-xl text-slate-800 flex items-center gap-2">
                  <span>🎡</span> چەرخی بەخت (Lucky Wheel)
                </h3>
                <button 
                  onClick={() => setWheelSettings(p => ({...p, isEnabled: !p.isEnabled}))}
                  className={`w-14 h-8 rounded-full transition-all relative ${wheelSettings.isEnabled ? 'bg-green-500' : 'bg-gray-200'}`}
                >
                  <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${wheelSettings.isEnabled ? 'left-7' : 'left-1'}`}></div>
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {wheelSettings.prizes.map((p, idx) => (
                  <div key={idx} className="p-4 bg-slate-50 rounded-[24px] border border-slate-100 space-y-2">
                    <div className="flex justify-between items-center text-[10px] font-black text-gray-400">
                      <span>Prize {idx + 1}</span>
                      <span>Chance: {p.weight}x</span>
                    </div>
                    <input 
                      className="w-full p-3 bg-white rounded-xl border border-slate-200 text-sm font-black" 
                      placeholder="ناوی خەڵات..." 
                      value={p.text}
                      onChange={e => {
                        const newPrizes = [...wheelSettings.prizes];
                        newPrizes[idx].text = e.target.value;
                        setWheelSettings(prev => ({...prev, prizes: newPrizes}));
                      }}
                    />
                    <input 
                      type="range" min="0" max="10" 
                      className="w-full accent-orange-600"
                      value={p.weight}
                      onChange={e => {
                        const newPrizes = [...wheelSettings.prizes];
                        newPrizes[idx].weight = parseInt(e.target.value);
                        setWheelSettings(prev => ({...prev, prizes: newPrizes}));
                      }}
                    />
                  </div>
                ))}
              </div>

              <button 
                onClick={saveWheelSettings}
                disabled={isLoading}
                className="w-full bg-slate-900 text-white py-5 rounded-[24px] font-black shadow-xl"
              >
                {isLoading ? 'پاشەکەوت دەکرێت...' : 'Save Wheel Settings'}
              </button>
            </div>

            <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 space-y-6">
              <h3 className="font-black text-xl text-slate-800">ڕێکخستنی گشتی</h3>
              <div>
                <label className="block text-sm font-black text-slate-400 mb-2">Telegram Chat ID</label>
                <input className="input-admin w-full" value={telegramChatId} onChange={e => updateGeneralSetting('telegramChatId', e.target.value)} />
              </div>

              <div className="p-6 bg-orange-50 border border-orange-100 rounded-[32px] space-y-6">
                <h4 className="text-sm font-black text-orange-700">ImgBB API Keys</h4>
                {imgbbKeys.map((key, index) => (
                  <div key={index} className="flex flex-col gap-2 p-4 bg-white rounded-2xl border border-orange-100">
                    <div className="flex items-center justify-between">
                      <label className="text-xs font-black text-orange-600">Key {index + 1}</label>
                      <input type="radio" checked={activeIndex === index} onChange={() => setActiveIndex(index)} />
                    </div>
                    <input className="w-full p-2 bg-slate-50 rounded-lg text-xs font-mono" value={key} onChange={e => {
                      const nk = [...imgbbKeys]; nk[index] = e.target.value; setImgbbKeys(nk);
                    }} />
                  </div>
                ))}
                <button onClick={saveApiKeysToFirestore} className="w-full bg-orange-600 text-white py-4 rounded-2xl font-black">Save API Keys</button>
              </div>
            </div>
          </div>
        )}
      </div>
      <style>{`.input-admin { @apply p-5 bg-slate-50 rounded-[20px] border border-slate-100 outline-none focus:border-orange-500 focus:bg-white font-black text-slate-700 transition-all; } .no-scrollbar::-webkit-scrollbar { display: none; }`}</style>
    </div>
  );
};

import React, { useState } from 'react';
import { CartItem } from '../types';
import { TELEGRAM_BOT_TOKEN } from '../constants';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

declare var Swal: any;

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  telegramChatId: string;
  onUpdateQuantity: (id: string, delta: number, size?: 'S' | 'M' | 'L') => void;
  onRemove: (id: string, size?: 'S' | 'M' | 'L') => void;
  onClearCart: () => void;
  locationUrl: string | null;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  telegramChatId,
  onUpdateQuantity,
  onRemove,
  onClearCart,
  locationUrl: initialLocationUrl
}) => {
  const [isSending, setIsSending] = useState(false);
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [phone, setPhone] = useState('');
  const [manualAddress, setManualAddress] = useState('');
  const [note, setNote] = useState('');
  const [promoCode, setPromoCode] = useState('');
  const [userCoords, setUserCoords] = useState<{lat: number, lng: number} | null>(null);
  const [isGettingLocation, setIsGettingLocation] = useState(false);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleGetLocation = () => {
    setIsGettingLocation(true);
    if (!navigator.geolocation) {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'براوسەرەکەت پشتگیری لۆکەیشن ناکات' });
      setIsGettingLocation(false);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setUserCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        setIsGettingLocation(false);
        Swal.fire({ icon: 'success', title: 'وەرگیرا', timer: 1000, showConfirmButton: false });
      },
      () => {
        setIsGettingLocation(false);
        Swal.fire({ icon: 'error', title: 'GPS نەکراوەتەوە' });
      }
    );
  };

  const handleOrder = async () => {
    if (!phone || phone.length < 10) {
      Swal.fire({ icon: 'warning', title: 'زانیاری ناتەواو', text: 'تکایە ژمارەی مۆبایلەکەت بنووسە.' });
      return;
    }

    setIsSending(true);
    const now = new Date().toLocaleString('ku-IQ', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

    let text = `📦 **NEW ORDER - BOOM PIZZA**\n`;
    text += `━━━━━━━━━━━━━━━━━━━━\n\n`;

    text += `🍕 **ITEMS LIST:**\n`;
    cart.forEach((item) => {
      const sizeStr = item.selectedSize ? ` (${item.selectedSize})` : '';
      text += `• **${item.name}${sizeStr}** x ${item.quantity} — \`${(item.price * item.quantity).toLocaleString()} IQD\`\n`;
    });

    text += `\n━━━━━━━━━━━━━━━━━━━━\n`;
    text += `💰 **TOTAL AMOUNT: \`${total.toLocaleString()} IQD\`**\n`;
    if (promoCode) text += `🎁 **PROMO CODE: \`${promoCode.toUpperCase()}\`**\n`;
    text += `━━━━━━━━━━━━━━━━━━━━\n\n`;

    text += `👤 **CUSTOMER INFO:**\n`;
    text += `📞 Phone: \`${phone}\`\n`;
    text += `📝 Note: ${note.trim() || '_No notes_'}\n`;

    if (manualAddress.trim()) text += `🏠 Address: \`${manualAddress.trim()}\`\n`;
    if (userCoords) {
      const url = `https://www.google.com/maps?q=${userCoords.lat},${userCoords.lng}`;
      text += `📍 Google Maps: [Open Location](${url})\n`;
    }
    text += `\n⏰ Date: ${now}`;

    try {
      await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ chat_id: telegramChatId, text: text, parse_mode: "Markdown" })
      });

      await addDoc(collection(db, "orders"), {
        items: cart.map(i => `${i.quantity}x ${i.name}${i.selectedSize ? ' ('+i.selectedSize+')' : ''}`),
        total,
        promoCode,
        customerPhone: phone,
        timestamp: Date.now()
      });

      await Swal.fire({ icon: 'success', title: 'داواکارییەکەت گەیشت!', text: 'بەم زووانە پەیوەندیت پێوە دەکەین.', confirmButtonColor: '#ea580c' });
      onClearCart();
      setIsCheckingOut(false);
      onClose();
    } catch {
      Swal.fire({ icon: 'error', title: 'کێشەیەک لە ناردن هەبوو' });
    } finally {
      setIsSending(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/60 backdrop-blur-sm">
      <div className="absolute inset-0" onClick={() => { setIsCheckingOut(false); onClose(); }} />
      <div className="bg-white rounded-t-[40px] h-[85vh] w-full flex flex-col relative animate-slide-up overflow-hidden text-black">
        <div className="p-8 border-b flex justify-between items-center sticky top-0 bg-white z-10">
          <div className="flex items-center gap-3">
            {isCheckingOut && <button onClick={() => setIsCheckingOut(false)} className="p-2 bg-gray-100 rounded-xl">←</button>}
            <h2 className="text-2xl font-black">{isCheckingOut ? 'ناونیشان و گەیاندن' : 'سەبەتەکەم'}</h2>
          </div>
          <button onClick={() => { setIsCheckingOut(false); onClose(); }} className="p-3 bg-gray-100 rounded-full">✕</button>
        </div>

        <div className="flex-grow overflow-y-auto p-6">
          {!isCheckingOut ? (
            <div className="space-y-4">
              {cart.map((item, idx) => (
                <div key={idx} className="bg-gray-50 p-5 rounded-[32px] flex items-center gap-4 border border-gray-100">
                  <img src={item.img} className="w-20 h-20 rounded-3xl object-cover" />
                  <div className="flex-grow">
                    <h3 className="font-black text-slate-800">{item.name} {item.selectedSize && `(${item.selectedSize})`}</h3>
                    <div className="text-orange-600 font-bold text-sm">{(item.price * item.quantity).toLocaleString()} IQD</div>
                    <div className="flex items-center gap-4 mt-2">
                      <button onClick={() => onUpdateQuantity(item.id, -1, item.selectedSize)} className="w-10 h-10 bg-white rounded-xl border border-gray-200 font-black">-</button>
                      <span className="font-black w-6 text-center">{item.quantity}</span>
                      <button onClick={() => onUpdateQuantity(item.id, 1, item.selectedSize)} className="w-10 h-10 bg-white rounded-xl border border-gray-200 font-black">+</button>
                    </div>
                  </div>
                  <button onClick={() => onRemove(item.id, item.selectedSize)} className="text-red-400 p-2">🗑️</button>
                </div>
              ))}
            </div>
          ) : (
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-500 mr-2">ژمارەی مۆبایل</label>
                <input className="w-full p-5 bg-slate-50 rounded-[24px] border border-slate-200 outline-none font-black" value={phone} onChange={e => setPhone(e.target.value)} placeholder="0750XXXXXXX" />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-black text-orange-600 mr-2">کۆدی دیاری / داشکاندن</label>
                <input 
                  className="w-full p-5 bg-orange-50/50 rounded-[24px] border border-orange-100 outline-none font-black text-orange-600 uppercase tracking-widest placeholder:text-orange-200" 
                  value={promoCode} 
                  onChange={e => setPromoCode(e.target.value)} 
                  placeholder="BOOM-XXXX" 
                />
              </div>

              <div className="p-6 bg-slate-50 rounded-[32px] space-y-4">
                <button onClick={handleGetLocation} className={`w-full py-5 rounded-[24px] font-black border-2 transition-all ${userCoords ? 'bg-green-50 border-green-500 text-green-600' : 'bg-white border-blue-500 text-blue-600'}`}>
                  {userCoords ? 'لۆکەیشن وەرگیرا ✓' : 'ناردنی لۆکەیشن'}
                </button>
                <textarea className="w-full p-5 bg-white rounded-[24px] border border-slate-200 outline-none font-black min-h-[100px]" value={manualAddress} onChange={e => setManualAddress(e.target.value)} placeholder="ناونیشانی دەستی بنووسە..." />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-black text-slate-500 mr-2">تێبینی</label>
                <input className="w-full p-5 bg-slate-50 rounded-[24px] border border-slate-200 outline-none font-black" value={note} onChange={e => setNote(e.target.value)} placeholder="بێ بیبەر بێت..." />
              </div>
            </div>
          )}
        </div>

        <div className="p-8 border-t bg-white space-y-4 shadow-xl">
          <div className="flex justify-between items-center">
            <span className="text-gray-400 font-bold">کۆی گشتی</span>
            <span className="text-3xl font-black text-orange-600">{total.toLocaleString()} د.ع</span>
          </div>
          <button 
            disabled={cart.length === 0 || isSending} 
            onClick={() => isCheckingOut ? handleOrder() : setIsCheckingOut(true)} 
            className="w-full bg-orange-600 text-white py-6 rounded-[30px] font-black text-xl shadow-xl shadow-orange-100 active:scale-95 transition-all"
          >
            {isSending ? 'خەریکی پڕۆسەکردنە...' : isCheckingOut ? 'جێگیرکردنی داواکاری' : 'بەردەوامبوون'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { CategoryBar } from './components/CategoryBar';
import { InAppBrowserOverlay } from './components/InAppBrowserOverlay';
import { LuckyWheel } from './components/LuckyWheel';
import { Product, CartItem, ViewState, Category, OrderLog, LuckyWheelSettings } from './types';
import { DEFAULT_CATEGORIES, ADD_TO_CART_SOUND_URL } from './constants';
import { db } from './firebase';
import { collection, onSnapshot, query, orderBy, doc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('');
  const [telegramChatId, setTelegramChatId] = useState('');
  const [businessLogo, setBusinessLogo] = useState('');
  const [mainBanner, setMainBanner] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);
  const [isLocalAdmin, setIsLocalAdmin] = useState(() => sessionStorage.getItem('isAdminAuthenticated') === 'true');
  const [isInAppBrowser, setIsInAppBrowser] = useState(false);

  // Wheel States
  const [wheelSettings, setWheelSettings] = useState<LuckyWheelSettings | null>(null);
  const [showWheel, setShowWheel] = useState(false);

  useEffect(() => {
    const ua = navigator.userAgent || navigator.vendor;
    if (ua.indexOf("FBAN") > -1 || ua.indexOf("FBAV") > -1 || ua.indexOf("Messenger") > -1) setIsInAppBrowser(true);

    const unsubProducts = onSnapshot(query(collection(db, "menu"), orderBy("name")), (snap) => {
      const p: Product[] = [];
      snap.forEach(d => p.push({ id: d.id, ...d.data() } as Product));
      setProducts(p);
    });

    const unsubCategories = onSnapshot(query(collection(db, "categories"), orderBy("name")), (snap) => {
      const c: Category[] = [];
      snap.forEach(d => c.push({ id: d.id, ...d.data() } as Category));
      setCategories(c.length > 0 ? c : DEFAULT_CATEGORIES);
    });

    onSnapshot(doc(db, "settings", "general"), (d) => {
      if (d.exists()) setTelegramChatId(d.data().telegramChatId || '');
    });

    onSnapshot(doc(db, "settings", "theme"), (d) => {
      if (d.exists()) setBusinessLogo(d.data().logoUrl || '');
    });

    onSnapshot(doc(db, "settings", "banner"), (d) => {
      if (d.exists()) setMainBanner(d.data().url || '');
    });

    onSnapshot(doc(db, "settings", "lucky_wheel"), (d) => {
      if (d.exists()) {
        const settings = d.data() as LuckyWheelSettings;
        setWheelSettings(settings);
        const lastSpin = localStorage.getItem('last_spin_date');
        const today = new Date().toDateString();
        if (settings.isEnabled && lastSpin !== today) {
          setTimeout(() => setShowWheel(true), 3000);
        }
      }
    });

    onSnapshot(query(collection(db, "orders"), orderBy("timestamp", "desc")), (snap) => {
      const o: OrderLog[] = [];
      snap.forEach(d => o.push({ id: d.id, ...d.data() } as OrderLog));
      setOrderLogs(o);
    });
  }, []);

  useEffect(() => {
    if (categories.length > 0 && !selectedCategory) setSelectedCategory(categories[0].id);
  }, [categories, selectedCategory]);

  const filteredProducts = useMemo(() => {
    if (!selectedCategory) return [];
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    new Audio(ADD_TO_CART_SOUND_URL).play().catch(() => {});
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id && i.selectedSize === size);
      let finalPrice = product.price;
      if (size === 'M' && product.priceM) finalPrice = product.priceM;
      if (size === 'L' && product.priceL) finalPrice = product.priceL;

      if (existing) {
        return prev.map(i => (i.id === product.id && i.selectedSize === size) ? { ...i, quantity: i.quantity + 1, price: finalPrice } : i);
      }
      return [...prev, { ...product, price: finalPrice, quantity: 1, selectedSize: size }];
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-black overflow-x-hidden">
      {isInAppBrowser && <InAppBrowserOverlay businessLogo={businessLogo} />}

      {showWheel && wheelSettings && (
        <LuckyWheel settings={wheelSettings} onClose={() => setShowWheel(false)} />
      )}

      <Header currentView={view} onToggleAdmin={() => setView(v => v === 'MENU' ? 'ADMIN' : 'MENU')} businessLogo={businessLogo} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <div className="px-4 pt-6">
              <div className="max-w-4xl mx-auto h-48 sm:h-64 rounded-[40px] overflow-hidden shadow-2xl shadow-orange-100 bg-gray-200">
                {mainBanner ? <img src={mainBanner} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-orange-500" />}
              </div>
            </div>
            <CategoryBar categories={categories} selectedCategoryId={selectedCategory} onSelectCategory={setSelectedCategory} />
            <div className="max-w-4xl mx-auto px-4 py-8 pb-32">
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                {filteredProducts.map(p => (
                  <ProductCard 
                    key={p.id} 
                    product={p} 
                    onAddToCart={(prod, size) => addToCart(prod, size)}
                    isPizza={categories.find(c => c.id === p.category)?.name.includes('پیتزا')}
                  />
                ))}
              </div>
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} categories={categories} isSoundEnabled={true} 
            telegramChatId={telegramChatId} businessLogo={businessLogo} 
            orderLogs={orderLogs} isLocalAdmin={isLocalAdmin} onAdminAuthChange={setIsLocalAdmin} 
            mainBanner={mainBanner}
          />
        )}
      </main>

      {view === 'MENU' && cart.length > 0 && <BottomNav cart={cart} onViewCart={() => setIsCartOpen(true)} />}

      <CartModal 
        isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} 
        telegramChatId={telegramChatId} locationUrl={null}
        onUpdateQuantity={(id, delta, size) => {
          setCart(c => c.map(i => (i.id === id && i.selectedSize === size) ? {...i, quantity: Math.max(1, i.quantity + delta)} : i));
        }}
        onRemove={(id, size) => setCart(c => c.filter(i => !(i.id === id && i.selectedSize === size)))}
        onClearCart={() => setCart([])}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Product, Category, AdminSubView, OrderLog, LuckyWheelSettings } from '../types';
import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  deleteDoc, 
  doc, 
  setDoc,
  updateDoc,
  onSnapshot
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { ADMIN_PASSWORD } from '../constants';

declare var Swal: any;

interface AdminPanelProps {
  products: Product[];
  categories: Category[];
  isSoundEnabled: boolean;
  telegramChatId: string;
  businessLogo: string;
  orderLogs: OrderLog[];
  isLocalAdmin: boolean;
  onAdminAuthChange: (authenticated: boolean) => void;
  mainBanner?: string;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  categories, 
  telegramChatId,
  businessLogo,
  orderLogs,
  isLocalAdmin,
  onAdminAuthChange,
  mainBanner
}) => {
  const [passwordInput, setPasswordInput] = useState('');
  const [activeTab, setActiveTab] = useState<'DASHBOARD' | 'CATEGORIES' | 'PRODUCTS' | 'API_KEYS' | 'SITE_SETTINGS'>('DASHBOARD');

  // Loading states
  const [isActionLoading, setIsActionLoading] = useState(false);
  const [uploadType, setUploadType] = useState<string | null>(null);

  // Forms
  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  const [productForm, setProductForm] = useState({
    name: '',
    category: '',
    price: '',
    priceM: '',
    priceL: '',
    img: ''
  });

  // Settings
  const [imgbbKeys, setImgbbKeys] = useState<string[]>(['', '', '', '', '']);
  const [activeKeyIndex, setActiveKeyIndex] = useState(0);

  // Stats
  const stats = useMemo(() => ({
    products: products.length,
    categories: categories.length,
    orders: orderLogs.length,
    revenue: orderLogs.reduce((acc, o) => acc + o.total, 0)
  }), [products, categories, orderLogs]);

  useEffect(() => {
    if (isLocalAdmin) {
      const unsub = onSnapshot(doc(db, "settings", "api_keys"), (d) => {
        if (d.exists()) {
          const data = d.data();
          setImgbbKeys(data.keys || ['', '', '', '', '']);
          setActiveKeyIndex(data.activeIndex || 0);
        }
      });
      return unsub;
    }
  }, [isLocalAdmin]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      onAdminAuthChange(true);
      sessionStorage.setItem('isAdminAuthenticated', 'true');
    } else {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'وشەی نهێنی هەڵەیە!' });
    }
  };

  const uploadToImgBB = async (file: File): Promise<string | null> => {
    const key = imgbbKeys[activeKeyIndex];
    if (!key) {
      Swal.fire({ icon: 'warning', title: 'کلیل نییە', text: 'تکایە سەرەتا کلیلی ImgBB زیاد بکە.' });
      return null;
    }

    const formData = new FormData();
    formData.append('image', file);

    try {
      const res = await fetch(`https://api.imgbb.com/1/upload?key=${key}`, {
        method: 'POST',
        body: formData
      });
      const data = await res.json();
      return data.success ? data.data.url : null;
    } catch (err) {
      console.error(err);
      return null;
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, type: 'CATEGORY' | 'PRODUCT' | 'LOGO' | 'BANNER') => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadType(type);
    const url = await uploadToImgBB(file);
    setUploadType(null);

    if (url) {
      if (type === 'CATEGORY') setCategoryForm(prev => ({ ...prev, imageUrl: url }));
      if (type === 'PRODUCT') setProductForm(prev => ({ ...prev, img: url }));
      if (type === 'LOGO') await setDoc(doc(db, "settings", "theme"), { logoUrl: url }, { merge: true });
      if (type === 'BANNER') await setDoc(doc(db, "settings", "banner"), { url: url }, { merge: true });

      if (type === 'LOGO' || type === 'BANNER') {
        Swal.fire({ icon: 'success', title: 'سەرکەوتوو', text: 'وێنەکە بە سەرکەوتوویی نوێکرایەوە.', timer: 1500 });
      }
    } else {
      Swal.fire({ icon: 'error', title: 'شکستی هێنا', text: 'بارکردنی وێنەکە سەرکەوتوو نەبوو.' });
    }
  };

  const addCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!categoryForm.name || !categoryForm.imageUrl) return;
    setIsActionLoading(true);
    try {
      await addDoc(collection(db, "categories"), categoryForm);
      setCategoryForm({ name: '', imageUrl: '' });
      Swal.fire({ icon: 'success', title: 'زیادکرا', timer: 1500 });
