    if (result.isConfirmed) {
      await deleteDoc(doc(db, "categories", id));
      Swal.fire({ icon: 'success', title: 'سڕایەوە', timer: 1000 });
    }
  };

  const addProduct = async (e: React.FormEvent) => {
