                  <label className="w-full cursor-pointer bg-slate-100 hover:bg-slate-200 p-5 rounded-2xl border-2 border-dashed border-slate-300 text-center transition-all">
                    <span className="text-sm font-black text-slate-600">
                      {uploadType === 'LOGO' ? 'خەریکی بارکردنە...' : 'گۆڕینی لۆگۆ'}
                    </span>
                    <input type="file" className="hidden" accept="image/*" onChange={e => handleFileChange(e, 'LOGO')} />
                  </label>
                </div>
              </div>

              {/* Banner Section */}
              <div className="bg-white p-10 rounded-[40px] shadow-sm border border-slate-100 space-y-6">
                <h3 className="text-xl font-black flex items-center gap-3">
                  <span className="p-2 bg-blue-100 rounded-xl text-lg">📢</span> Main Banner
                </h3>
                <div className="flex flex-col items-center gap-6 py-4">
                  <div className="w-full h-32 bg-slate-50 rounded-3xl border-2 border-slate-100 overflow-hidden relative">
                    {mainBanner ? <img src={mainBanner} className="w-full h-full object-cover" /> : <div className="absolute inset-0 flex items-center justify-center text-slate-300">No Banner</div>}
                  </div>
                  <label className="w-full cursor-pointer bg-slate-100 hover:bg-slate-200 p-5 rounded-2xl border-2 border-dashed border-slate-300 text-center transition-all">
                    <span className="text-sm font-black text-slate-600">
                      {uploadType === 'BANNER' ? 'خەریکی بارکردنە...' : 'گۆڕینی باکگراوند'}
                    </span>
                    <input type="file" className="hidden" accept="image/*" onChange={e => handleFileChange(e, 'BANNER')} />
                  </label>
                </div>
              </div>

              {/* Telegram Info */}
              <div className="bg-white p-10 rounded-[40px] shadow-sm border border-slate-100 space-y-6 md:col-span-2">
                <h3 className="text-xl font-black flex items-center gap-3">
                  <span className="p-2 bg-green-100 rounded-xl text-lg">💬</span> Telegram Notifications
                </h3>
                <div className="space-y-4">
                  <div>
                    <label className="text-xs font-black text-slate-400 mr-2">Admin Chat ID</label>
                    <input 
                      className="w-full p-4 bg-slate-50 rounded-xl border border-slate-200 font-bold outline-none"
                      value={telegramChatId}
                      onChange={async e => {
                        const val = e.target.value;
                        await setDoc(doc(db, "settings", "general"), { telegramChatId: val }, { merge: true });
                      }}
                    />
                  </div>
                  <p className="text-[10px] text-slate-400 font-bold">بۆ ئەوەی داواکارییەکان بۆ تێلیگرام بێت، پێویستە Chat ID دابنێیت.</p>
                </div>
              </div>
            </div>
          </div>
        )}

      </main>

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .font-arabic { font-family: 'Noto Sans Arabic', sans-serif; }
      `}</style>
    </div>
  );
};

import React from 'react';
