              <img 
                src={category.imageUrl} 
                alt={category.name}
                className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
              />
              {selectedCategoryId === category.id && (
                <div className="absolute inset-0 bg-orange-600/5 pointer-events-none"></div>
              )}
            </div>
            <span className={`
              text-base font-black transition-all duration-300 text-center
              ${selectedCategoryId === category.id ? 'text-orange-600' : 'text-gray-700 group-hover:text-orange-500'}
