      setCategories(finalCategories);
    });

    const unsubSettings = onSnapshot(doc(db, "settings", "general"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setTelegramChatId(data.telegramChatId || '-5132542685');
      }
    });

    const unsubTheme = onSnapshot(doc(db, "settings", "theme"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setBusinessLogo(data.logoUrl || '');
      }
    });

    const unsubBanner = onSnapshot(doc(db, "settings", "banner"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setMainBanner(data.url || '');
      }
    });

    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("timestamp", "desc")), (snap) => {
      const o: OrderLog[] = [];
      snap.forEach(d => o.push({ id: d.id, ...d.data() } as OrderLog));
      setOrderLogs(o);
    });

    return () => { unsubProducts(); unsubCategories(); unsubSettings(); unsubTheme(); unsubBanner(); unsubOrders(); };
  }, []);

  useEffect(() => {
    if (categories.length > 0 && !selectedCategory) {
      setSelectedCategory(categories[0].id);
    } else if (categories.length > 0 && !categories.find(c => c.id === selectedCategory)) {
      setSelectedCategory(categories[0].id);
    }
  }, [categories, selectedCategory]);

  const filteredProducts = useMemo(() => {
    if (!selectedCategory) return [];
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    new Audio(ADD_TO_CART_SOUND_URL).play().catch(() => {});
    const category = categories.find(c => c.id === product.category);
    const isPizza = category?.name.toLowerCase().includes('pizza') || category?.name.includes('پیتزا');
    const finalSize = isPizza ? size : undefined;

    setCart(prev => {
      const existing = prev.find(i => i.id === product.id && i.selectedSize === finalSize);
      let finalPrice = product.price;
      if (isPizza) {
        if (finalSize === 'M' && product.priceM) finalPrice = product.priceM;
        if (finalSize === 'L' && product.priceL) finalPrice = product.priceL;
      }
      if (existing) {
        return prev.map(i => 
          (i.id === product.id && i.selectedSize === finalSize) 
            ? { ...i, quantity: i.quantity + 1, price: finalPrice } 
            : i
        );
      }
      return [...prev, { ...product, price: finalPrice, quantity: 1, selectedSize: finalSize }];
    });
  };

  const currentCategoryName = categories.find(c => c.id === selectedCategory)?.name || '';

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-black overflow-x-hidden" dir="rtl">
      <Header currentView={view} onToggleAdmin={() => setView(v => v === 'MENU' ? 'ADMIN' : 'MENU')} businessLogo={businessLogo} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <div className="px-4 pt-6">
              <div className="max-w-4xl mx-auto h-48 sm:h-64 rounded-[40px] overflow-hidden shadow-2xl shadow-orange-100 bg-gray-200">
                {mainBanner ? (
                  <img src={mainBanner} alt="Main Banner" className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-orange-400 to-red-500 text-white p-8">
                    <div className="text-center">
                      <h2 className="text-4xl font-black mb-2">Boom Pizza 🍕</h2>
                      <p className="font-bold opacity-80">تامێکی جیاواز لە هەموو بریتانیایەک!</p>
                    </div>
                  </div>
                )}
              </div>
            </div>

            <CategoryBar categories={categories} selectedCategoryId={selectedCategory} onSelectCategory={setSelectedCategory} />
            <div className="max-w-4xl mx-auto px-4 py-8 pb-32">
              <div className="mb-8">
                <h2 className="text-3xl font-black text-gray-900">Boom Pizza Menu</h2>
                <p className="text-gray-400 font-bold mt-1">
                  {currentCategoryName ? `بەخێربێیت، سەیری ${currentCategoryName} بکە` : 'بەخێربێیت بۆ Boom Pizza'}
                </p>
              </div>

              {categories.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[40px] shadow-sm border border-gray-100">
                  <div className="text-5xl mb-4">🍕</div>
                  <h3 className="text-2xl font-black text-slate-800">بەخێربێیت بۆ Boom Pizza</h3>
                  <p className="text-gray-400 font-bold mt-2 px-6">بەداخەوە ئێستا هیچ خواردنێک بەردەست نییە.</p>
                </div>
              ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {filteredProducts.map(p => {
                    const category = categories.find(c => c.id === p.category);
                    const isPizza = category?.name.toLowerCase().includes('pizza') || category?.name.includes('پیتزا');
                    return (
                      <ProductCard 
                        key={p.id} 
                        product={p} 
                        onAddToCart={(prod, size) => addToCart(prod, size)}
                        isPizza={isPizza}
                      />
                    );
                  })}
                </div>
              )}
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} categories={categories} isSoundEnabled={true} 
            telegramChatId={telegramChatId} businessLogo={businessLogo} 
            orderLogs={orderLogs} isLocalAdmin={isLocalAdmin} onAdminAuthChange={setIsLocalAdmin} 
            mainBanner={mainBanner}
          />
        )}
      </main>

      {view === 'MENU' && cart.length > 0 && <BottomNav cart={cart} onViewCart={() => setIsCartOpen(true)} />}

      <CartModal 
        isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} 
        telegramChatId={telegramChatId} locationUrl={locationUrl}
        onUpdateQuantity={(id, delta, size) => {
          setCart(c => c.map(i => (i.id === id && i.selectedSize === size) ? {...i, quantity: Math.max(1, i.quantity + delta)} : i));
        }}
        onRemove={(id, size) => setCart(c => c.filter(i => !(i.id === id && i.selectedSize === size)))}
        onClearCart={() => setCart([])}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { CartItem } from '../types';
import { TELEGRAM_BOT_TOKEN } from '../constants';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

declare var Swal: any;

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  telegramChatId: string;
  onUpdateQuantity: (id: string, delta: number, size?: 'S' | 'M' | 'L') => void;
  onRemove: (id: string, size?: 'S' | 'M' | 'L') => void;
  onClearCart: () => void;
  locationUrl: string | null;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  telegramChatId,
  onUpdateQuantity,
  onRemove,
  onClearCart,
  locationUrl: initialLocationUrl
}) => {
  const [isSending, setIsSending] = useState(false);
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [phone, setPhone] = useState('');
  const [manualAddress, setManualAddress] = useState('');
  const [note, setNote] = useState('');
  const [userCoords, setUserCoords] = useState<{lat: number, lng: number} | null>(null);
  const [isGettingLocation, setIsGettingLocation] = useState(false);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleGetLocation = () => {
    setIsGettingLocation(true);
    if (!navigator.geolocation) {
      Swal.fire({ 
        icon: 'error', 
        title: 'هەڵە', 
        text: 'براوسەرەکەت پشتگیری لۆکەیشن ناکات',
        confirmButtonText: 'باشە' 
      });
      setIsGettingLocation(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setUserCoords({
          lat: position.coords.latitude,
          lng: position.coords.longitude
        });
        setIsGettingLocation(false);
        Swal.fire({
          icon: 'success',
          title: 'لۆکەیشن وەرگیرا',
          text: 'شوێنەکەت بە سەرکەوتوویی تۆمارکرا',
          timer: 1500,
          showConfirmButton: false
        });
      },
      (error) => {
        setIsGettingLocation(false);
        Swal.fire({
          icon: 'error',
          title: 'GPS نەکراوەتەوە',
          text: 'تکایە لۆکەیشن (GPS) کارا بکە یان ناونیشانەکەت بە دەست بنووسە.',
          confirmButtonText: 'باشە'
        });
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  const handleOrder = async () => {
    if (cart.length === 0) {
      Swal.fire({ icon: 'warning', title: 'سەبەتە بەتاڵە', text: 'تکایە سەرەتا خواردن زیاد بکە بۆ سەبەتەکەت.', confirmButtonText: 'باشە' });
      return;
    }

    if (!phone || phone.length < 10) {
      Swal.fire({ icon: 'warning', title: 'زانیاری ناتەواو', text: 'تکایە ژمارەی مۆبایلەکەت بە دروستی بنووسە.', confirmButtonText: 'باشە' });
      return;
    }

    if (!userCoords && !manualAddress.trim()) {
      Swal.fire({ 
        icon: 'warning', 
        title: 'ناونیشان پێویستە', 
        text: 'تکایە لۆکەیشنەکەت بنێرە یان ناونیشانەکەت بە دەست بنووسە بۆ تەواوکردنی داواکارییەکە.', 
        confirmButtonText: 'باشە' 
      });
      return;
    }

    const finalChatId = telegramChatId || '-5132542685';

    setIsSending(true);

    // Receipt formatting
    const now = new Date().toLocaleString('ku-IQ', { 
      year: 'numeric', month: 'long', day: 'numeric', 
      hour: '2-digit', minute: '2-digit' 
    });

    let text = `📦 NEW ORDER - BOOM PIZZA\n`;
    text += `━━━━━━━━━━━━━━━━━━━━\n\n`;

    text += `🍕 ITEMS LIST:\n`;
    cart.forEach((item) => {
      const sizeStr = item.selectedSize ? ` (${item.selectedSize})` : '';
      const itemPrice = (item.price * item.quantity).toLocaleString();
      text += `• ${item.name}${sizeStr} x ${item.quantity} — ${itemPrice} IQD\n`;
    });

    text += `\n━━━━━━━━━━━━━━━━━━━━\n`;
    text += `💰 TOTAL AMOUNT: ${total.toLocaleString()} IQD\n`;
    text += `━━━━━━━━━━━━━━━━━━━━\n\n`;

    text += `👤 CUSTOMER INFO:\n`;
    text += `📞 Phone: ${phone}\n`;
    text += `📝 Note: ${note.trim() || 'No notes'}\n`;

    if (manualAddress.trim()) {
      text += `🏠 Address: ${manualAddress.trim()}\n`;
    }

    if (userCoords) {
      const mapsUrl = `https://www.google.com/maps?q=${userCoords.lat},${userCoords.lng}`;
      text += `📍 Location: ${mapsUrl}\n`;
    }

    text += `\n⏰ Date: ${now}`;

    try {
      // Use URLSearchParams and mode: 'no-cors' to ensure compatibility with Messenger's browser
      const params = new URLSearchParams();
      params.append('chat_id', finalChatId);
      params.append('text', text);

      await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        mode: 'no-cors', // Critical for In-App Browsers
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: params.toString()
      });

      // Firebase Log
      await addDoc(collection(db, "orders"), {
        items: cart.map(i => `${i.quantity}x ${i.name}${i.selectedSize ? ' ('+i.selectedSize+')' : ''}`),
        total,
        customerPhone: phone,
        manualAddress: manualAddress,
        customerNote: note,
        gpsLocation: userCoords ? `https://www.google.com/maps?q=${userCoords.lat},${userCoords.lng}` : null,
        timestamp: Date.now()
      });

      await Swal.fire({
        icon: 'success',
        title: 'داواکارییەکەت گەیشت!',
        text: 'سوپاس بۆ کڕینەکەت، بەم زووانە پەیوەندیت پێوە دەکەین.',
        confirmButtonText: 'باشە',
        confirmButtonColor: '#ea580c'
      });

      onClearCart();
      setIsCheckingOut(false);
      setPhone('');
      setManualAddress('');
      setNote('');
      setUserCoords(null);
      onClose();
    } catch (error: any) {
      console.error("Order error:", error);
      Swal.fire({ 
        icon: 'error', 
        title: 'هەڵەیەک ڕوویدا', 
        text: 'ببورە، کێشەیەک دروست بوو. تکایە دووبارە هەوڵبدەرەوە.', 
        confirmButtonText: 'دووبارە هەوڵبدەرەوە' 
      });
    } finally {
      setIsSending(false);
    }
  };

  const closeAndReset = () => {
    setIsCheckingOut(false);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/60 backdrop-blur-sm">
      <div className="absolute inset-0" onClick={closeAndReset} />
      <div className="bg-white rounded-t-[40px] h-[85vh] w-full flex flex-col relative animate-slide-up overflow-hidden text-black">

        {/* Header */}
        <div className="p-8 border-b flex justify-between items-center bg-white sticky top-0 z-10">
          <div className="flex items-center gap-3">
            {isCheckingOut && (
              <button onClick={() => setIsCheckingOut(false)} className="p-2 bg-gray-100 rounded-xl">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" />
                </svg>
              </button>
            )}
            <h2 className="text-2xl font-black">{isCheckingOut ? 'ناونیشان و گەیاندن' : 'سەبەتەکەم'}</h2>
          </div>
          <button onClick={closeAndReset} className="p-3 bg-gray-100 rounded-full">✕</button>
        </div>

        {/* Body */}
        <div className="flex-grow overflow-y-auto p-6">
          {!isCheckingOut ? (
            <div className="space-y-4">
              {cart.map((item, idx) => (
                <div key={`${item.id}-${item.selectedSize}-${idx}`} className="bg-gray-50 p-5 rounded-[32px] flex items-center gap-4 border border-gray-100 shadow-sm">
                  <img src={item.img} className="w-20 h-20 rounded-3xl object-cover bg-white shadow-sm" />
                  <div className="flex-grow">
                    <div className="flex items-center gap-2">
                      <h3 className="font-black text-slate-800">{item.name}</h3>
                      {item.selectedSize && (
                        <span className="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-black">{item.selectedSize}</span>
                      )}
                    </div>
                    <div className="text-orange-600 font-bold text-sm">{(item.price * item.quantity).toLocaleString()} IQD</div>
                    <div className="flex items-center gap-4 mt-2">
                      <button onClick={() => onUpdateQuantity(item.id, -1, item.selectedSize)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black flex items-center justify-center">-</button>
                      <span className="font-black text-xl w-6 text-center">{item.quantity}</span>
                      <button onClick={() => onUpdateQuantity(item.id, 1, item.selectedSize)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black flex items-center justify-center">+</button>
                    </div>
                  </div>
                  <button onClick={() => onRemove(item.id, item.selectedSize)} className="text-red-400 hover:text-red-600 font-bold p-2 transition-colors">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </div>
              ))}
              {cart.length === 0 && (
                <div className="text-center py-20">
                  <div className="text-6xl mb-4">🛒</div>
                  <div className="text-gray-400 font-black text-lg">سەبەتەکەت بەتاڵە</div>
                </div>
              )}
            </div>
          ) : (
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-500 mr-2">ژمارەی مۆبایل (پێویستە)</label>
                <input 
                  type="tel" 
                  placeholder="بۆ نموونە: 0750XXXXXXX" 
                  className="w-full p-5 bg-slate-50 rounded-[24px] border border-slate-200 outline-none focus:border-orange-500 focus:bg-white font-black transition-all"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                />
              </div>

              <div className="p-6 bg-slate-50 rounded-[32px] border border-slate-100 space-y-6">
                <div className="text-center">
                  <span className="text-xs font-black text-orange-600 uppercase tracking-wider">شێوازی گەیاندن هەڵبژێرە</span>
                </div>

                <div className="space-y-3">
                  <button 
                    onClick={handleGetLocation}
                    disabled={isGettingLocation}
                    className={`w-full flex items-center justify-center gap-3 py-5 rounded-[24px] font-black border-2 transition-all ${
                      userCoords 
                      ? 'bg-green-50 border-green-500 text-green-600' 
                      : 'bg-white border-blue-500 text-blue-600 active:scale-95'
                    }`}
                  >
                    {isGettingLocation ? (
                      <div className="w-5 h-5 border-2 border-blue-600/30 border-t-blue-600 rounded-full animate-spin"></div>
                    ) : userCoords ? (
                      <span>لۆکەیشن وەرگیرا ✓</span>
                    ) : (
                      <span>ناردنی لۆکەیشن 📍</span>
                    )}
                  </button>
                </div>

                <div className="flex items-center gap-4">
                  <div className="flex-grow h-[1px] bg-slate-200"></div>
                  <span className="text-[10px] font-black text-slate-300">یان</span>
                  <div className="flex-grow h-[1px] bg-slate-200"></div>
                </div>

                <div className="space-y-3">
                  <textarea 
                    placeholder="ناونیشانەکەت بنووسە..." 
                    className={`w-full p-5 bg-white rounded-[24px] border outline-none focus:border-orange-500 font-black transition-all min-h-[100px] ${manualAddress ? 'border-orange-200' : 'border-slate-200'}`}
                    value={manualAddress}
                    onChange={(e) => setManualAddress(e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-black text-slate-500 mr-2">تێبینی زیادە</label>
                <input 
                  type="text"
                  placeholder="بۆ نموونە: بێ بیبەر بێت..." 
                  className="w-full p-5 bg-slate-50 rounded-[24px] border border-slate-200 outline-none focus:border-orange-500 focus:bg-white font-black transition-all"
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                />
              </div>
            </div>
          )}
        </div>

        {/* Footer Actions */}
        <div className="p-8 border-t bg-white space-y-4 shadow-[0_-10px_20px_rgba(0,0,0,0.02)]">
          <div className="flex justify-between items-center mb-2">
            <span className="text-gray-400 font-bold">کۆی گشتی</span>
            <span className="text-3xl font-black text-orange-600">{total.toLocaleString()} د.ع</span>
          </div>

          {!isCheckingOut ? (
            <button 
              disabled={cart.length === 0}
              onClick={() => setIsCheckingOut(true)}
              className="w-full bg-orange-600 text-white py-6 rounded-[30px] font-black text-xl shadow-xl shadow-orange-100 active:scale-95 transition-all disabled:opacity-50"
            >
              بەردەوامبوون
            </button>
          ) : (
            <button 
              disabled={isSending || cart.length === 0 || !phone || (!userCoords && !manualAddress.trim())}
              onClick={handleOrder}
              className="w-full bg-orange-600 text-white py-6 rounded-[30px] font-black text-xl shadow-xl shadow-orange-100 active:scale-95 transition-all disabled:opacity-50"
            >
              {isSending ? 'لە پڕۆسەدایە...' : 'جێگیرکردنی داواکاری'}
            </button>
          )}
        </div>
      </div>
      <style>{`@keyframes slide-up { from { transform: translateY(100%); } to { transform: translateY(0); } } .animate-slide-up { animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1); }`}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { CategoryBar } from './components/CategoryBar';
import { Product, CartItem, ViewState, Category, OrderLog } from './types';
import { DEFAULT_CATEGORIES, ADD_TO_CART_SOUND_URL } from './constants';
import { db } from './firebase';
import { collection, onSnapshot, query, orderBy, doc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('');
  const [telegramChatId, setTelegramChatId] = useState('-5132542685'); 
  const [businessLogo, setBusinessLogo] = useState('');
  const [mainBanner, setMainBanner] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);
  const [isLocalAdmin, setIsLocalAdmin] = useState(() => sessionStorage.getItem('isAdminAuthenticated') === 'true');
  const [locationUrl, setLocationUrl] = useState<string | null>(null);

  useEffect(() => {
    if (businessLogo) {
      const appleIcon = document.getElementById('apple-icon') as HTMLLinkElement;
      const favicon = document.getElementById('favicon') as HTMLLinkElement;
      if (appleIcon) appleIcon.href = businessLogo;
      if (favicon) favicon.href = businessLogo;

      const manifest = {
        "short_name": "Boom Pizza",
        "name": "Boom Pizza - Fast Food Delivery",
        "icons": [
          { "src": businessLogo, "sizes": "192x192", "type": "image/png", "purpose": "any maskable" },
          { "src": businessLogo, "sizes": "512x512", "type": "image/png", "purpose": "any maskable" }
        ],
        "start_url": ".",
        "display": "standalone",
        "theme_color": "#ea580c",
        "background_color": "#f8fafc",
        "orientation": "portrait"
      };

      const stringManifest = JSON.stringify(manifest);
      const blob = new Blob([stringManifest], {type: 'application/json'});
      const manifestURL = URL.createObjectURL(blob);
      const manifestElement = document.getElementById('pwa-manifest') as HTMLLinkElement;
      if (manifestElement) manifestElement.setAttribute('href', manifestURL);
    }
  }, [businessLogo]);

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setLocationUrl(`https://www.google.com/maps?q=${pos.coords.latitude},${pos.coords.longitude}`),
        null, { enableHighAccuracy: true }
      );
    }

    const unsubProducts = onSnapshot(query(collection(db, "menu"), orderBy("name")), (snap) => {
      const p: Product[] = [];
      snap.forEach(d => p.push({ id: d.id, ...d.data() } as Product));
      setProducts(p);
    });

    const unsubCategories = onSnapshot(query(collection(db, "categories"), orderBy("order", "asc")), (snap) => {
      const c: Category[] = [];
      snap.forEach(d => c.push({ id: d.id, ...d.data() } as Category));
      const finalCategories = c.length > 0 ? c : DEFAULT_CATEGORIES;
      setCategories(finalCategories);
    });

    const unsubSettings = onSnapshot(doc(db, "settings", "general"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setTelegramChatId(data.telegramChatId || '-5132542685');
      }
    });

    const unsubTheme = onSnapshot(doc(db, "settings", "theme"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setBusinessLogo(data.logoUrl || '');
      }
    });

    const unsubBanner = onSnapshot(doc(db, "settings", "banner"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setMainBanner(data.url || '');
      }
    });

    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("timestamp", "desc")), (snap) => {
      const o: OrderLog[] = [];
      snap.forEach(d => o.push({ id: d.id, ...d.data() } as OrderLog));
      setOrderLogs(o);
    });

    return () => { unsubProducts(); unsubCategories(); unsubSettings(); unsubTheme(); unsubBanner(); unsubOrders(); };
  }, []);

  useEffect(() => {
    if (categories.length > 0 && !selectedCategory) {
      setSelectedCategory(categories[0].id);
    } else if (categories.length > 0 && !categories.find(c => c.id === selectedCategory)) {
      setSelectedCategory(categories[0].id);
    }
  }, [categories, selectedCategory]);

  const filteredProducts = useMemo(() => {
    if (!selectedCategory) return [];
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    new Audio(ADD_TO_CART_SOUND_URL).play().catch(() => {});
    const category = categories.find(c => c.id === product.category);
    const isPizza = category?.name.toLowerCase().includes('pizza') || category?.name.includes('پیتزا');
    const finalSize = isPizza ? size : undefined;

    setCart(prev => {
      const existing = prev.find(i => i.id === product.id && i.selectedSize === finalSize);
      let finalPrice = product.price;
      if (isPizza) {
        if (finalSize === 'M' && product.priceM) finalPrice = product.priceM;
        if (finalSize === 'L' && product.priceL) finalPrice = product.priceL;
      }
      if (existing) {
        return prev.map(i => (i.id === product.id && i.selectedSize === finalSize) ? { ...i, quantity: i.quantity + 1, price: finalPrice } : i);
      }
      return [...prev, { ...product, price: finalPrice, quantity: 1, selectedSize: finalSize }];
    });
  };

  const currentCategoryName = categories.find(c => c.id === selectedCategory)?.name || '';

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-black overflow-x-hidden" dir="rtl">
      <Header currentView={view} onToggleAdmin={() => setView(v => v === 'MENU' ? 'ADMIN' : 'MENU')} businessLogo={businessLogo} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <div className="px-4 pt-6">
              <div className="max-w-4xl mx-auto h-48 sm:h-64 rounded-[40px] overflow-hidden shadow-2xl shadow-orange-100 bg-gray-200">
                {mainBanner ? (
                  <img src={mainBanner} alt="Main Banner" className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-orange-400 to-red-500 text-white p-8">
                    <div className="text-center">
                      <h2 className="text-4xl font-black mb-2">Boom Pizza 🍕</h2>
                      <p className="font-bold opacity-80">تامێکی جیاواز لە هەموو بریتانیایەک!</p>
                    </div>
                  </div>
                )}
              </div>
            </div>

            <CategoryBar categories={categories} selectedCategoryId={selectedCategory} onSelectCategory={setSelectedCategory} />
            <div className="max-w-4xl mx-auto px-4 py-8 pb-32">
              <div className="mb-8">
                <h2 className="text-3xl font-black text-gray-900">Boom Pizza Menu</h2>
                <p className="text-gray-400 font-bold mt-1">
                  {currentCategoryName ? `بەخێربێیت، سەیری ${currentCategoryName} بکە` : 'بەخێربێیت بۆ Boom Pizza'}
                </p>
              </div>

              {categories.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[40px] shadow-sm border border-gray-100">
                  <div className="text-5xl mb-4">🍕</div>
                  <h3 className="text-2xl font-black text-slate-800">بەخێربێیت بۆ Boom Pizza</h3>
                  <p className="text-gray-400 font-bold mt-2 px-6">بەداخەوە ئێستا هیچ خواردنێک بەردەست نییە.</p>
                </div>
              ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {filteredProducts.map(p => {
                    const category = categories.find(c => c.id === p.category);
                    const isPizza = category?.name.toLowerCase().includes('pizza') || category?.name.includes('پیتزا');
                    return (
                      <ProductCard 
                        key={p.id} 
                        product={p} 
                        onAddToCart={(prod, size) => addToCart(prod, size)}
                        isPizza={isPizza}
                      />
                    );
                  })}
                </div>
              )}
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} categories={categories} isSoundEnabled={true} 
            telegramChatId={telegramChatId} businessLogo={businessLogo} 
            orderLogs={orderLogs} isLocalAdmin={isLocalAdmin} onAdminAuthChange={setIsLocalAdmin} 
            mainBanner={mainBanner}
          />
        )}
      </main>

      {view === 'MENU' && cart.length > 0 && <BottomNav cart={cart} onViewCart={() => setIsCartOpen(true)} />}

      <CartModal 
        isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} 
        telegramChatId={telegramChatId} locationUrl={locationUrl}
        onUpdateQuantity={(id, delta, size) => {
          setCart(c => c.map(i => (i.id === id && i.selectedSize === size) ? {...i, quantity: Math.max(1, i.quantity + delta)} : i));
        }}
        onRemove={(id, size) => setCart(c => c.filter(i => !(i.id === id && i.selectedSize === size)))}
        onClearCart={() => setCart([])}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { CartItem } from '../types';
import { TELEGRAM_BOT_TOKEN } from '../constants';
import { db } from '../firebase';
import { collection, addDoc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

declare var Swal: any;

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  telegramChatId: string;
  onUpdateQuantity: (id: string, delta: number, size?: 'S' | 'M' | 'L') => void;
  onRemove: (id: string, size?: 'S' | 'M' | 'L') => void;
  onClearCart: () => void;
  locationUrl: string | null;
}

export const CartModal: React.FC<CartModalProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  telegramChatId,
  onUpdateQuantity,
  onRemove,
  onClearCart,
  locationUrl: initialLocationUrl
}) => {
  const [isSending, setIsSending] = useState(false);
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [phone, setPhone] = useState('');
  const [manualAddress, setManualAddress] = useState('');
  const [note, setNote] = useState('');
  const [userCoords, setUserCoords] = useState<{lat: number, lng: number} | null>(null);
  const [isGettingLocation, setIsGettingLocation] = useState(false);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleGetLocation = () => {
    setIsGettingLocation(true);
    if (!navigator.geolocation) {
      Swal.fire({ icon: 'error', title: 'هەڵە', text: 'براوسەرەکەت پشتگیری لۆکەیشن ناکات', confirmButtonText: 'باشە' });
      setIsGettingLocation(false);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        setUserCoords({ lat: position.coords.latitude, lng: position.coords.longitude });
        setIsGettingLocation(false);
        Swal.fire({ icon: 'success', title: 'لۆکەیشن وەرگیرا', text: 'شوێنەکەت بە سەرکەوتوویی تۆمارکرا', timer: 1500, showConfirmButton: false });
      },
      () => {
        setIsGettingLocation(false);
        Swal.fire({ icon: 'error', title: 'GPS نەکراوەتەوە', text: 'تکایە لۆکەیشن کارا بکە یان ناونیشانەکەت بنووسە.', confirmButtonText: 'باشە' });
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  const handleOrder = async () => {
    if (cart.length === 0 || !phone || phone.length < 10 || (!userCoords && !manualAddress.trim())) {
      Swal.fire({ icon: 'warning', title: 'زانیاری ناتەواو', text: 'تکایە هەموو خانەکان بە دروستی پڕ بکەرەوە.', confirmButtonText: 'باشە' });
      return;
    }

    const finalChatId = '-5132542685';
    setIsSending(true);

    const now = new Date().toLocaleString('ku-IQ', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

    let text = `📦 NEW ORDER - BOOM PIZZA\n━━━━━━━━━━━━━━━━━━━━\n\n🍕 ITEMS LIST:\n`;
    cart.forEach((item) => {
      const sizeStr = item.selectedSize ? ` (${item.selectedSize})` : '';
      text += `• ${item.name}${sizeStr} x ${item.quantity} — ${(item.price * item.quantity).toLocaleString()} IQD\n`;
    });

    text += `\n━━━━━━━━━━━━━━━━━━━━\n💰 TOTAL: ${total.toLocaleString()} IQD\n━━━━━━━━━━━━━━━━━━━━\n\n`;
    text += `👤 CUSTOMER:\n📞 Phone: ${phone}\n📝 Note: ${note.trim() || 'No notes'}\n`;
    if (manualAddress.trim()) text += `🏠 Address: ${manualAddress.trim()}\n`;
    if (userCoords) text += `📍 Location: https://www.google.com/maps?q=${userCoords.lat},${userCoords.lng}\n`;
    text += `\n⏰ Date: ${now}`;

    try {
      const params = new URLSearchParams();
      params.append('chat_id', finalChatId);
      params.append('text', text);

      // Using mode: 'no-cors' to bypass strict CORS in Messenger in-app browser
      await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: params.toString()
      });

      await addDoc(collection(db, "orders"), {
        items: cart.map(i => `${i.quantity}x ${i.name}${i.selectedSize ? ' ('+i.selectedSize+')' : ''}`),
        total,
        customerPhone: phone,
        manualAddress: manualAddress,
        customerNote: note,
        gpsLocation: userCoords ? `https://www.google.com/maps?q=${userCoords.lat},${userCoords.lng}` : null,
        timestamp: Date.now()
      });

      Swal.fire({ icon: 'success', title: 'داواکارییەکەت گەیشت!', text: 'سوپاس بۆ کڕینەکەت.', confirmButtonText: 'باشە', confirmButtonColor: '#ea580c' });
      onClearCart();
      setIsCheckingOut(false);
      setPhone('');
      setManualAddress('');
      setNote('');
      setUserCoords(null);
      onClose();
    } catch (error) {
      Swal.fire({ icon: 'error', title: 'هەڵەیەک ڕوویدا', text: 'تکایە دووبارە هەوڵبدەرەوە.', confirmButtonText: 'باشە' });
    } finally {
      setIsSending(false);
    }
  };

  const closeAndReset = () => { setIsCheckingOut(false); onClose(); };
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end bg-black/60 backdrop-blur-sm">
      <div className="absolute inset-0" onClick={closeAndReset} />
      <div className="bg-white rounded-t-[40px] h-[85vh] w-full flex flex-col relative animate-slide-up overflow-hidden text-black">
        <div className="p-8 border-b flex justify-between items-center bg-white sticky top-0 z-10">
          <div className="flex items-center gap-3">
            {isCheckingOut && (
              <button onClick={() => setIsCheckingOut(false)} className="p-2 bg-gray-100 rounded-xl">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
              </button>
            )}
            <h2 className="text-2xl font-black">{isCheckingOut ? 'ناونیشان و گەیاندن' : 'سەبەتەکەم'}</h2>
          </div>
          <button onClick={closeAndReset} className="p-3 bg-gray-100 rounded-full">✕</button>
        </div>

        <div className="flex-grow overflow-y-auto p-6">
          {!isCheckingOut ? (
            <div className="space-y-4">
              {cart.map((item, idx) => (
                <div key={`${item.id}-${item.selectedSize}-${idx}`} className="bg-gray-50 p-5 rounded-[32px] flex items-center gap-4 border border-gray-100 shadow-sm">
                  <img src={item.img} className="w-20 h-20 rounded-3xl object-cover bg-white shadow-sm" />
                  <div className="flex-grow">
                    <div className="flex items-center gap-2">
                      <h3 className="font-black text-slate-800">{item.name}</h3>
                      {item.selectedSize && <span className="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-black">{item.selectedSize}</span>}
                    </div>
                    <div className="text-orange-600 font-bold text-sm">{(item.price * item.quantity).toLocaleString()} IQD</div>
                    <div className="flex items-center gap-4 mt-2">
                      <button onClick={() => onUpdateQuantity(item.id, -1, item.selectedSize)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black flex items-center justify-center">-</button>
                      <span className="font-black text-xl w-6 text-center">{item.quantity}</span>
                      <button onClick={() => onUpdateQuantity(item.id, 1, item.selectedSize)} className="w-10 h-10 bg-white border border-gray-200 rounded-2xl font-black flex items-center justify-center">+</button>
                    </div>
                  </div>
                  <button onClick={() => onRemove(item.id, item.selectedSize)} className="text-red-400 p-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                </div>
              ))}
              {cart.length === 0 && <div className="text-center py-20 text-gray-400 font-black">سەبەتەکەت بەتاڵە</div>}
            </div>
          ) : (
            <div className="space-y-6">
              <input type="tel" placeholder="ژمارەی مۆبایل" className="w-full p-5 bg-slate-50 rounded-[24px] border border-slate-200 font-black" value={phone} onChange={e => setPhone(e.target.value)} />
              <div className="p-6 bg-slate-50 rounded-[32px] border border-slate-100 space-y-4">
                <button onClick={handleGetLocation} className={`w-full py-5 rounded-[24px] font-black border-2 transition-all ${userCoords ? 'bg-green-50 border-green-500 text-green-600' : 'bg-white border-blue-500 text-blue-600'}`}>
                  {isGettingLocation ? 'چاوەڕوانبە...' : userCoords ? 'لۆکەیشن وەرگیرا ✓' : 'ناردنی لۆکەیشن 📍'}
                </button>
                <div className="text-center text-[10px] font-black text-slate-300">یان</div>
                <textarea placeholder="ناونیشانەکەت بنووسە..." className="w-full p-5 bg-white rounded-[24px] border border-slate-200 font-black min-h-[100px]" value={manualAddress} onChange={e => setManualAddress(e.target.value)} />
              </div>
              <input type="text" placeholder="تێبینی زیادە" className="w-full p-5 bg-slate-50 rounded-[24px] border border-slate-200 font-black" value={note} onChange={e => setNote(e.target.value)} />
            </div>
          )}
        </div>

        <div className="p-8 border-t bg-white space-y-4">
          <div className="flex justify-between items-center mb-2">
            <span className="text-gray-400 font-bold">کۆی گشتی</span>
            <span className="text-3xl font-black text-orange-600">{total.toLocaleString()} د.ع</span>
          </div>
          <button 
            disabled={isSending || cart.length === 0} 
            onClick={!isCheckingOut ? () => setIsCheckingOut(true) : handleOrder}
            className="w-full bg-orange-600 text-white py-6 rounded-[30px] font-black text-xl"
          >
            {isSending ? 'پڕۆسەیە...' : isCheckingOut ? 'جێگیرکردنی داواکاری' : 'بەردەوامبوون'}
          </button>
        </div>
      </div>
      <style>{`@keyframes slide-up { from { transform: translateY(100%); } to { transform: translateY(0); } } .animate-slide-up { animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1); }`}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Header } from './components/Header';
import { ProductCard } from './components/ProductCard';
import { CartModal } from './components/CartModal';
import { AdminPanel } from './components/AdminPanel';
import { BottomNav } from './components/BottomNav';
import { CategoryBar } from './components/CategoryBar';
import { Product, CartItem, ViewState, Category, OrderLog } from './types';
import { DEFAULT_CATEGORIES, ADD_TO_CART_SOUND_URL } from './constants';
import { db } from './firebase';
import { collection, onSnapshot, query, orderBy, doc } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('MENU');
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('');
  const [telegramChatId, setTelegramChatId] = useState('-5132542685'); 
  const [businessLogo, setBusinessLogo] = useState('');
  const [mainBanner, setMainBanner] = useState('');
  const [orderLogs, setOrderLogs] = useState<OrderLog[]>([]);
  const [isLocalAdmin, setIsLocalAdmin] = useState(() => sessionStorage.getItem('isAdminAuthenticated') === 'true');
  const [locationUrl, setLocationUrl] = useState<string | null>(null);

  useEffect(() => {
    if (businessLogo) {
      const appleIcon = document.getElementById('apple-icon') as HTMLLinkElement;
      const favicon = document.getElementById('favicon') as HTMLLinkElement;
      if (appleIcon) appleIcon.href = businessLogo;
      if (favicon) favicon.href = businessLogo;

      const manifest = {
        "short_name": "Boom Pizza",
        "name": "Boom Pizza - Fast Food Delivery",
        "icons": [
          { "src": businessLogo, "sizes": "192x192", "type": "image/png", "purpose": "any maskable" },
          { "src": businessLogo, "sizes": "512x512", "type": "image/png", "purpose": "any maskable" }
        ],
        "start_url": ".",
        "display": "standalone",
        "theme_color": "#ea580c",
        "background_color": "#f8fafc",
        "orientation": "portrait"
      };

      const stringManifest = JSON.stringify(manifest);
      const blob = new Blob([stringManifest], {type: 'application/json'});
      const manifestURL = URL.createObjectURL(blob);
      const manifestElement = document.getElementById('pwa-manifest') as HTMLLinkElement;
      if (manifestElement) manifestElement.setAttribute('href', manifestURL);
    }
  }, [businessLogo]);

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setLocationUrl(`https://www.google.com/maps?q=${pos.coords.latitude},${pos.coords.longitude}`),
        null, { enableHighAccuracy: true }
      );
    }

    const unsubProducts = onSnapshot(query(collection(db, "menu"), orderBy("name")), (snap) => {
      const p: Product[] = [];
      snap.forEach(d => p.push({ id: d.id, ...d.data() } as Product));
      setProducts(p);
    });

    const unsubCategories = onSnapshot(query(collection(db, "categories"), orderBy("order", "asc")), (snap) => {
      const c: Category[] = [];
      snap.forEach(d => c.push({ id: d.id, ...d.data() } as Category));
      const finalCategories = c.length > 0 ? c : DEFAULT_CATEGORIES;
      setCategories(finalCategories);
    });

    const unsubSettings = onSnapshot(doc(db, "settings", "general"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setTelegramChatId(data.telegramChatId || '-5132542685');
      }
    });

    const unsubTheme = onSnapshot(doc(db, "settings", "theme"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setBusinessLogo(data.logoUrl || '');
      }
    });

    const unsubBanner = onSnapshot(doc(db, "settings", "banner"), (d) => {
      if (d.exists()) {
        const data = d.data();
        setMainBanner(data.url || '');
      }
    });

    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("timestamp", "desc")), (snap) => {
      const o: OrderLog[] = [];
      snap.forEach(d => o.push({ id: d.id, ...d.data() } as OrderLog));
      setOrderLogs(o);
    });

    return () => { unsubProducts(); unsubCategories(); unsubSettings(); unsubTheme(); unsubBanner(); unsubOrders(); };
  }, []);

  useEffect(() => {
    if (categories.length > 0 && !selectedCategory) {
      setSelectedCategory(categories[0].id);
    } else if (categories.length > 0 && !categories.find(c => c.id === selectedCategory)) {
      setSelectedCategory(categories[0].id);
    }
  }, [categories, selectedCategory]);

  const filteredProducts = useMemo(() => {
    if (!selectedCategory) return [];
    return products.filter(p => p.category === selectedCategory);
  }, [products, selectedCategory]);

  const addToCart = (product: Product, size?: 'S' | 'M' | 'L') => {
    new Audio(ADD_TO_CART_SOUND_URL).play().catch(() => {});
    const category = categories.find(c => c.id === product.category);
    const isPizza = category?.name.toLowerCase().includes('pizza') || category?.name.includes('پیتزا');
    const finalSize = isPizza ? size : undefined;

    setCart(prev => {
      const existing = prev.find(i => i.id === product.id && i.selectedSize === finalSize);
      let finalPrice = product.price;
      if (isPizza) {
        if (finalSize === 'M' && product.priceM) finalPrice = product.priceM;
        if (finalSize === 'L' && product.priceL) finalPrice = product.priceL;
      }
      if (existing) {
        return prev.map(i => (i.id === product.id && i.selectedSize === finalSize) ? { ...i, quantity: i.quantity + 1, price: finalPrice } : i);
      }
      return [...prev, { ...product, price: finalPrice, quantity: 1, selectedSize: finalSize }];
    });
  };

  const currentCategoryName = categories.find(c => c.id === selectedCategory)?.name || '';

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-black overflow-x-hidden" dir="rtl">
      <Header currentView={view} onToggleAdmin={() => setView(v => v === 'MENU' ? 'ADMIN' : 'MENU')} businessLogo={businessLogo} />

      <main className="flex-grow">
        {view === 'MENU' ? (
          <>
            <div className="px-4 pt-6">
              <div className="max-w-4xl mx-auto h-48 sm:h-64 rounded-[40px] overflow-hidden shadow-2xl shadow-orange-100 bg-gray-200">
                {mainBanner ? (
                  <img src={mainBanner} alt="Main Banner" className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-orange-400 to-red-500 text-white p-8">
                    <div className="text-center">
                      <h2 className="text-4xl font-black mb-2">Boom Pizza 🍕</h2>
                      <p className="font-bold opacity-80">تامێکی جیاواز لە هەموو بریتانیایەک!</p>
                    </div>
                  </div>
                )}
              </div>
            </div>

            <CategoryBar categories={categories} selectedCategoryId={selectedCategory} onSelectCategory={setSelectedCategory} />
            <div className="max-w-4xl mx-auto px-4 py-8 pb-32">
              <div className="mb-8">
                <h2 className="text-3xl font-black text-gray-900">Boom Pizza Menu</h2>
                <p className="text-gray-400 font-bold mt-1">
                  {currentCategoryName ? `بەخێربێیت، سەیری ${currentCategoryName} بکە` : 'بەخێربێیت بۆ Boom Pizza'}
                </p>
              </div>

              {categories.length === 0 ? (
                <div className="text-center py-20 bg-white rounded-[40px] shadow-sm border border-gray-100">
                  <div className="text-5xl mb-4">🍕</div>
                  <h3 className="text-2xl font-black text-slate-800">بەخێربێیت بۆ Boom Pizza</h3>
                  <p className="text-gray-400 font-bold mt-2 px-6">بەداخەوە ئێستا هیچ خواردنێک بەردەست نییە.</p>
                </div>
              ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {filteredProducts.map(p => {
                    const category = categories.find(c => c.id === p.category);
                    const isPizza = category?.name.toLowerCase().includes('pizza') || category?.name.includes('پیتزا');
                    return (
                      <ProductCard 
                        key={p.id} 
                        product={p} 
                        onAddToCart={(prod, size) => addToCart(prod, size)}
                        isPizza={isPizza}
                      />
                    );
                  })}
                </div>
              )}
            </div>
          </>
        ) : (
          <AdminPanel 
            products={products} categories={categories} isSoundEnabled={true} 
            telegramChatId={telegramChatId} businessLogo={businessLogo} 
            orderLogs={orderLogs} isLocalAdmin={isLocalAdmin} onAdminAuthChange={setIsLocalAdmin} 
            mainBanner={mainBanner}
          />
        )}
      </main>

      {view === 'MENU' && cart.length > 0 && <BottomNav cart={cart} onViewCart={() => setIsCartOpen(true)} />}

      <CartModal 
        isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} 
        telegramChatId={telegramChatId} locationUrl={locationUrl}
        onUpdateQuantity={(id, delta, size) => {
          setCart(c => c.map(i => (i.id === id && i.selectedSize === size) ? {...i, quantity: Math.max(1, i.quantity + delta)} : i));
        }}
        onRemove={(id, size) => setCart(c => c.filter(i => !(i.id === id && i.selectedSize === size)))}
        onClearCart={() => setCart([])}
      />
    </div>
  );
};

